local config = {
  ui_story_5071_50710101_1_dialog_content = "<size=45>으아아악──!</size>",
  ui_story_5071_50710101_2_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_5071_50710101_3_dialog_content = "......",
  ui_story_5071_50710101_4_dialog_content = "으윽... 콜록...",
  ui_story_5071_50710101_5_dialog_content = "안 돼...",
  ui_story_5071_50710101_6_dialog_content = "듣자 하니 그놈이 전부 죽였다면서?!",
  ui_story_5071_50710101_7_dialog_content = "그놈 혼자 <color=#FFB400>센트리 폰드</color>에서 살아 나갔어. 그러니 틀림없겠지.",
  ui_story_5071_50710101_8_dialog_content = "믿을 수가 없군... 권력을 얻기 위해서 가장 가까운 자기 형제까지 저버리다니...",
  ui_story_5071_50710101_9_dialog_content = "정말... 그런 놈에게 우리 움브라톤의 미래를 맡겨도 되는 건가?",
  ui_story_5071_50710101_10_dialog_content = "......",
  ui_story_5071_50710101_11_dialog_content = "넌...",
  ui_story_5071_50710101_12_dialog_content = "이제...",
  ui_story_5071_50710101_13_dialog_content = "<size=50>만족하나?</size>",
  ui_story_5071_50710101_14_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5071_50710101_15_dialog_content = "──!!!",
  ui_story_5071_50710101_16_dialog_content = "(...그림자가 된 자 또한 그림자에 삼킬 위험이 있는 법.)",
  ui_story_5071_50710101_17_dialog_content = "(그림자에 가려진 것은 과거뿐만이 아니었단 말인가... 내 형제여.)",
  ui_story_5071_50710101_18_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5071_50710101_19_dialog_content = "아버님, 베델이에요.",
  ui_story_5071_50710101_20_dialog_content = "들어와라.",
  ui_story_5071_50710101_21_dialog_content = "네. 아버님, 준비는...",
  ui_story_5071_50710101_22_dialog_content = "......",
  ui_story_5071_50710101_23_dialog_content = "...아버님? 괜찮으세요? 그렇게 피곤해하시는 모습은 처음 보는데요...",
  ui_story_5071_50710101_24_dialog_content = "하하. 아무리 술을 좋아해도 과음은 곤란하지.\n나도 이제 이런 문제를 신경 쓸 나이가 된 모양이군.",
  ui_story_5071_50710101_25_dialog_content = "...그런 농담은 하지 마세요.",
  ui_story_5071_50710101_26_dialog_content = "좋다, 농담이라 해 두자고. 본론부터 말해 봐라.",
  ui_story_5071_50710101_27_dialog_content = "네, 출발 준비는 끝났어요.",
  ui_story_5071_50710101_28_dialog_content = "쌍사성으로 통하는 도로 수리는 잘되고 있는 모양이군. 암귀의 습격도 드물고 말이야.",
  ui_story_5071_50710101_29_dialog_content = "하지만 우리 그림자의 눈이 닿지 않는 곳이다. 방심해선 안 된다.",
  ui_story_5071_50710101_30_dialog_content = "물론 너라면 그쪽 「손님」과의 회담을 성사시켜 줄 거라 믿는다.",
  ui_story_5071_50710101_31_dialog_content = "절대 아버님을 실망시키지 않을게요.",
  ui_story_5071_50710101_32_dialog_content = "베델, 넌 총상회의 회장으로서 움브라톤에만 책임을 다하면 된다.",
  ui_story_5071_50710101_33_dialog_content = "아버님...",
  ui_story_5071_50710101_34_dialog_content = "되었다, 나도 이제 나갈 때가 됐으니 이참에 배웅해 주마.",
  ui_story_5071_50710101_35_dialog_content = "......",
  ui_story_5071_50710101_36_dialog_content = "(그림자 속에서 날아올라 자유롭게 하늘을 누비는 상회...)",
  ui_story_5071_50710101_37_dialog_content = "(<color=#FFB400>당신의 꿈</color>이... 정말 이뤄진 건가요?)",
  ui_story_5071_50710101_38_dialog_content = "<color=#e8d9bb>찰칵!</color>",
  ui_story_5071_50710101_39_dialog_content = "틀림없어요! 특종 냄새가 확 난다니까요!",
  ui_story_5071_50710101_40_dialog_content = "음?",
  ui_story_5071_50710101_41_dialog_content = "안녕하세요, 저는 《데일리 스쿠프 속보》의 기자 브랜디라고 하는데요!",
  ui_story_5071_50710101_42_dialog_content = "이번에 공중상회에서 제조한 초대형 비공정인 <color=#FFB400>「부유 비공정」</color>에 대해 어떻게 생각하십니까?",
  ui_story_5071_50710101_43_dialog_content = "대답하고 싶지 않네요.",
  ui_story_5071_50710101_44_dialog_content = "...시작부터 취재 거부인가요? 역시 비즈니스 세계의 거물들은 상대하기 힘들다니까요.",
  ui_story_5071_50710101_45_dialog_content = "뭐, 괜찮아요. 마침 좋은 취잿감을 찾았으니까요...",
  ui_story_5071_50710101_46_dialog_content = "PlayerName 씨! 여기요! 여길 보세요!",
  ui_story_5071_50710101_47_dialog_content = "<color=#e8d9bb>찰칵!</color>",
  ui_story_5071_50710101_48_dialog_content = "PlayerName 씨도 오늘 <color=#FFB400>초도비행 기념식</color>에 초대받으셨나요?\n부유 비공정에 대한 감상평을 들을 수 있을까요?",
  ui_story_5071_50710101_49_dialog_content = "친숙하게 느껴져.",
  ui_story_5071_50710101_50_dialog_content = "사용되는 기술은 콜로서스랑 다르지만, 이 비공정도 마찬가지로 하늘을 나는 거대한 물건이니까.",
  ui_story_5071_50710101_51_dialog_content = "대단한 것 같아.",
  ui_story_5071_50710101_52_dialog_content = "나도 지금까진 소형 비공정밖에 못 봤거든.\n설마 샤엘 씨가 상회 통째로 이동할 수 있는 거대한 비공정을 만들 줄은 몰랐어...",
  ui_story_5071_50710101_53_dialog_content = "확실히 비공정 중에서는 대단한 편이지만,\nPlayerName 씨의 스카이워커호보다는 작지 않나요?",
  ui_story_5071_50710101_54_dialog_content = "그거야 그렇긴 한데...\n근데 크기로 따지면 전에 콘서트를 열었던 그 칸타토르호랑은 비슷하지 않나?",
  ui_story_5071_50710101_55_dialog_content = "그렇죠, 그럼 이걸로 내일 신문의 1면을 장식할 기사는 정해졌네요!",
  ui_story_5071_50710101_56_dialog_content = "「아이테르 공개 발언! 부유 비공정도 스카이워커호에 비하면 아무것도 아냐」!",
  ui_story_5071_50710101_57_dialog_content = "잠깐만! 내가 언제 그런 말을 했는데?!",
  ui_story_5071_50710101_58_dialog_content = "<color=#e8d9bb>치지지직──</color>",
  ui_story_5071_50710101_59_dialog_content = "「상처도, 실패도 두려워하지 마. 노력한다면 반드시 행운이 따라올 거야!」",
  ui_story_5071_50710101_60_dialog_content = "여러분~ 오랜만이야! 다들 잘─ 지─냈─어─?",
  ui_story_5071_50710101_61_dialog_content = "어...? 움브라톤 인기 아이돌 골디 아냐?!\n골디를 게스트로 부르다니, 역시 공중상회는 대단하네!",
  ui_story_5071_50710101_62_dialog_content = "몰랐어요? 골디를 인기 스타로 키운 게 바로 공중상회의 샤엘 회장님이잖아요!",
  ui_story_5071_50710101_63_dialog_content = "공중상회는 엔터테인먼트 업계까지 손을 뻗은 건가?\n샤엘 회장님은 대체 얼마나 많은 사업을 하고 있는 거지...?",
  ui_story_5071_50710101_64_dialog_content = "아이돌이니 비공정이니, 그래봤자 대중에 영합하는 구경거리일 뿐이죠...\n섀도우마스터가 참석하는 자리가 아니었으면 전 오지도 않았을 겁니다.",
  ui_story_5071_50710101_65_dialog_content = "여러분! 초도비행 기념식이 곧 시작될 거예요~",
  ui_story_5071_50710101_66_dialog_content = "그전에 모두에게 들려줄 제 신곡을 준비했답니다! 제목은──",
  ui_story_5071_50710101_67_dialog_content = "<size=45>《손 닿을 곳에 있는 빛》!</size>",
  ui_story_5071_50710101_68_dialog_content = "모두 함께 바람을 타고 날아올라 하늘 끝까지 닿아보는 거예요!",
  ui_story_5071_50710101_69_dialog_content = "♪끝없는 하늘, 구름이 걷히면 보이는 희망♪\n♪꿈은 지평선 저편, 아침 해와 함께 올라가 보자♪",
  ui_story_5071_50710101_70_dialog_content = "♪날개를 활짝 펴고 푸른 하늘로 날아올라♪\n♪손 닿을 곳에서 꿈은 눈부시게 빛날 테니까♪",
  ui_story_5071_50710101_71_dialog_content = "(역시 골디라니까... 방금 전까지 웅성거리던 손님들이\n골디의 노랫소리에 이끌려 고개를 끄덕이고 있어.)",
  ui_story_5071_50710101_72_dialog_content = "(...그나마 골디 팬클럽이 못 와서 망정이지, 안 그랬으면 함성소리에 내 고막이 찢어졌겠어...)",
  ui_story_5071_50710101_73_dialog_content = "(샤엘 씨가 초대한 손님들은 대체 어떤 대단한 사람들인 걸까...)",
  ui_story_5071_50710101_74_dialog_content = "오, 오셨다! 섀도우마스터다! 얼른 가 보자──!",
  ui_story_5071_50710101_75_dialog_content = "(이스타반 씨도 이번 행사에 오신 건가? 평소엔 거의 없던 일 아닌가...)",
  ui_story_5071_50710101_76_dialog_content = "1분만 더 늦었으면 커팅식이 시작됐을 거예요.\n역시 섀도우마스터는 늘 제시간에 맞춰 나타나신다니까요.",
  ui_story_5071_50710101_77_dialog_content = "최고의 타이밍에 모습을 드러내는 건 비즈니스 행사의 요령이지.\n다 샤엘 회장에게 배운 것 아니겠나.",
  ui_story_5071_50710101_78_dialog_content = "섀도우마스터! 이런 성대한 자리에서 만나 뵙게 되어 정말 영광입니다!",
  ui_story_5071_50710101_79_dialog_content = "조, 존귀하신 섀도우마스터... 호, 혹시 절 기억하시나요?",
  ui_story_5071_50710101_80_dialog_content = "섀도우마스터, 전에 따로 뵙고 싶다고 부탁을 드렸었는데, 혹시 제 편지를 보셨는지요?",
  ui_story_5071_50710101_81_dialog_content = "섀도우마스터! 저도... 저기...! 섀도우마스터...!",
  ui_story_5071_50710101_82_dialog_content = "신사 숙녀 여러분, 섀도우마스터께서는 오늘 특별히 시간을 내셔서\n이 부유 비공정에서 여러분을 만나러 오셨습니다.",
  ui_story_5071_50710101_83_dialog_content = "하지만 그 행운은 어디까지나 사전에 약속을 잡으신 분께만 주어지는 것이랍니다.",
  ui_story_5071_50710101_84_dialog_content = "지금은 우선 무대에서 열창 중인 아이돌 아가씨께 주목해 주시는 게 어떻겠습니까?",
  ui_story_5071_50710101_85_dialog_content = "섀도우마스터와 만나는 데 그런 번거로운 규칙이 있는 줄은 몰랐네요.",
  ui_story_5071_50710101_86_dialog_content = "......",
  ui_story_5071_50710101_87_dialog_content = "미안해요, 제 소개가 늦었네요. 대륙상회 회장 한스티라고 해요.\n첫 방문이라 아직 움브라톤의 룰을 잘 몰라서요. 다들 마음 상하는 일이 없었으면 좋겠네요.",
  ui_story_5071_50710101_88_dialog_content = "대륙상회의... 한스티 회장?! 절대 공개석상에 모습을 드러내지 않는다고 들었는데...\n역시 샤엘 회장님... 아니지... 섀도우마스터의 힘인가...",
  ui_story_5071_50710101_89_dialog_content = "대륙상회? 움브라톤에 그런 상회가 있었어요?",
  ui_story_5071_50710101_90_dialog_content = "최근 움브라톤 밖의 마을에는 대부분 대륙상회가 전개하는 사업이 있습니다.\n움브라톤에 진출한 지는 얼마 안 됐지만, 발전 속도가 심상치 않죠!",
  ui_story_5071_50710101_91_dialog_content = "반가워요, 한스티 씨. 정말 올 줄은 몰랐는데 말이에요.",
  ui_story_5071_50710101_92_dialog_content = "이번에 공중상회에선 움브라톤 전역의 이름난 상회 회장은 모두 초대했죠?\n이런 기회를 어떻게 놓칠 수가 있겠어요?",
  ui_story_5071_50710101_93_dialog_content = "게다가 좀처럼 모습을 드러내지 않는 섀도우마스터도 오신다길래,\n꼭 이번 기회에 뵙고 싶었거든요.",
  ui_story_5071_50710101_94_dialog_content = "참, 당신이 샤엘 씨였군요. <color=#FFB400>공중상회</color>의 수장, 제가 「우러러볼」 수밖에 없는 존재 말이죠.",
  ui_story_5071_50710101_95_dialog_content = "한스티 씨는 농담도 참 잘하시네요.",
  ui_story_5071_50710101_96_dialog_content = "<color=#FFB400>대륙상회</color>의 사업 범위는 아스트라 전역에 퍼져 있잖아요. 하늘과 땅은 공존하는 법이죠.",
  ui_story_5071_50710101_97_dialog_content = "이 비공정, 괜찮네요. 마음에 들어요.",
  ui_story_5071_50710101_98_dialog_content = "한스티 씨도 마음에 드신다니, 공중상회의 영광이에요.",
  ui_story_5071_50710101_99_dialog_content = "그럼 섀도우마스터, 제게 단독 면담 기회를 주시겠어요?",
  ui_story_5071_50710101_100_dialog_content = "한스티 씨, 죄송합니다만──",
  ui_story_5071_50710101_101_dialog_content = "귀여운 문어야, 내가 지금 섀도우마스터에게 이야기하고 있잖니?",
  ui_story_5071_50710101_102_dialog_content = "......",
  ui_story_5071_50710101_103_dialog_content = "한스티 회장, 제안은 고려해 두도록 하지.",
  ui_story_5071_50710101_104_dialog_content = "고마워요, 그럼 좋은 소식 기다리고 있을게요.",
  ui_story_5071_50710101_105_dialog_content = "클레이튼, 내 일정에서 한스티 회장과 면담할 시간을 조율해라.",
  ui_story_5071_50710101_106_dialog_content = "...네, 분부대로 하겠습니다.",
  ui_story_5071_50710101_107_dialog_content = "(어머? 섀도우마스터가 저런 경박한 여자를 위해 자기가 세운 규칙을 어기다니, 무슨 일일까?)",
  ui_story_5071_50710101_108_dialog_content = "PlayerName, 언제까지 구석에 머물 생각인가.",
  ui_story_5071_50710101_109_dialog_content = "아, 이스타반 씨... 안녕하세요!\n아깐 다들 바쁜 것 같아서 인사드릴 틈이 안 보이더라구요.",
  ui_story_5071_50710101_110_dialog_content = "따라와라, 이제 우리 차례가 됐다.",
  ui_story_5071_50710101_111_dialog_content = "엥?",
  ui_story_5071_50710101_112_dialog_content = "제 신곡이 마음에 들었으면 좋겠어요! 그럼 다음은 우리의 귀빈들을 모실 차례네요!",
  ui_story_5071_50710101_113_dialog_content = "섀도우마스터 이스타반 씨, 공중상회 회장 샤엘 씨, 아스트라 대륙의 귀빈 PlayerName 씨가 부유 비공정의 초도비행을 기념하는 테이프 커팅식을 진행하실 거예요!",
  ui_story_5071_50710101_114_dialog_content = "이런 절차가 있었는지 전혀 몰랐는데요...",
  ui_story_5071_50710101_115_dialog_content = "후훗, 긴장할 거 없어, 달링. 눈앞의 리본을 가위로 자르기만 하면 되는걸.",
  ui_story_5071_50710101_116_dialog_content = "<color=#e8d9bb>서걱──</color>",
  ui_story_5071_50710101_117_dialog_content = "이 부유 비공정은 샤엘 씨의 공중상회가 투자해 만든, 관광, 쇼핑, 레저, 휴양을\n모두 즐길 수 있는 초대형 비공정이에요.",
  ui_story_5071_50710101_118_dialog_content = "이제 앞으로는 저 같은 평범한 오로리안도 아이테르처럼\n하늘 위에서 휴식과 쇼핑을 즐길 수 있게 된 거죠!",
  ui_story_5071_50710101_119_dialog_content = "오늘 부유 비공정이 이륙하면 움브라톤 상공을 한 바퀴 돌고,\n밤엔 불꽃놀이 행사로 오늘을 축하할 거예요! 생각만 해도 로맨틱하죠~?",
  ui_story_5071_50710101_120_dialog_content = "대신 여러분도 풍경에만 빠져 있지 말고, 비공정에서 개최되는 다양한 이벤트에도 참여해 주세요!",
  ui_story_5071_50710101_121_dialog_content = "저 골디의 악수회, 움브라톤 알리우드 영화 특별 상영회,\n그리고 역사상 가장 투명하고 편리한 「부유 경매」도 개최될 거거든요!",
  ui_story_5071_50710101_122_dialog_content = "그럼 여러분, 같이 카운트다운 부탁드려요──",
  ui_story_5071_50710101_123_dialog_content = "3──",
  ui_story_5071_50710101_124_dialog_content = "2──",
  ui_story_5071_50710101_125_dialog_content = "1──!",
  ui_story_5071_50710101_126_dialog_content = "부유 비공정──",
  ui_story_5071_50710101_127_dialog_content = "<size=50>이륙──!</size>",
  ui_story_5071_50710101_128_dialog_content = "오! 이륙한다! 진짜 날았어!",
  ui_story_5071_50710101_129_dialog_content = "비공정 처음 타본 사람처럼 놀라기는. 내가 백야성에 있을 땐 이 정도 경치는 매일 봤다고.",
  ui_story_5071_50710101_130_dialog_content = "백야성은 좋은 곳이겠지만, 어쨌든 그 섬은 움직이질 않잖아요.\n아무튼 전 샤엘 회장님 투자 감각이 정말 뛰어나다고 생각해요.",
  ui_story_5071_50710101_131_dialog_content = "(확실히 뛰어나지.)",
  ui_story_5071_50710101_132_dialog_content = "(하지만... 하늘을 나는 것들은 모두...)",
  ui_story_5071_50710101_X132_dialog_content = "(언젠가는 땅에 떨어지기 마련이야.)",
  ui_story_5071_50710201_1_dialog_content = "<color=#e8d9bb>부유 비공정, 호화 객실</color>",
  ui_story_5071_50710201_2_dialog_content = "존경하는 섀도우마스터, 오늘에서야 드디어 감사 인사를 드릴 수 있게 됐네요...",
  ui_story_5071_50710201_3_dialog_content = "섀도우마스터께서 소개해 주신 덕분에 제 아들이 드디어\n꿈에 그리던 백야성 유학을 가게 됐어요!",
  ui_story_5071_50710201_4_dialog_content = "하하, 그거 정말 기분 좋은 소식이로군.",
  ui_story_5071_50710201_5_dialog_content = "당신 아들은 머리가 좋고, 자기 생각이 잘 선 아이지.\n유학을 갈 수 있었던 것도 모두 자기 노력의 결과다.",
  ui_story_5071_50710201_6_dialog_content = "헌데 무슨 다른 걱정거리라도 있는 건가.",
  ui_story_5071_50710201_7_dialog_content = "그, 그게... 혹시라도 아들이 귀족 도련님들한테 괴롭힘이라도 당할까 걱정이 돼서요...",
  ui_story_5071_50710201_8_dialog_content = "아, 무슨 바보 같은 얘기를... 죄송해요. 섀도우마스터... 제가 괜한 말을 했네요.",
  ui_story_5071_50710201_9_dialog_content = "걱정하는 것도 이해할 수 있다. 당신 아들은 뛰어난 재능이 있지.",
  ui_story_5071_50710201_10_dialog_content = "그가 무사히 돌아와 보고 배운 것을 활용해 움브라톤에 학교를 여는 건\n그 누구보다도 내가 바라는 일이다.",
  ui_story_5071_50710201_11_dialog_content = "내가 약속하지. 당신이 걱정할 만한 일은 결코 일어나지 않는다.",
  ui_story_5071_50710201_12_dialog_content = "그렇게 말씀해 주시니까 저도 이제야 안심이 되네요!",
  ui_story_5071_50710201_13_dialog_content = "이건 저희 집에서 새로 만든 와인인데... 부디 사양하지 말고 받아주세요!\n귀중한 시간을 저한테 내주셔서 정말 감사합니다...",
  ui_story_5071_50710201_14_dialog_content = "신경 쓰지 않아도 된다. 그럼 다음에 다시 만나지.",
  ui_story_5071_50710201_15_dialog_content = "<color=#e8d9bb>부유 비공정, 골디의 악수회 현장</color>",
  ui_story_5071_50710201_16_dialog_content = "PlayerName, 항상 응원해 줘서 고마워!",
  ui_story_5071_50710201_17_dialog_content = "네 기대에 부응할 수 있도록 앞으로도 더 멋진 음악을 만들게!",
  ui_story_5071_50710201_18_dialog_content = "응! 역시 골디 넌 하늘이랑 인연이 있다니까. 마침 오늘 신곡도...",
  ui_story_5071_50710201_19_dialog_content = "저기요! 한 사람당 1분씩 아닌가요?! 앞의 사람 시간 안 지났어요?!",
  ui_story_5071_50710201_20_dialog_content = "헤헷, 미안, PlayerName. 그럼 다음에 시간 나면 사무실에 놀러 와 줘~",
  ui_story_5071_50710201_21_dialog_content = "골디! 골디! 나랑도 더 얘기해 줘!",
  ui_story_5071_50710201_22_dialog_content = "(그나저나 골디도 참, 이 짧은 시간에 이렇게 잔뜩 팬을 만들다니...)",
  ui_story_5071_50710201_23_dialog_content = "(아는 사람들은 다들 바쁜 것 같고... 혼자 구경이나 할까?)",
  ui_story_5071_50710201_24_dialog_content = "아, 아직 절 기억하시는지요... 옛날에 섀도우마스터의 옆집에 살던 사람입니다!",
  ui_story_5071_50710201_25_dialog_content = "전에 섀도우마스터의 양친께서 별세하셨을 때...\n섀도우마스터가 안 계셔서 제가 대신 두 분 장례를 도와드렸었지요...",
  ui_story_5071_50710201_26_dialog_content = "두 분이 안식을 취할 수 있게 도와준 것은 고맙게 생각하고 있다.",
  ui_story_5071_50710201_27_dialog_content = "아, 아닙니다... 다만 이번엔 저도 섀도우마스터의 도움이 절실하게 필요합니다!",
  ui_story_5071_50710201_28_dialog_content = "전 섀도우마스터 덕분에 그동안 잡화점을 여러 개 차릴 수 있었지요.\n물론 공중상회에는 비할 수 없지만, 나름대로 이름이 나 있습니다.",
  ui_story_5071_50710201_29_dialog_content = "그런데 최근 인근의 상인들이 손을 잡고 저희 가게를 밀어내고 있어서...\n결국 파산 직전까지 몰린 상황입니다.",
  ui_story_5071_50710201_30_dialog_content = "도저히 어떻게 해야 할지 답이 보이질 않아서... 이렇게 부탁을 드리러 왔습니다...",
  ui_story_5071_50710201_31_dialog_content = "내게 뭘 원하는가, 저들을 처리해 주길 원하는 건가?",
  ui_story_5071_50710201_32_dialog_content = "그, 그래 주실 수 있는 겁니까?",
  ui_story_5071_50710201_33_dialog_content = "그것보다 왜 총상회엔 가입하지 않았지?\n합법적인 사업을 하고 있다면 총상회도 여러 측면에서 당신을 도왔을 텐데.",
  ui_story_5071_50710201_34_dialog_content = "그, 그게... 총상회에 가입하면 반드시 고액의 회비를 내야 한다고 들어서...",
  ui_story_5071_50710201_35_dialog_content = "총상회에 들어가 본 적도 없고, 알아본 적도 없으면서 진상을 어떻게 알 수 있지?",
  ui_story_5071_50710201_36_dialog_content = "...알겠습니다! 분명히 놈들이 절 속인 모양이군요!",
  ui_story_5071_50710201_37_dialog_content = "그럼... 지금이라도 총상회에 가입할 수 있을까요?",
  ui_story_5071_50710201_38_dialog_content = "나는 총상회 회장이 아니다. 하지만 이것만은 말해줄 수 있지.\n총상회의 문은 누구에게든지 언제나 열려 있다.",
  ui_story_5071_50710201_39_dialog_content = "날 믿어라. 이제서야 결단을 내린 것을 후회하게 될 테니.",
  ui_story_5071_50710201_40_dialog_content = "감사합니다! 섀도우마스터!\n앞으로도 계속 섀도우마스터... 그리고 총상회의 결정을 지지하겠습니다!",
  ui_story_5071_50710201_41_dialog_content = "섀도우마스터의 부모님을 안장해 준 사람은 이미 세상을 떠났습니다.\n저 남자는 아무래도 저와 같은 「취미」가 있는 모양이네요.",
  ui_story_5071_50710201_42_dialog_content = "그건 중요하지 않다. 클레이튼, 저자에게 가서 앞으로 어떻게 해야 하는지 알려줘라.",
  ui_story_5071_50710201_43_dialog_content = "예, 섀도우마스터.",
  ui_story_5071_50710201_44_dialog_content = "<color=#e8d9bb>부유 비공정, 영화관 밖</color>",
  ui_story_5071_50710201_45_dialog_content = "(음... 「실화를 각색한 청춘 스토리── 《알리우드 드림》 절찬 상영 중!\n마지막 1장의 티켓만 남았습니다!」...?)",
  ui_story_5071_50710201_46_dialog_content = "(리리카의 신작이잖아?! 요즘 어떻게 지내는지 영 소식을 못 들었는데, 새 작품 찍느라 바빴구나...)",
  ui_story_5071_50710201_47_dialog_content = "(어차피 지금 딱히 할 일도 없는데, 관람해서 응원해 주자!)",
  ui_story_5071_50710201_48_dialog_content = "《알리우드 드림》 1장 주세요!",
  ui_story_5071_50710201_49_dialog_content = "...으악! 브랜디가 선수쳤잖아?!",
  ui_story_5071_50710201_50_dialog_content = "...이 꼬마애... 왜 계속 아무 말도 안 하지?",
  ui_story_5071_50710201_51_dialog_content = "미아인가? 근데 아이 찾는 부모는 못 봤는데?",
  ui_story_5071_50710201_52_dialog_content = "도대체 어느 집 애야?",
  ui_story_5071_50710201_53_dialog_content = "(왜 사람들이 모여있지? 무슨 이벤트라도 하고 있나...?)",
  ui_story_5071_50710201_54_dialog_content = "킁킁──",
  ui_story_5071_50710201_55_dialog_content = "...어? 꼬마애?",
  ui_story_5071_50710201_56_dialog_content = "으읏──",
  ui_story_5071_50710201_57_dialog_content = "어? 어라──? 야... 너 왜 나한테 안기는 건데?",
  ui_story_5071_50710201_58_dialog_content = "저렇게 한참 낯가리던 애가 달려드는 거 보면... 저 남자애가 가족이겠네.",
  ui_story_5071_50710201_59_dialog_content = "너 그 애 형 맞지? 그런 어린애를 혼자 놔두면 어떡해? 아까까지 한참 울고 있었다니까.",
  ui_story_5071_50710201_60_dialog_content = "앞으로는 조심해!",
  ui_story_5071_50710201_61_dialog_content = "......",
  ui_story_5071_50710201_62_dialog_content = "......",
  ui_story_5071_50710201_63_dialog_content = "저기... 너 누구야...?",
  ui_story_5071_50710201_64_dialog_content = "<color=#e8d9bb>꼬르륵──</color>",
  ui_story_5071_50710201_65_dialog_content = "형아... 나 배고파...",
  ui_story_5071_50710201_66_dialog_content = "섀도우마스터, 그간 잘 지냈습니까?",
  ui_story_5071_50710201_67_dialog_content = "후작 나리 아니신가, 요즘 계속 백야성 장원에서 손녀딸 공부를 봐 주고 있는 줄 알았는데.",
  ui_story_5071_50710201_68_dialog_content = "하하, 계속 위에 있다간 어떤 자들이 「개혁」이라는 이름을 내세워\n움브라톤의 제 자산을 삼켜버릴까 걱정이 돼서 말이지요.",
  ui_story_5071_50710201_69_dialog_content = "어떻게 된 겁니까? 고액의 회비도 걷고 있으면서, 총상회는 아직도 배가 안 찼답니까?",
  ui_story_5071_50710201_70_dialog_content = "하하, 그건 다른 문제일 터이다만, 후작 나리.",
  ui_story_5071_50710201_71_dialog_content = "당신 상회가 총상회 규정을 위반했기 때문에 조사와 압류가 이루어진 것이다.",
  ui_story_5071_50710201_72_dialog_content = "앞으로 제때 시정해서, 예전 같은 그런... 떳떳하지 못한 수단을 버린다면,\n사업을 계속할 수 있을 것이다.",
  ui_story_5071_50710201_73_dialog_content = "게다가 총상회가 징수하는 회비의 대부분은 약정에 따라\n「세금」 명목으로 백야성에 상납하고 있다.",
  ui_story_5071_50710201_74_dialog_content = "총상회는 얼마 되지도 않는 남은 부분으로 일상 지출을 충당하고 있지...",
  ui_story_5071_50710201_75_dialog_content = "그런 속임수의 대사를 입에 담을 때 따님의 말투는 정말 당신을 쏙 빼닮았더군요.\n모르는 사람이 들으면 분명 친딸인 줄 알겠습니다.",
  ui_story_5071_50710201_76_dialog_content = "이미 총상회장의 설명을 들었다면, 굳이 날 찾아온 이유가 뭐지?",
  ui_story_5071_50710201_77_dialog_content = "이스타반, 시치미 떼지 말아요...",
  ui_story_5071_50710201_78_dialog_content = "움브라톤이 무엇으로 지금의 번영을 이뤘습니까?",
  ui_story_5071_50710201_79_dialog_content = "이스타반 클랜이 이렇게까지 클 수 있었던 게 무엇 때문입니까?",
  ui_story_5071_50710201_80_dialog_content = "당신 손은 지금 이 비공정에 탄 그 누구의 손보다도 더러운데...\n설마 그걸 깨끗이 씻을 수 있으리라 생각했습니까?",
  ui_story_5071_50710201_81_dialog_content = "당신이 용인하는 「개혁」은 결국 당신을 해칠 겁니다!",
  ui_story_5071_50710201_82_dialog_content = "하하, 그런가.",
  ui_story_5071_50710201_83_dialog_content = "그거 오히려 기대되는군...",
  ui_story_5071_50710201_84_dialog_content = "움브라톤을 정상 궤도에 올려놓으려는 「개혁」이 대체 어떻게 내 목을 조를 수 있을지 말이야.",
  ui_story_5071_50710201_85_dialog_content = "냠냠... 우걱우걱...",
  ui_story_5071_50710201_86_dialog_content = "체하겠다! 천천히 먹어!",
  ui_story_5071_50710201_87_dialog_content = "로스트치킨 두 마리, 피자 네 판, 케이크 다섯 조각... 너 도대체 며칠을 굶은 거야?",
  ui_story_5071_50710201_88_dialog_content = "냠냠... 음... 마지막으로 뭐 먹은 지 세 시간이나 지났어...\n배고파 죽는 줄 알았다구...",
  ui_story_5071_50710201_89_dialog_content = "고작 세 시간 지났는데 이렇게 배가 고파?!",
  ui_story_5071_50710201_90_dialog_content = "나, 난 모르는 사람을 만나면 긴장하거든... 긴장하면 에너지를 많이 쓰니까, 그래서...",
  ui_story_5071_50710201_91_dialog_content = "아, 저기... 밥값은 잘 갚을게!",
  ui_story_5071_50710201_92_dialog_content = "그, 근데 형아... 나 샤엘 사장님 찾는 거 좀 도와줄 수 있을까?",
  ui_story_5071_50710201_93_dialog_content = "샤엘 씨...?",
  ui_story_5071_50710201_94_dialog_content = "나, 난 버질이라고 해. 샤엘 사장님 직원이야...",
  ui_story_5071_50710201_95_dialog_content = "케헥... 샤엘 씨가 너 같은 어린애한테까지 일을 시키고 있단 말이야?!",
  ui_story_5071_50710201_96_dialog_content = "오, 오, 오해하지 마! 내가 시켜달라고 부탁한 거야!",
  ui_story_5071_50710201_97_dialog_content = "뭐... 무슨 일인지는 잘 모르겠지만, 근처에 샤엘 씨가 있는 게 느껴지니까...",
  ui_story_5071_50710201_98_dialog_content = "꼼짝 마!",
  ui_story_5071_50710201_99_dialog_content = "목표 발견!",
  ui_story_5071_50710201_100_dialog_content = "우린 문지기 멍멍이다!",
  ui_story_5071_50710201_101_dialog_content = "멍멍이 출격!",
  ui_story_5071_50710201_102_dialog_content = "저쪽은... 이스타반 씨 응접실 아냐?",
  ui_story_5071_50710302_1_dialog_content = "여사님, 괜찮으신가요?",
  ui_story_5071_50710302_2_dialog_content = "고마워요, 전... 괜찮아요.",
  ui_story_5071_50710302_3_dialog_content = "파티, 파시. 뭐가 어떻게 된 건지 말해줄래?",
  ui_story_5071_50710302_4_dialog_content = "우린 착한 문지기 멍멍이야.",
  ui_story_5071_50710302_5_dialog_content = "미리 약속 안 잡은 나쁜 손님은 들여보낼 수 없어.",
  ui_story_5071_50710302_6_dialog_content = "정말 충직한 꼬마 맹견들이네. 대신 앞으로는 이렇게까지 소란 피울 필요는 없어.",
  ui_story_5071_50710302_7_dialog_content = "부유 비공정 위에서 날뛰면 하늘에서 떨어져 버릴지도 모르거든.",
  ui_story_5071_50710302_8_dialog_content = "파티는 안 무서워! 파시도 안 무서워!",
  ui_story_5071_50710302_9_dialog_content = "하지만 안에서 손님을 만나고 있는 섀도우마스터를 방해하면 큰일 날걸?",
  ui_story_5071_50710302_10_dialog_content = "보스를 방해하면 안 돼... 착한 멍멍이는 당연히 알지!",
  ui_story_5071_50710302_11_dialog_content = "그래서... 어느 상회 회장님의 수행원이신가요?\n죄송하지만 제가 당신을 초대한 기억은 없는 것 같아서요.",
  ui_story_5071_50710302_12_dialog_content = "닮았어... 가까이서 보면 볼수록... 똑같아...",
  ui_story_5071_50710302_13_dialog_content = "......?",
  ui_story_5071_50710302_14_dialog_content = "사, 사...사장님!",
  ui_story_5071_50710302_15_dialog_content = "버질? 왜 여기 네가 있니? 내가 부유 경매장에서 기다리라고 했잖아?",
  ui_story_5071_50710302_16_dialog_content = "바, 방금 너무 배고파서 뭐 좀 먹으려고 나왔는데... 밖에 사람이 많아서 길을 잃었어요.",
  ui_story_5071_50710302_17_dialog_content = "근데 이 형아가 도와줬어요! 그리고 맛있는 것도 잔뜩 먹게 해 줬어요!",
  ui_story_5071_50710302_18_dialog_content = "하하... 어쩌다 보니 그렇게 됐네요.",
  ui_story_5071_50710302_19_dialog_content = "어머? 벌써 PlayerName하고 친구가 된 거야?\n우리 버질은 모르는 사람한테는 쉽게 말을 안 거는 줄 알았는데 말이야.",
  ui_story_5071_50710302_20_dialog_content = "그치만...PlayerName 형아한테는 골동품 냄새가 나니까 왠지 안심이 돼서...",
  ui_story_5071_50710302_21_dialog_content = "후훗, 틀린 말은 아냐. PlayerName 얜 출토된 지 얼마 안 된 골동품이 맞거든.",
  ui_story_5071_50710302_22_dialog_content = "PlayerName...? 설마 그 전설의 아이테르인가요?!",
  ui_story_5071_50710302_23_dialog_content = "미안하지만 아직 제 질문에 답을 안 주셨는데요. 대체 누구시죠? 그리고 왜 여기 계신 거죠?",
  ui_story_5071_50710302_24_dialog_content = "미리 말씀드리는데, 이 비공정 보안팀도 섀도우마스터의 저 멍멍이들 못지않게\n거칠다는 점 알아 두셨으면 좋겠네요.",
  ui_story_5071_50710302_25_dialog_content = "아... 전 이본이라고 해요. 소설을 쓰는 사람이지요.\n오늘은 사거리 출판사의 특별 기고가 자격으로 온 거예요.",
  ui_story_5071_50710302_26_dialog_content = "소동을 일으켜서 정말 미안해요...\n오늘 이 비공정에서 섀도우마스터를 만나려면 사전에 약속이 필요한 줄 몰랐거든요...",
  ui_story_5071_50710302_27_dialog_content = "이본...? 제가 잘못 들은 거 아니죠? 그 유명 작가 이본 선생님인가요?!",
  ui_story_5071_50710302_28_dialog_content = "...오랫동안 글밥을 먹긴 했지만, 이런 어린 친구까지 제 이름을 알고 있을 줄은 몰랐네요.",
  ui_story_5071_50710302_29_dialog_content = "여사님 작품은 움브라톤의 과거의 산증인이니까요.\n움브라톤에서 글을 읽을 줄 아는 사람이면 누구나 여사님 작품을 읽은 적 있을 거예요.",
  ui_story_5071_50710302_30_dialog_content = "이렇게 모습을 드러내신 적은 없으셨을 텐데요. 그래서 저도 못 알아뵀고 말이죠.\n그런데 오늘은 무슨 일로...",
  ui_story_5071_50710302_31_dialog_content = "젊었을 땐 이래저래 조심스럽고 불안하기도 해서 그랬었지요.\n지금은 나이가 들어서인지 그때보단 용기가 조금 생겼답니다.",
  ui_story_5071_50710302_32_dialog_content = "아니면 저도 신작 집필을 위해 혼자 이 비공정에 탈 엄두도 못 냈겠지요.",
  ui_story_5071_50710302_33_dialog_content = "신작 집필이요?",
  ui_story_5071_50710302_34_dialog_content = "지난 작품이 혹평을 많이 받은 뒤로 전 제가 더는 집필할 마음이 안 생길 줄 알았어요.",
  ui_story_5071_50710302_35_dialog_content = "그런데 얼마 전 한 <color=#FFB400>화가 친구</color>를 사귀게 됐었지요. 그 친구에게 전 어떤 이야기를 들었답니다.",
  ui_story_5071_50710302_36_dialog_content = "진실한 이야기는 그 어떤 심혈을 기울인 소설보다도 사람의 마음을 들끓게 만들지요.\n그 친구의 이야기를 듣고 나서 전 격동으로 잠을 이루지 못할 정도였어요!",
  ui_story_5071_50710302_37_dialog_content = "그건 절대 이대로 움브라톤의 먼지 속에 묻혀선 안 되는 이야기예요.\n그래서 전 그 친구의 격려를 받고 다시 집필을 시작했어요.",
  ui_story_5071_50710302_38_dialog_content = "하지만 그 이야기는 훌륭하긴 했지만, 세부적인 고증이 부족했어요.\n그래서 전 섀도우마스터를 취재하러 온 거예요.",
  ui_story_5071_50710302_39_dialog_content = "...위험한 건 알고 있어요. 그리고 섀도우마스터가 자신이 아는 사실을\n저처럼 한물간 작가에게 털어놓을지도 잘 모르겠고...",
  ui_story_5071_50710302_40_dialog_content = "소설을 쓰는 게... 왜 위험하죠?",
  ui_story_5071_50710302_41_dialog_content = "이 작품이 세상에 나올 수 있다면, 여러분도 그 이유를 알게 되실 거예요.",
  ui_story_5071_50710302_42_dialog_content = "역시 작가님답네요. 독자의 흥미를 아주 잘 돋우고 계시잖아요.",
  ui_story_5071_50710302_43_dialog_content = "샤엘 씨, 무리한 부탁이란 건 알지만... 섀도우마스터께 말씀 좀 드려주실 수 있을까요?\n그분 시간을 오래 뺏진 않을 거예요!",
  ui_story_5071_50710302_44_dialog_content = "후훗, 만약 제가 거절한다면, 움브라톤의 문단에서는 또 우리 상인들이\n돈만 알고 문학적 소양이 없다고 비판하겠죠?",
  ui_story_5071_50710302_45_dialog_content = "전 그런 평론을 전혀 신경 쓰지 않지만... 저도 여사님 작품의 팬인 이상 어쩔 수 없겠네요~",
  ui_story_5071_50710302_46_dialog_content = "그리고 어차피 오늘은 섀도우마스터도 이미 「관례」를 깨고 있으니까요.\n그럼 여기서 잠시만 기다려 주세요.",
  ui_story_5071_50710302_47_dialog_content = "크흠. 저기, 이본 선생님, 여기 이 친구한테 사인 좀 해 주실 수 있을까요?\n낯을 가려서 직접 말을 못 하거든요... 얘 이름은 버질이구요.",
  ui_story_5071_50710302_48_dialog_content = "사인이요? 물론 해 드려야죠. 꼬마 친구, 제 작품을 좋아해 줘서 고마워요.\n지금 수중에 빈 원고지밖에 없는데, 여기에 사인해도 괜찮을까요?",
  ui_story_5071_50710302_49_dialog_content = "무...물론이죠!",
  ui_story_5071_50710302_50_dialog_content = "자, 여기요. 그래도 이래서야 너무 성의가 없어 보이니까,\n또 만날 기회가 되면 책 한 권을 선물할게요...",
  ui_story_5071_50710302_51_dialog_content = "참, 제 작품 중에 어떤 게 가장 마음에 들었나요?",
  ui_story_5071_50710302_52_dialog_content = "저, 저저저저, 전... 《레드 머큐리》요!",
  ui_story_5071_50710302_53_dialog_content = "그 제목...",
  ui_story_5071_50710302_54_option_content = "어디서 들어본 것 같은데...",
  ui_story_5071_50710302_55_dialog_content = "아, 콜로서스에도 한 권 있었던 것 같아!",
  ui_story_5071_50710302_56_option_content = "역시 들어본 적 없어...",
  ui_story_5071_50710302_57_dialog_content = "《레드 머큐리》는 한 아름답지만 냉혹하고 신비로운 상회의 수장,\n머큐리 부인의 전설적인 이야기를 다루고 있어.",
  ui_story_5071_50710302_58_dialog_content = "그 부인은 사랑하는 사람을 위해 귀족 신분을 버리고 움브라톤으로 왔어.",
  ui_story_5071_50710302_59_dialog_content = "남편이 죽은 뒤엔 혼자 여러 상회를 경영하면서, 조용하게 남편의 복수도 해냈다는 이야기야.",
  ui_story_5071_50710302_60_dialog_content = "《레드 머큐리》 얘기니? 그거 나도 좋아하는 작품이야.",
  ui_story_5071_50710302_61_dialog_content = "그, 그런가요? 그거 정말 기쁘네요...",
  ui_story_5071_50710302_62_dialog_content = "이본 여사님, 이미 사람을 보내서 전했어요. 이제 곧 답이 올 거예요.",
  ui_story_5071_50710302_63_dialog_content = "아... 정말 고마워요, 샤엘 씨!",
  ui_story_5071_50710302_64_dialog_content = "운명이란 때로는 이토록 공교로운 것이로군요. 사실 이 말을 꺼내고 싶진 않았는데...\n당신은 정말 <color=#FFB400>멜리사</color> 부인과 똑 닮았네요.",
  ui_story_5071_50710302_65_dialog_content = "...그분을 아시나요? 그럼 설마 《레드 머큐리》의 이야기가 정말로...",
  ui_story_5071_50710302_66_dialog_content = "맞아요. 머큐리 부인의 모델이 바로 멜리사 부인이에요.",
  ui_story_5071_50710302_67_dialog_content = "멜리사 부인? 그게 누구죠?",
  ui_story_5071_50710302_68_dialog_content = "너도 몰라? 근데... 그 멜리사 부인은 왠지 샤엘 씨한테 되게 중요한 사람인가 봐.",
  ui_story_5071_50710302_69_dialog_content = "......",
  ui_story_5071_50710302_70_dialog_content = "이본 여사님, 머큐리 부인의 모습을 책으로 남겨 주셔서 진심으로 감사드려요.\n덕분에 전 그분이 어떤 모습이었을지 상상할 수 있었으니까요.",
  ui_story_5071_50710302_71_dialog_content = "멜리사 부인의 자녀분은 원수에게 납치되어 독살당했다고 들었었는데...\n이제 보니 어머니와 마찬가지로 힘차게 살아가고 계셨네요.",
  ui_story_5071_50710302_72_dialog_content = "전 후회를 거의 안 하는 사람이지만, 지금은 진작 출판업에 투자를 안 한 게 후회가 돼요.\n그랬으면 당신을 좀 더 일찍 만날 수 있었을 텐데 말이에요.",
  ui_story_5071_50710302_73_dialog_content = "앞으로 얼마든지 기회는 있답니다.\n물론 제가 옛날이야기를 늘어놓는 걸 싫어하지 않으신다면 말이지요.",
  ui_story_5071_50710302_74_dialog_content = "이야기 듣는 거라면 원래부터 좋아했어요. 게다가 그분의 이야기라면...",
  ui_story_5071_50710302_75_dialog_content = "참, 이건 다른 이야기인데요. 여사님이 지금 집필 중인 작품에도 지속적으로 투자하고 싶어요.",
  ui_story_5071_50710302_76_dialog_content = "어머... 세상에...",
  ui_story_5071_50710302_77_dialog_content = "멜리사 부인도 따님의 이런 훌륭한 모습을 보시면\n분명히 백합처럼 아름다운 미소를 지으셨을 거예요.",
  ui_story_5071_50710302_78_dialog_content = "휴, 상회장님은 고객에겐 늘 관대하지만, 파트너에겐 늘 난제를 주신단 말이죠.",
  ui_story_5071_50710302_79_dialog_content = "어머, 벌써 답이 온 건가요?",
  ui_story_5071_50710302_80_dialog_content = "음, 이분이 바로 이본 여사님이시겠군요.",
  ui_story_5071_50710302_81_dialog_content = "섀도우마스터께서 면담 요청을 허락하셨습니다. 따라오시죠.\n안에서 잠시만 기다려 주시면 됩니다.",
  ui_story_5071_50710302_82_dialog_content = "!!!",
  ui_story_5071_50710302_83_dialog_content = "샤엘 씨... 도와주셔서 정말 고마워요!",
  ui_story_5071_50710302_84_dialog_content = "아까 말씀하셨잖아요. 이것도 운명의 공교로움 아니겠어요?\n그럼 섀도우마스터와 면담이 끝나고, 우리끼리 나눌 옛날이야기도 기대하고 있을게요.",
  ui_story_5071_50710302_85_dialog_content = "물론이지요. 영광이랍니다.",
  ui_story_5071_50710302_86_dialog_content = "......",
  ui_story_5071_50710302_87_dialog_content = "우리 PlayerName, 왜 아직도 멍하니 있을까?",
  ui_story_5071_50710302_88_dialog_content = "아니면...",
  ui_story_5071_50710302_89_dialog_content = "갑자기 내 과거에 흥미가 생긴 걸까?",
  ui_story_5071_50710401_1_dialog_content = "<color=#e8d9bb>10여 년 전</color>",
  ui_story_5071_50710401_2_dialog_content = "저기 좀 봐! 저 사람들이 바로 어둠의 위기를 끝내준 그 연합군인가?",
  ui_story_5071_50710401_3_dialog_content = "백야성으로 가고 있는 것 같아... 그럼 백야성 기사들인 건가?!",
  ui_story_5071_50710401_4_dialog_content = "백야성 기사는 다들 번쩍번쩍한 갑옷을 입을걸.\n저 사람들은 딱 봐도 꾀죄죄한 게 보나 마나 움브라톤 쪽이겠지.",
  ui_story_5071_50710401_5_dialog_content = "움브라톤은 진작 암귀한테 박살 난 거 아니었어? 아직도 살아있는 사람들이 있단 말이야?",
  ui_story_5071_50710401_6_dialog_content = "백야성이 도와준 덕분에 꽤 살아남았다는 모양이더라고.",
  ui_story_5071_50710401_7_dialog_content = "하여튼 사람은 뒷배가 있어야 된다니까.\n움브라톤이 시궁창이긴 해도, 꼬리만 흔들면 도와줄 주인님이 있잖아?",
  ui_story_5071_50710401_8_dialog_content = "쉿... 조용히 해! 주먹 한 방에 암귀를 갈라 죽일 수 있는 사람들이라고.\n괜히 깝죽대지 마.",
  ui_story_5071_50710401_9_dialog_content = "어? 잠깐만. 저거 샤엘 아냐? 야, 그 사람들한테 가서 뭐 하려고?!",
  ui_story_5071_50710401_10_dialog_content = "뒤에서 비아냥대지 말고 직접 가서 말하지 그래? 아무리 그래도 암귀를 없애준 영웅들인데.",
  ui_story_5071_50710401_11_dialog_content = "샤엘... 너도 우리 대신 몇 번이나 암귀를 물리쳐 주긴 했지만...\n저 사람들은 암귀보다 더 무서울지도 모른다고! 괜히 건드렸다 목 날아갈 짓 하지 마!",
  ui_story_5071_50710401_12_dialog_content = "걱정 마... 그 어떤 사람도 「이익」과 「돈」을 외면하진 않을 테니까.",
  ui_story_5071_50710401_13_dialog_content = "멈춰라! 누구냐?",
  ui_story_5071_50710401_14_dialog_content = "긴장 풀어요. 자, 보세요. 전 암귀도 아니잖아요.",
  ui_story_5071_50710401_15_dialog_content = "별일 아니에요. 그냥 저희 가게에서 무료로 얼음물이나 한 잔 드리고 싶어서요~\n이 지방은 날씨가 건조하거든요.",
  ui_story_5071_50710401_16_dialog_content = "세상에 공짜 점심은 없을 텐데.",
  ui_story_5071_50710401_17_dialog_content = "후훗, 공짜 점심은 없지만, 공짜 물이라면 있죠.\n물론 식사를 원하신다면 그것도 저희 가게에서 팔고 있답니다~",
  ui_story_5071_50710401_18_dialog_content = "정통 사막 스타일의 전갈 통구이 도시락, 움브라톤으로 돌아가면 더는 못 먹을걸요?",
  ui_story_5071_50710401_19_dialog_content = "우린 가야 할 길이 머니 됐다.",
  ui_story_5071_50710401_20_dialog_content = "꽤 먼 길을 왔을 텐데, 좀 쉬는 게 좋지 않을까요?\n당신은 안 힘들어도 병사들은 힘들지도 모르잖아요.",
  ui_story_5071_50710401_21_dialog_content = "하하, 이 근방 사람들은 성질이 사납다고들 하던데, 넌 예외인 모양이군.",
  ui_story_5071_50710401_22_dialog_content = "자, 여러분~ 물 드시고 싶으신 분, 식사하고 싶으신 분, 전부 절 따라오세요~",
  ui_story_5071_50710401_23_dialog_content = "<color=#e8d9bb>샤엘은 장갑을 벗어서 흔들며 열심히 주변 사람들의 주의를 끌었다.</color>",
  ui_story_5071_50710401_24_dialog_content = "<color=#e8d9bb>눈부신 햇살 아래, 샤엘의 팔뚝에는 가느다란 상처가 희미하게 붉은빛을 내고 있었고,\n그 모습은 마치 혀를 내밀고 있는 작은 뱀의 형상 같았다.</color>",
  ui_story_5071_50710401_25_dialog_content = "<color=#e8d9bb>그것을 본 이스타반은 그제서야 목소리의 근원을 따라 상대의 모습을 관찰하기 시작했다.</color>",
  ui_story_5071_50710401_26_dialog_content = "잠깐! 너, 넌... 멜리사...? 아니야... 넌...",
  ui_story_5071_50710401_27_dialog_content = "설마 네가 샤엘이냐?!",
  ui_story_5071_50710401_28_dialog_content = "어머? 저 아직 제 소개는 안 했을 텐데요.",
  ui_story_5071_50710401_29_dialog_content = "확실히 이 주변에선 나름 유명한 상인이긴 한데, 어떻게 당신이...",
  ui_story_5071_50710401_30_dialog_content = "드디어 찾았군!",
  ui_story_5071_50710401_31_dialog_content = "하하... 결국엔 약속을 지키지 못할 줄 알았는데...",
  ui_story_5071_50710401_32_dialog_content = "자! 우릴 따라 움브라톤으로 돌아가자. 거기야말로 네 고향이다!",
  ui_story_5071_50710401_33_dialog_content = "(...움브라톤 사람들은 종잡을 수가 없어서 말이 안 통한다더니,\n역시 마을 사람들 말대로네.)",
  ui_story_5071_50710401_34_dialog_content = "후훗, 손님. 저도 움브라톤에 가보고 싶긴 한데요, 지금 전 제 가게도 있어서요...",
  ui_story_5071_50710401_35_dialog_content = "어머, 그러고 보니 가게에 가 볼 시간이네요!",
  ui_story_5071_50710401_36_dialog_content = "뭔가 오해한 모양인데...",
  ui_story_5071_50710401_37_dialog_content = "다가오지 마!",
  ui_story_5071_50710402_1_dialog_content = "하하하, 역시 멜리사의 딸답군!\n제대로 된 훈련도 못 받았을 텐데, 전투 능력은 결코 무시할 수준이 아니잖아.",
  ui_story_5071_50710402_2_dialog_content = "당신... 대체 목적이 뭐야? 난 그냥 평범한 상인일 뿐이야. 나한테 무슨 이용 가치가 있지?",
  ui_story_5071_50710402_3_dialog_content = "미안하군, 내가 미리 제대로 설명했어야 했어.\n난 친구의 잃어버린 딸을 찾아주고 있을 뿐이다.",
  ui_story_5071_50710402_4_dialog_content = "난 어렸을 때부터 사막에서 자랐어. 내가 움브라톤과 관계가 있을 리가 없잖아?",
  ui_story_5071_50710402_5_dialog_content = "네 팔엔 뱀의 표식이 있을 거다. 안 그런가?",
  ui_story_5071_50710402_6_dialog_content = "그거 방금 본 거 아냐?",
  ui_story_5071_50710402_7_dialog_content = "음... 그리고 네가 네 어머니와 헤어질 때 입었던 옷엔 네 이름 「샤엘」이 적혀 있었을 거다.\n내 말이 맞나?",
  ui_story_5071_50710402_8_dialog_content = "방금 네 반응을 보면 그게 네 이름이 맞는 모양이더군.",
  ui_story_5071_50710402_9_dialog_content = "...내가... 누구 딸이라고?",
  ui_story_5071_50710402_10_dialog_content = "넌 나의 친구, 멜리사의 딸이다.",
  ui_story_5071_50710402_11_dialog_content = "내가 진짜로 그 사람 딸이면, 왜 그 사람은 날 보러 안 오는 거지?",
  ui_story_5071_50710402_12_dialog_content = "...이미 병으로 세상을 떠났다.",
  ui_story_5071_50710402_13_dialog_content = "그럼 그 말들도 결국 증거는 없다는 거잖아.",
  ui_story_5071_50710402_14_dialog_content = "......",
  ui_story_5071_50710402_15_dialog_content = "난 줄곧 이걸 가지고 다녔지. 언젠간 직접 네게 줄 날이 올 거라 생각하면서 말이다.",
  ui_story_5071_50710402_16_dialog_content = "이거... 순금인가?",
  ui_story_5071_50710402_17_dialog_content = "네 어머니가 남긴 유품이다. 넌 루미나틱스를 쓸 수 있으니 잘 다룰 수 있을 거다.",
  ui_story_5071_50710402_18_dialog_content = "이렇게 그냥 줘도 되는 거야?",
  ui_story_5071_50710402_19_dialog_content = "잘 생각해 보고, 생각이 정리되면 언제든지 움브라톤으로 날 찾아와라.",
  ui_story_5071_50710402_20_dialog_content = "그럼 당신도 잘 생각하는 게 좋을걸.\n물건은 받겠지만, 꼭 당신을 찾아간다는 보장은 안 하니까.",
  ui_story_5071_50710402_21_dialog_content = "오게 될 거다.",
  ui_story_5071_50710402_22_dialog_content = "...진짜 이상한 사람이네.",
  ui_story_5071_50710402_23_dialog_content = "(근데... 세상에 정말 공짜 「점심」이 있을까?)",
  ui_story_5071_50710402_24_dialog_content = "<color=#e8d9bb>똑똑똑──</color>",
  ui_story_5071_50710402_25_dialog_content = "들어와라.",
  ui_story_5071_50710402_26_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5071_50710402_27_dialog_content = "샤엘?",
  ui_story_5071_50710402_28_dialog_content = "하하, 내가 오게 될 거라고 했었지.\n움브라톤에 온 지도 꽤 된 모양이던데, 좀 익숙해졌나?",
  ui_story_5071_50710402_29_dialog_content = "<color=#e8d9bb>탁──</color>",
  ui_story_5071_50710402_30_dialog_content = "인사치레보단 일단 그 자료부터 보세요.",
  ui_story_5071_50710402_31_dialog_content = "흐음?",
  ui_story_5071_50710402_32_dialog_content = "그 대단한 이스타반 클랜도 벌크 시장에 뛰어들었더군요.",
  ui_story_5071_50710402_33_dialog_content = "그런데 공급업체 보는 안목이 썩 좋진 않네요.",
  ui_story_5071_50710402_34_dialog_content = "당신한테 물건을 대기로 한 폭스 상회 말이에요.\n백야성 귀족을 속일 만큼 간이 배 밖으로 나왔더군요... 자세한 건 자료에 정리해 뒀어요.",
  ui_story_5071_50710402_35_dialog_content = "저라도 추적할 수 있는 일이라면, 백야성 쪽에선 진작부터 눈치채고 있었겠죠?",
  ui_story_5071_50710402_36_dialog_content = "당신이 「신용」하는 공급업체가 감옥에 들어갈 날도 이제 머지않겠네요.",
  ui_story_5071_50710402_37_dialog_content = "폭스 상회가 잡혀 들어가면 이스타반 클랜은 공급망을 잃게 될 거예요.\n게다가 고객 쪽엔 어떻게 해명할 생각이죠?",
  ui_story_5071_50710402_38_dialog_content = "이 일 때문에 날 찾아온 건가?",
  ui_story_5071_50710402_39_dialog_content = "섀도우마스터, 갑자기 그런 심각한 얼굴 하지 마세요.",
  ui_story_5071_50710402_40_dialog_content = "전 도움을 주러 온 거지, 불난 집에 부채질하러 온 건 아니에요.",
  ui_story_5071_50710402_41_dialog_content = "사업을 할 거면 암흑가 아저씨들끼리만 할 게 아니라 업계 사람의 도움이 필요하지 않겠어요?",
  ui_story_5071_50710402_42_dialog_content = "물론 섀도우마스터에겐 특별히 지인 할인도 해 드릴게요.",
  ui_story_5071_50710402_43_dialog_content = "(그랬군, 날 찾아오지 않고 자기 힘으로 움브라톤에 작은 상회를 세웠던 건...)",
  ui_story_5071_50710402_44_dialog_content = "(실력을 얕보이고 싶지 않다는 것이겠지. 그리고 기회를 잡아서 날 돕고,\n대등한 협력관계를 세우겠다는 것인가.)",
  ui_story_5071_50710402_45_dialog_content = "하하하하! 좋다, 그렇다면 어디 샤엘 사장에게 신세를 져 보도록 할까.\n이번 거래의 공급망 관리를 부탁하지.",
  ui_story_5071_50710402_46_dialog_content = "이걸로 빚을 졌으니, 소원이 있다면 말해 봐라. 반드시 들어주겠다고 약속하마.",
  ui_story_5071_50710402_47_dialog_content = "전 줄곧 제 소원을 이뤄줄 사람은 저뿐이라고 생각해 왔는걸요.",
  ui_story_5071_50710402_48_dialog_content = "상관없다. 그 소원은 나중에 빌어도 되니 말이야.\n필요한 때가 오면 언제든지 날 찾아와 요구해라.",
  ui_story_5071_50710402_49_dialog_content = "섀도우마스터의 호의엔 감사드릴게요.\n부디 제가 그 「소원」을 요구하러 올 일이 평생 없었으면 좋겠네요.",
  ui_story_5071_50710402_50_dialog_content = "...나조차 혼란스러울 지경이군. 네겐 네 어머니의 그림자가 있다. 외모뿐만이 아니라...",
  ui_story_5071_50710402_51_dialog_content = "...어머니는... 대체 어떤 분이셨죠?",
  ui_story_5071_50710402_52_dialog_content = "한 상회의 수장이었지. 일 처리가 과감하고, 너처럼 경영에 재능이 있었다.\n난 네 어머니를 무척 존경했다.",
  ui_story_5071_50710402_53_dialog_content = "아쉽지만 그런 칭찬을 들어도 전 어떤 모습도 떠오르질 않아요.\n어머니의 그림자조차 손에 닿질 않는다구요...",
  ui_story_5071_50710402_54_dialog_content = "섀도우마스터! 확인했습니다!",
  ui_story_5071_50710402_55_dialog_content = "말씀대로 폭스 상회는 처음부터 우리 쪽에 물건을 납품할 생각이 없었습니다!\n죄송합니다. 저희가 사전에 제대로 조사하지 못한 탓에...",
  ui_story_5071_50710402_56_dialog_content = "게다가 계약금의 80%를 날리게 생겼습니다... 폭스 상회 회장은 이미 백야성에 잡혀갔습니다.",
  ui_story_5071_50710402_57_dialog_content = "물건을 빠르게 납품해 줄 다른 상회를 찾았습니다만, 지금 바로 계약할까요?",
  ui_story_5071_50710402_58_dialog_content = "됐다. 이미 우리에게 더 적합한 파트너를 찾았으니, 너흰 내 연락을 기다려라.",
  ui_story_5071_50710402_59_dialog_content = "예!",
  ui_story_5071_50710402_60_dialog_content = "일을 이렇게 만든 건 당신 부하들이었군요.\n...잠깐만요, 그럼 당신은 진작부터 폭스 상회에 문제가 있는 걸 알고 있었나요?!",
  ui_story_5071_50710402_61_dialog_content = "지나간 일을 다시 따질 필요는 없을 텐데.\n지금은 앞으로의 협력 관계를 축하해야 마땅하지 않겠나.",
  ui_story_5071_50710402_62_dialog_content = "부하가 이미 다른 상회를 찾았다는데... 왜 절 선택한 거죠? 설마 제 어머니 때문에...",
  ui_story_5071_50710402_63_dialog_content = "아니, 네가 그 이유다, 샤엘.\n넌 대상회를 이끄는 회장이란 자들보다 거래의 방법을 더 잘 알고 있다.",
  ui_story_5071_50710402_64_dialog_content = "우리가 협력 관계가 될 수 있어서 기쁘군.",
  ui_story_5071_50710402_65_dialog_content = "그럼 우리의 협력이 순조롭길 미리 기원하죠.",
  ui_story_5071_50710402_66_dialog_content = "그나저나 아직 네 상회의 이름을 못 들었는데.",
  ui_story_5071_50710402_67_dialog_content = "「공중상회」예요.",
  ui_story_5071_50710402_68_dialog_content = "...너도 저 하늘에 떠 있는 섬을 동경하고 있는 모양이군.",
  ui_story_5071_50710402_69_dialog_content = "백야성 말인가요? 확실히 매력적인 곳이긴 하죠.\n하지만 제가 동경하는 건 자유롭게 하늘을 이동하는 섬이에요.",
  ui_story_5071_50710402_70_dialog_content = "자유롭게 거래하고, 내키는 대로 마음껏 날아다니는 그런...\n어머? 제 꿈이 너무 비현실적이라고 생각하는 건가요?",
  ui_story_5071_50710402_71_dialog_content = "아니, 그것보다...",
  ui_story_5071_50710402_72_dialog_content = "앞으로 잘해보자고.",
  ui_story_5071_50710402_73_dialog_content = "(샤엘 씨가 이렇게까지 감정을 드러낸 적은 없었는데...\n그래서 나도 모르게 기억 일부를 보고 말았어...)",
  ui_story_5071_50710402_74_dialog_content = "우리 PlayerName, 왜 아직도 멍하니 있을까?",
  ui_story_5071_50710402_75_dialog_content = "아니면...",
  ui_story_5071_50710402_76_dialog_content = "갑자기 내 과거에 흥미가 생긴 걸까?",
  ui_story_5071_50710402_77_dialog_content = "아, 그게...",
  ui_story_5071_50710402_78_dialog_content = "어쩐지 형아가 이상하게 생각한다 했어.\n나도 사장님이 이렇게 진심으로 기뻐하는 거 처음 봤거든!",
  ui_story_5071_50710402_79_dialog_content = "버질, 그렇게 이본 여사님 작품이 마음에 든다면...",
  ui_story_5071_50710402_80_dialog_content = "출판사에 투자해서 이본 여사님한테 우리 전속작가가 되어달라고 할까?",
  ui_story_5071_50710402_81_dialog_content = "네? 그, 그래도 되는 건가요?",
  ui_story_5071_50710402_82_dialog_content = "그 대신 너도 큰일을 해야지. 네가 먼저 골동품에 관한 책을 내는 거야. 어때?",
  ui_story_5071_50710402_83_dialog_content = "으앗... 저, 저... 계속 노력하고 있는걸요...",
  ui_story_5071_50710402_84_dialog_content = "네? 버질이 책을요...?",
  ui_story_5071_50710402_85_dialog_content = "후훗, 어린애라고 무시하면 안 돼. 버질은 진짜 골동품 전문가거든.\n뭐든지 감정할 수 있다니까~",
  ui_story_5071_50710402_86_dialog_content = "그, 그렇게까지 대단한 건 아닌걸요...",
  ui_story_5071_50710402_87_dialog_content = "그럼 마침 잘됐네! 방금 오다가 원고지를 주웠거든. 이걸 보고 뭔가 알아내 줄 수 있어?",
  ui_story_5071_50710402_88_dialog_content = "음... 이 원고지는 요즘 사람들이 흔히 쓰는 종류인데...",
  ui_story_5071_50710402_89_dialog_content = "어? 잠깐만! 이거...",
  ui_story_5071_50710501_1_dialog_content = "이게 정말 이본 여사님 원고인 게 확실하니?",
  ui_story_5071_50710501_2_dialog_content = "네. 게다가 제가 알기론 이건 출판된 적 없는 신작 원고예요!",
  ui_story_5071_50710501_3_dialog_content = "근데 이 원고지는 이미 몇 년 된 것 같은데, 왜 지금까지 출판을 안 했을까?",
  ui_story_5071_50710501_4_dialog_content = "작가들의 작품이란 건 종종 여러 가지 이유 때문에 바로 출판할 수가 없거든.\n그리고 여기 좀 봐, 맨 아래 몇 장은 완전 새 거야.",
  ui_story_5071_50710501_5_dialog_content = "어쩌면 옛날 작품을 최근에 이어서 쓰기 시작하신 걸지도 몰라!\n으아아아... 너무 읽고 싶어...",
  ui_story_5071_50710501_6_dialog_content = "버질, 그럼 일단 원고를 이본 선생님한테 돌려주는 게 좋지 않을까?",
  ui_story_5071_50710501_7_dialog_content = "으아아아... 첫 문장만 읽어도 벌써 눈가가 촉촉해져!\n마지막으로 선생님 작품을 읽었을 땐 내 키가 아직 용주 골동품 의자보다도 작았었는데...",
  ui_story_5071_50710501_8_dialog_content = "그렇게 대단하다고? 대체 뭐가 쓰여 있길래...",
  ui_story_5071_50710501_9_dialog_content = "푸른 벽돌을 깔아놓은 큰길을 따라, 성밖으로 나가 백야성 역참 입구 앞까지 가면,\n공터 위 하얗게 빛나는 돌무더기를 육안으로 볼 수 있었다.",
  ui_story_5071_50710501_10_dialog_content = "종종 그 유래도 모른 채 돌무더기 안에서 숨바꼭질을 하는 아이들이 있었고,\n그럴 때면 늘 참견하기를 좋아하는 어른이 나타나 아이들을 겁주고는 했다.",
  ui_story_5071_50710501_11_dialog_content = "「이 꼬맹이들, 그런 데서 잘도 노는구나. 너네 거기가 옛날에 어떤 곳이었는지 알기나 해?」",
  ui_story_5071_50710501_12_dialog_content = "아이들은 배를 쭉 내밀고 아무것도 두렵지 않다는 듯 답했다.\n「그걸 왜 몰라요? 센트리 폰드잖아요.」",
  ui_story_5071_50710501_13_dialog_content = "「시내에서 그 이름 걸고 노름하는 투기장 따위랑 같은 줄 아나 본데,\n너네 거기서 몇 명이나 죽었는지는 알아?」",
  ui_story_5071_50710501_14_dialog_content = "아이들이 갑자기 조용해지자, 어른은 더 흥이 나서 말했다.\n「100명 중에 살아서 나온 사람은 단 한 명뿐이었다니까!」",
  ui_story_5071_50710501_15_dialog_content = "그러나 그것은 거짓말이 아니었다.\n센트리 폰드는 본래부터 귀족들이 사람 목숨을 가지고 즐기는 곳이었다.",
  ui_story_5071_50710501_16_dialog_content = "각종 죄목의 범죄자들이 무겁고 두꺼운 쇠사슬을 동물처럼 매고,\n「우르르」 쏟아지듯 안으로 내던져져 서로를 죽인다.",
  ui_story_5071_50710501_17_dialog_content = "물론 개중에는 죽음도 두려워하지 않고 자원해서 들어간 자들도 더러 있었는데,\n그저 굶주린 배를 채우기 위해서거나, 귀족 나리의 눈에 들길 바라서인 경우였다.",
  ui_story_5071_50710501_18_dialog_content = "그러나 때로는 속아서 그곳에 빠진 자도 있었다.",
  ui_story_5071_50710501_19_dialog_content = "(움브라톤의 치안관이 암흑가와 결탁했다는 사실을 백야성 심판관에게 알릴 수만 있다면...)",
  ui_story_5071_50710501_20_dialog_content = "(돈만 보고 남의 목숨을 해치는 저 쓰레기들도 없애고, 움브라톤을 구할 수 있을 거야!)",
  ui_story_5071_50710501_21_dialog_content = "(그나저나... 심판관이 정말 이런 곳에 있나?)",
  ui_story_5071_50710501_22_dialog_content = "아, 안 돼──",
  ui_story_5071_50710501_23_dialog_content = "멈춰라!",
  ui_story_5071_50710501_24_dialog_content = "이러지 마! 당장 가야 한다고!",
  ui_story_5071_50710501_25_dialog_content = "너 경비병한테 쫓기고 있잖아. 범죄자냐?",
  ui_story_5071_50710501_26_dialog_content = "아, 아니야! 너... 보니까 너도 움브라톤 사람 같은데, 제발 좀 도와줘!",
  ui_story_5071_50710501_27_dialog_content = "난 귀족들이 움브라톤에서 벌이는 악행을 심판소에 고발하러 왔을 뿐이야!\n그런데 오히려 경비병들이 날 잡으려고 한다고!",
  ui_story_5071_50710501_28_dialog_content = "감옥에 보내는 거면 그렇다 쳐도, 놈들은 날 센트리 폰드에 처넣을 생각이야!\n그, 그건 날 죽이겠다는 거나 다름없다고!",
  ui_story_5071_50710501_29_dialog_content = "(뭐야, 나보다 먼저 고발하러 온 사람이 있었단 말이야?!\n잠깐, 그럼 심판소도 믿을 수 없다는 건가? 아니면... 설마 온 백야성이...)",
  ui_story_5071_50710501_30_dialog_content = "도망칠 수 있을 줄 알았냐!",
  ui_story_5071_50710501_31_dialog_content = "이미 포위당한 건가?! 아무래도... 도망치긴 힘들겠어.",
  ui_story_5071_50710501_32_dialog_content = "벌써부터 포기하면 안 되지.",
  ui_story_5071_50710501_33_dialog_content = "어이, 너! 비켜라!",
  ui_story_5071_50710501_34_dialog_content = "이 사람은 싸우는 법조차 모른다.\n대체 이 사람이 무슨 죄를 지었고, 어디로 데려가려는 거지?",
  ui_story_5071_50710501_35_dialog_content = "안 보내줄 작정인가? 뭐, 상관없지. 머릿수만 채우면 그만이니까.\n그럼 네놈이 대신 들어갈 테냐?",
  ui_story_5071_50710501_36_dialog_content = "그런 말도 안 되는 억지라니... 저놈들, 날 살려줄 생각이 전혀 없는 거야...",
  ui_story_5071_50710501_37_dialog_content = "그래... 이게 내 결말이구나... 어차피 가문에선 아버지한테 미움받고, 밖에서도...",
  ui_story_5071_50710501_38_dialog_content = "내가 대신 가지.",
  ui_story_5071_50710501_39_dialog_content = "...뭐? 그게 뭔 소리야?! 내가 누군지도 모르면서 나 대신 죽으러 가겠다고?\n지금 이게 장난인 줄 알아?!",
  ui_story_5071_50710501_40_dialog_content = "내가 뭘 하는지 정도는 알고 있다.",
  ui_story_5071_50710501_41_dialog_content = "넌 딱 봐도 공부깨나 한 것 같은데, 그럼 나 같은 놈보단 움브라톤을 구할 방법을 더 잘 알겠지.\n만약 내가 가서 못 돌아온다면, 내 부탁 하나만 들어줘라.",
  ui_story_5071_50710501_42_dialog_content = "움브라톤을 살리는 거다.",
  ui_story_5071_50710501_43_dialog_content = "......",
  ui_story_5071_50710501_44_dialog_content = "오늘 이 자리에는 무려 자원해서 참가한 용사가 한 명 있습니다!",
  ui_story_5071_50710501_45_dialog_content = "다른 참가자들은 운이 참 좋군요!\n가장 먼저 그 용사를 쓰러트리고 살아남는 자는 백작님께서 두 배의 상금을 하사하실 겁니다!",
  ui_story_5071_50710501_46_dialog_content = "으하하하하──",
  ui_story_5071_50710501_47_dialog_content = "그래! 저놈이야! 저 머리에 뿔 달린 놈!",
  ui_story_5071_50710501_48_dialog_content = "......",
  ui_story_5071_50710501_49_dialog_content = "죽여──!",
  ui_story_5071_50710501_50_dialog_content = "여기 던져진 자들은 이미 이성조차 악마에게 바쳐버린 건가.",
  ui_story_5071_50710501_51_dialog_content = "빨리 가서 조져! 멍청한 놈들이 뭘 꾸물대고 있어?!",
  ui_story_5071_50710501_52_dialog_content = "바깥의 저놈들한테 이용당하고 있을 뿐인데도...",
  ui_story_5071_50710501_53_dialog_content = "저놈 막아! 같이 살아서 상금도 나눠 먹자고!",
  ui_story_5071_50710501_54_dialog_content = "근데 살아남을 수 있는 건 한 명뿐이잖아?",
  ui_story_5071_50710501_55_dialog_content = "아무튼 그게 저 뿔 달린 놈은 아니겠지!",
  ui_story_5071_50710501_56_dialog_content = "그럼 멍청하게 서 있지 말고 어디 다 덤벼봐라!",
  ui_story_5071_50710502_1_dialog_content = "관중석에서는 점점 더 큰 환호성이 터져 나왔고,\n다른 참가자가 한주먹에 나가떨어질 때마다 환호성이 거듭됐다.",
  ui_story_5071_50710502_2_dialog_content = "푸른 불꽃에 휩싸인 주먹이 금세라도 자신을 향할까 두렵기라도 한 듯,\n치맛자락을 손에 쥐고 맨 뒷줄로 도망쳐 숨는 관객도 있었다.",
  ui_story_5071_50710502_3_dialog_content = "야수처럼 강인하고, 악마처럼 흉포한 청년은 마지막 상대를 쓰러트리자 비로소 멈추었고,\n관객들도 그제서야 참았던 숨을 내쉴 수 있었다.",
  ui_story_5071_50710502_4_dialog_content = "저놈이 이겼어! 다른 놈들이 전부 달려들었는데도 이겨버렸다고!",
  ui_story_5071_50710502_5_dialog_content = "저놈도 중상이야. 다른 놈들은 전부 무기를 숨기고 있었거든. 저 몸의 칼자국 좀 봐...",
  ui_story_5071_50710502_6_dialog_content = "내가 세 봤는데 천 번은 베였어!",
  ui_story_5071_50710502_7_dialog_content = "천 번?!",
  ui_story_5071_50710502_8_dialog_content = "......",
  ui_story_5071_50710502_9_dialog_content = "...이제 돌아가도 되겠지.",
  ui_story_5071_50710502_10_dialog_content = "네가 지킨 놈은 돌아가도 좋다. 하지만 넌──",
  ui_story_5071_50710502_11_dialog_content = "얘들아?",
  ui_story_5071_50710502_12_dialog_content = "내 말 들었니?",
  ui_story_5071_50710502_13_dialog_content = "으아아악?! 무, 무슨 일이죠...?",
  ui_story_5071_50710502_14_dialog_content = "둘 다 푹 빠져서 날 아예 잊어버렸잖아.",
  ui_story_5071_50710502_15_dialog_content = "나도 끼워달라고 하고 싶지만, 그 전에 처리할 급한 일이 있거든.",
  ui_story_5071_50710502_16_dialog_content = "어쨌든, 너흰 그 원고부터 얼른 이본 여사님께 돌려드리고 오는 게 좋겠어.",
  ui_story_5071_50710502_17_dialog_content = "그리고 버질 너, 이따가 경매 일도 잊지 말고.",
  ui_story_5071_50710502_18_dialog_content = "아, 알겠어요!",
  ui_story_5071_50710502_19_dialog_content = "이본 선생님은 지금 이스타반 씨랑 면담 중이겠지? 그럼 이스타반 씨한테 가 볼까?",
  ui_story_5071_50710502_20_dialog_content = "근데 형아... 우리 읽던 거 딱 불편한 곳에서 끊겼잖아...",
  ui_story_5071_50710502_21_dialog_content = "사, 살짝만 더 보면 안 돼?",
  ui_story_5071_50710502_22_dialog_content = "크흠... 그럼 조금만... 더 볼까?",
  ui_story_5071_50710502_23_dialog_content = "응! 조금만!",
  ui_story_5071_50710601_1_dialog_content = "<color=#e8d9bb>부유 비공정, 호화 객실</color>",
  ui_story_5071_50710601_2_dialog_content = "존귀하신 섀도우마스터, 이번 회담 기회를 주셔서 감사합니다.\n대륙상회를 대표해 당신께 최고의 경의를 표합니다.",
  ui_story_5071_50710601_3_dialog_content = "대륙상회의 비밀스러운 한스티 회장이 너였다니, 한스티라는 성이 아니었던 것으로 기억하는데.",
  ui_story_5071_50710601_4_dialog_content = "피차일반이잖아요.",
  ui_story_5071_50710601_5_dialog_content = "...많이 달라졌군.",
  ui_story_5071_50710601_6_dialog_content = "뭐 달라진 게 있나요? 아... 제 다리 얘긴가요?",
  ui_story_5071_50710601_7_dialog_content = "어둠의 위기 때, 전 움브라톤이 포위되기 직전에 큰돈을 들여 간신히 도망쳤어요...\n하지만 도중에 암귀를 만났죠...",
  ui_story_5071_50710601_8_dialog_content = "뭐, 별거 아니에요. 그 일 아니었으면 의족이 이렇게 편리한 건지도 몰랐을 테니까요.",
  ui_story_5071_50710601_9_dialog_content = "하하, 정말 많이 변했군. 그때보다 더 낙천적이고, 강해졌어.",
  ui_story_5071_50710601_10_dialog_content = "어쩔 수 없잖아요. 경험이 쌓일수록 사람은 성장하기 마련인걸요.",
  ui_story_5071_50710601_11_dialog_content = "네 상회도 제법 대단하던데, 총상회의 금지령도 무시하고 위험한 투자를 할 배짱도 있고 말이야.",
  ui_story_5071_50710601_12_dialog_content = "후훗. 역시 그림자는 언제나 지켜보고 있었군요.",
  ui_story_5071_50710601_13_dialog_content = "그래도 그렇지, 모처럼 만난 옛 친구 체면이라고는 전혀 안 봐주는군요.\n좋은 마음으로 만나러 왔는데, 말도 몇 마디 안 나누고 면박부터 주고 말이에요.",
  ui_story_5071_50710601_14_dialog_content = "옛 친구이기 때문에 오히려 네가 잘되길 바라는 것이다.",
  ui_story_5071_50710601_15_dialog_content = "이해가 안 되는데요. <color=#FFB400>당신의 움브라톤</color>은 자유롭고 포용력 있는 도시 아니었나요?",
  ui_story_5071_50710601_16_dialog_content = "대형 카지노는 움브라톤에 더 많은 이익을 가져다주고, 백야성에 낼 「세금」도\n힘 하나 안 들이고 넉넉하게 낼 수 있게 해 줄 텐데, 이렇게 좋은 일을 왜 마다하는 거죠?",
  ui_story_5071_50710601_17_dialog_content = "예전의 넌 그렇게 돈을 쫓는 사람이 아니었다.\n예술이나 문학을 더 좋아하고, 늘 붓을 잡고 있던 소녀였지.",
  ui_story_5071_50710601_18_dialog_content = "바뀐 건 저뿐만이 아니잖아요.",
  ui_story_5071_50710601_19_dialog_content = "저도 못 믿겠는걸요. 그때 그 궁상맞던 청년이 모습을 완전히 바꾸고는,\n「양치기의 지팡이」를 들고 명실상부한 <color=#FFB400>이스타반</color>이 됐잖아요?",
  ui_story_5071_50710601_20_dialog_content = "......",
  ui_story_5071_50710601_21_dialog_content = "그래, 영원히 변하지 않는 것은 없다. 그리고 움브라톤도 변혁을 이루는 중이지.",
  ui_story_5071_50710601_22_dialog_content = "움브라톤은 너의 것도 아니고, 내 것도 아니다.",
  ui_story_5071_50710601_23_dialog_content = "이곳에서 넌 자유롭게 사업을 해도 좋다. 하지만 그 「검은 사업」들만은 손대선 안 된다.\n그것들을 없애는 건 <color=#FFB400>배런</color>의 꿈이기도 했으니 말이야.",
  ui_story_5071_50710601_24_dialog_content = "당신...",
  ui_story_5071_50710601_25_dialog_content = "왜 이렇게 된 거야...? 이러면 주인공이 너무 비참하잖아...",
  ui_story_5071_50710601_26_dialog_content = "백야성 성주도 만났는데 결국 귀족들한테 모함당해서 감옥에 갇히다니...",
  ui_story_5071_50710601_27_dialog_content = "백야성 성주는 움브라톤에 대한 주인공의 생각을 전혀 들을 마음이 없었던 거야.\n그저 투견 취급했을 뿐이고... 이용할 수 없다는 걸 알게 되니까 흥미가 사라졌던 거지.",
  ui_story_5071_50710601_28_dialog_content = "이번 작품 내용은 왠지 지금까지 본 선생님 작품들보다 훨씬 복잡한 거 같아...\n나 주인공이 감옥에서 나와서 어떻게 됐을지 너무 궁금해.",
  ui_story_5071_50710601_29_dialog_content = "그럼 우리 조금만... 더 볼까?",
  ui_story_5071_50710601_30_dialog_content = "응! 진짜로 조금만!",
  ui_story_5071_50710601_31_dialog_content = "묘지의 공기는 시가지보다 더 차가웠다.\n어쩌면 그가 오랫동안 이곳에 서 있었던 탓일지도 모른다.",
  ui_story_5071_50710601_32_dialog_content = "집을 떠날 적에 그는 부모에게 「다녀올게」라고 짧은 한마디를 던졌다.\n어느덧 몇 년의 시간이 흘렀고, 지금의 그에겐 「다녀왔어」라고 말할 상대조차 없었다.",
  ui_story_5071_50710601_33_dialog_content = "등 뒤에서 발소리가 다가오자, 그는 돌아보지도 않은 채 냉랭하게 경고했다.\n「목적이 뭔지부터 말하는 게 좋을 거다.」",
  ui_story_5071_50710601_34_dialog_content = "「케이드... 드디어 돌아왔구나.」 상대가 답했다.",
  ui_story_5071_50710601_35_dialog_content = "케이드는 뒤를 돌아보았고, 그곳에는 어디선가 본 듯한 사람이 서 있었다.\n「내가 그쪽을 아나?」",
  ui_story_5071_50710601_36_dialog_content = "전에 센트리 폰드에서 사람을 구했었지...? 그때 그게 나야.",
  ui_story_5071_50710601_37_dialog_content = "넌 나 때문에 오랫동안 고생해 왔어. 그러니까 나도 보고만 있을 순 없잖아.",
  ui_story_5071_50710601_38_dialog_content = "이제 넌 돌아갈 집도 없어 보이는데, 괜찮다면 우리 집으로 와도 좋아.\n앞으로 난 널 형제처럼 대할 테니까!",
  ui_story_5071_50710601_39_dialog_content = "난 아직 그쪽 이름도 모르는데...",
  ui_story_5071_50710601_40_dialog_content = "배런, 난 배런이야.",
  ui_story_5071_50710601_41_dialog_content = "두 청년은 곧 공통의 취미를 발견했다.",
  ui_story_5071_50710601_42_dialog_content = "...센트리 폰드에서 돌아온 뒤로 계속 연습했어.",
  ui_story_5071_50710601_43_dialog_content = "뭐, 체스를?",
  ui_story_5071_50710601_44_dialog_content = "아니, 루미나틱스. 나도 언젠간 너처럼 압도적인 힘을 갖고 싶었거든.",
  ui_story_5071_50710601_45_dialog_content = "그렇게 따지면 나도 너처럼 압도적인 체스 실력을 갖고 싶은데 말이야.",
  ui_story_5071_50710601_46_dialog_content = "하하, 너도 체스를 좋아할 줄은 진짜 몰랐다니까. 어디 선생님한테 배웠어?",
  ui_story_5071_50710601_47_dialog_content = "...우리 아버지.",
  ui_story_5071_50710601_48_dialog_content = "...미안해, 괜한 말을 꺼냈네... 대신 앞으로는 우리 아버지가 네 아버지야!",
  ui_story_5071_50710601_49_dialog_content = "아버지는 널 정말 좋아하시니까, 널 입양해 달라고 할게!\n그럼 우린 진짜 형제가 되는 거라고!",
  ui_story_5071_50710601_50_dialog_content = "......",
  ui_story_5071_50710601_51_dialog_content = "그때 난 네가 나 대신 그 생사의 싸움판에 서는 걸 거절할 수 없었어.\n그러니까 너도 거절하지 마, 부탁이야.",
  ui_story_5071_50710601_52_dialog_content = "...난 그저 내가 돌아온 뒤에도 움브라톤이 예전 모습 그대로,\n아무것도 변하지 않은 게 걱정될 뿐이야.",
  ui_story_5071_50710601_53_dialog_content = "...생각해 봤어. 우리가 백야성에만 기대를 건다면, 움브라톤은 영원히 변할 수 없을 거야.",
  ui_story_5071_50710601_54_dialog_content = "어둠 속에 숨어서 움브라톤의 골수를 빨아먹는 저 해충들은...\n우리가 우리 힘으로 제거해야 해.",
  ui_story_5071_50710601_55_dialog_content = "움브라톤... 본그림자라는 뜻이 담긴 이 이름을 대체 누가 지은 거지?\n왜 우리가 꼭 남의 그림자여야만 하는 거냐고. 우리도 자기 미래가 있어야 하는 거잖아!",
  ui_story_5071_50710601_56_dialog_content = "미래... 맞아, 미래의 이 도시는 자유롭고, 단결된...\n그 누구의 지배도 받지 않는 곳이 돼야만 해!",
  ui_story_5071_50710601_57_dialog_content = "그래, 물론 나도 그러길 바라고 있어.\n하지만 과거의 어둠에서 완전히 벗어나는 건 그렇게 쉬운 일이 아냐...",
  ui_story_5071_50710601_58_dialog_content = "어쩌면 우린 앞으로 더 오랜 시간 동안... 저들과 공존하는 법을 배우고,\n심지어 저들의 일부가 되어야 할 수도 있겠지...",
  ui_story_5071_50710601_59_dialog_content = "아니, 그 독들을 없애고 싶다면 서두르는 방법밖에 없어! 타협은 결코 있을 수 없다고.",
  ui_story_5071_50710601_60_dialog_content = "음...?",
  ui_story_5071_50710601_61_dialog_content = "왜 그래?",
  ui_story_5071_50710601_62_dialog_content = "문 뒤에 엿듣는 사람이 있는데... 괜찮아?",
  ui_story_5071_50710601_63_dialog_content = "아... 쟨 <color=#FFB400>에바</color>라고 해. 아버지 친구 딸이고, 내 친구기도 해, 신경 쓸 거 없어.",
  ui_story_5071_50710601_64_dialog_content = "누구보고 그냥 친구래?!",
  ui_story_5071_50710601_65_dialog_content = "배런의 행동력에 케이드는 늘 감탄했다.\n그리고 이제 배런은 상회의 회장인 아버지의 지지를 얻어낼 생각이었다.",
  ui_story_5071_50710601_66_dialog_content = "안 된다!",
  ui_story_5071_50710601_67_dialog_content = "대체 왜죠? 우린 옳은 일을 하려는 거잖아요!",
  ui_story_5071_50710601_68_dialog_content = "남의 피를 빨아먹고 사는 암흑가 조직도, 놈들과 다를 거 없는 상회도...\n전부 움브라톤의 독이잖아요!",
  ui_story_5071_50710601_69_dialog_content = "우리가 서두른다면 전부 다 뿌리째 뽑아버릴 수 있을 거라고요!",
  ui_story_5071_50710601_70_dialog_content = "그걸 할 수 있었다면 이미 진작에 누군가 했겠지.\n움브라톤은 비록 혼돈의 땅이지만, 대신 결코 쓰러지지 않는 균형을 유지하고 있다.",
  ui_story_5071_50710601_71_dialog_content = "내가 대체 몇 번이나 말한 거냐. 순진하게 굴지 마라. 아직도 포기를 안 했다니...\n지난번에 얻은 교훈으로도 모자랐던 거냐?",
  ui_story_5071_50710601_72_dialog_content = "그때는 요행으로 케이드를 만났으니 망정이지, 다음에도 네가 무사할 성싶으냐?",
  ui_story_5071_50710601_73_dialog_content = "그땐 너나 케이드뿐만 아니라 온 가문이 네놈 때문에 파멸할 거다!",
  ui_story_5071_50710601_74_dialog_content = "아버지!",
  ui_story_5071_50710601_75_dialog_content = "배런은 원래부터 아버지와 사이가 좋지 않았다.\n그러나 이제 그의 곁에는 케이드라는 경청자가 있었다...",
  ui_story_5071_50710601_76_dialog_content = "아버지는 내가 그리는 움브라톤의 미래상을 듣는 것조차 원하지 않으셔...",
  ui_story_5071_50710601_77_dialog_content = "말해, 내가 듣고 있잖아.",
  ui_story_5071_50710601_78_dialog_content = "크흠. 지금 상회들이 왜 암흑가의 손에 놀아나고 있는지 알아?\n그건 상회들이 저마다 자기 뜻대로만 하고 있기 때문이야.",
  ui_story_5071_50710601_79_dialog_content = "난 모든 상회가 연합해서 하나의 이익공동체가 돼야 한다고 생각해. 이름은...",
  ui_story_5071_50710601_80_dialog_content = "...총상회 어때?",
  ui_story_5071_50710601_81_dialog_content = "그래, 총상회라고 하자고! 그렇게 모두의 이익이 서로 연결된다면,\n저들도 서로를 돕고, 단결해서 적과 맞설 수 있게 되겠지!",
  ui_story_5071_50710601_82_dialog_content = "암흑가 조직도, 놈들과 결탁하는 상회도, 용병단도...\n그리고 백야성에도 맞설 수 있을 거야.",
  ui_story_5071_50710601_83_dialog_content = "그렇게 해서 움브라톤을 갉아먹는 모든 독을 뿌리 뽑고 나면,\n여긴 그 어떤 불순물도 없는... 상인들의 천국이 될 거야.",
  ui_story_5071_50710601_84_dialog_content = "그때가 되면... 난 내가 세운 대상회를 이끌고 가 본 적 없는 머나먼 곳으로 떠날 거야!",
  ui_story_5071_50710601_85_dialog_content = "거길 어떻게 갈 건데?",
  ui_story_5071_50710601_86_dialog_content = "음... 차로 가야지 뭐 별 수 있나... 아, 그래! 헤븐즈 밸리에 가서 콜로서스를 한 대 사자고!\n그리고 콜로서스에 상회를 만드는 거야!",
  ui_story_5071_50710601_87_dialog_content = "상회를 이끌고 하늘을 날면서, 산들바람과 햇살을 받으며 자유롭게 대륙을 오가고,\n모든 사람들과 평등하게 거래를 하는 거지!",
  ui_story_5071_50710601_88_dialog_content = "출신도, 빈부도 따지지 않고 누구든지 내 상회에 받아줄 거야.\n노력만 하면 수고의 대가를 받을 수 있는 그런 상회를 만들 거라고!",
  ui_story_5071_50710601_89_dialog_content = "......",
  ui_story_5071_50710601_90_dialog_content = "...케이드, 왜 그래? 내 말이 별로였어?",
  ui_story_5071_50710601_91_dialog_content = "아니, 아주 멋진 말이었어. 정말 아름다운 꿈이야. 그림자에게서 벗어나는 방법은...\n어쩌면 정말 하늘을 나는 것뿐일지도 모르겠네.",
  ui_story_5071_50710601_92_dialog_content = "그 꿈을 위해서 난 모든 걸 바칠 수 있어.",
  ui_story_5071_50710601_93_dialog_content = "나도 다 바칠 수 있거든?!",
  ui_story_5071_50710601_94_dialog_content = "에바 넌 장사 같은 거 싫어하는 거 아니었어?",
  ui_story_5071_50710601_95_dialog_content = "맞아... 대신 난 그림을 그릴 수 있으니까, 내가 멋진 콜로서스를 디자인해 줄게!",
  ui_story_5071_50710601_96_dialog_content = "하하, 콜로서스를 우리가 설계할 필요는 없어.",
  ui_story_5071_50710601_97_dialog_content = "그러나 꿈을 그려나가는 즐거운 분위기는 다음 대국까지 이어지지 않았다.",
  ui_story_5071_50710601_98_dialog_content = "왜 그래? 뭐 안 좋은 일이라도 있어?",
  ui_story_5071_50710601_99_dialog_content = "아버지가 같이 거래 상대를 만나러 가자고 하셨어.",
  ui_story_5071_50710601_100_dialog_content = "이제야 상회 일을 가르쳐 주실 마음이 생기셨구나.\n그거 잘됐네. 우리의 꿈을 위해서도 도움이 될 거야.",
  ui_story_5071_50710601_101_dialog_content = "아니, 아니야... 아버지가 나한테 소개해 주려는 건...",
  ui_story_5071_50710601_102_dialog_content = "독약을 파는 상인이야. 아버지가 그 사람과 거래하고 있다는 건, 다시 말해서...",
  ui_story_5071_50710601_103_dialog_content = "우리 가문도 더는 깨끗하지 못하다는 뜻이겠지... 역시 아버지가 날 막으셨던 이유가 있었어.",
  ui_story_5071_50710601_104_dialog_content = "앞으로 어떻게 아버지를 대해야 할지 모르겠어... 그리고 앞으로 내가 어떻게 해야 할지도...",
  ui_story_5071_50710601_X104_dialog_content = "...우리의 꿈을 위해 너희 아버지의 자원도 이용할 수 있을 거야.",
  ui_story_5071_50710601_105_dialog_content = "그걸 이용한다고...? 농담이지? 케이드...",
  ui_story_5071_50710601_106_dialog_content = "...네가 그런 말을 할 줄은 몰랐어.",
  ui_story_5071_50710601_107_dialog_content = "아무튼, 무슨 일이 있어도... 넌 내 편인 거지?",
  ui_story_5071_50710601_108_dialog_content = "......",
  ui_story_5071_50710601_109_dialog_content = "계속하자. 이번엔 네가 「백」, 내가 「흑」이야.",
  ui_story_5071_50710601_110_dialog_content = "배런은 알지 못했다. 이번에는 케이드가 자신보다 먼저 움직였다는 것을.",
  ui_story_5071_50710601_111_dialog_content = "독약을 다 태워라!",
  ui_story_5071_50710601_112_dialog_content = "예!",
  ui_story_5071_50710601_113_dialog_content = "으아악──!",
  ui_story_5071_50710601_114_dialog_content = "가만히 있어!",
  ui_story_5071_50710601_115_dialog_content = "왜 날 노린 거지? 도대체 내가 당신이랑 무슨 원수를 졌다고 이래?!",
  ui_story_5071_50710601_116_dialog_content = "이 독약들을 움브라톤에서 팔아치우면, 또 수많은 사람과 그 가족들이 무너질 거다.",
  ui_story_5071_50710601_117_dialog_content = "흥, 백야성 심판소도 가만히 있는데 당신이 그걸 왜 따져?!",
  ui_story_5071_50710601_118_dialog_content = "...당신 대체 누구야?",
  ui_story_5071_50710601_119_dialog_content = "내가 누구냐고? 난... 그저 이 거리를 서성이는 그림자일 뿐이다.",
  ui_story_5071_50710601_120_dialog_content = "얼마 후, 놀랍게도 배런의 아버지는 케이드를 입양하겠다고 제안했다.\n그러나 서약식 자리에 배런의 모습은 없었다.",
  ui_story_5071_50710601_121_dialog_content = "케이드는 그를 걱정했지만, 근심을 얼굴에 드러내지 않았다.\n고개를 든 그의 검은 두 뿔은 날카롭게 빛났고, 맹세의 말을 나직하게 꺼냈다.",
  ui_story_5071_50710601_122_dialog_content = "「...결코 가족을 해치지 않겠습니다.」",
  ui_story_5071_50710601_123_dialog_content = "「결코 가문의 이익을 침해하지 않을 것이며...」",
  ui_story_5071_50710701_1_dialog_content = "「배런」의 꿈? 지금 그런 말이 잘도 입에서 나오는군요!",
  ui_story_5071_50710701_2_dialog_content = "당신이 모든 걸 망쳤으면서!",
  ui_story_5071_50710701_3_dialog_content = "미안하군, 한스티 회장...",
  ui_story_5071_50710701_4_dialog_content = "하지만 충고를 하나 하도록 하지... 네가 선택한 파트너에 대한 일이다.",
  ui_story_5071_50710701_5_dialog_content = "사업에 관해서라면 나도 능통하다고 할 순 없겠지.",
  ui_story_5071_50710701_6_dialog_content = "하지만 움브라톤에서 합법적으로 돈을 벌고 싶다면, 뭐든지 샤엘과 논의하면 좋을 것이다.",
  ui_story_5071_50710701_7_dialog_content = "약속하지, 내가 도울 수 있는 일이라면 얼마든지 돕겠다.",
  ui_story_5071_50710701_8_dialog_content = "당신 「약속」 따윈 필요 없으니까 아껴 두세요. 섀도우마스터.",
  ui_story_5071_50710701_9_dialog_content = "아무래도 내게 깊은 오해가 있는 모양이군.",
  ui_story_5071_50710701_10_dialog_content = "다음에 기회가 되면 다시 앉아서 옛날이야기를 해 보자고.",
  ui_story_5071_50710701_11_dialog_content = "섀도우마스터, 다음 손님과의 면담 시간입니다...",
  ui_story_5071_50710701_12_dialog_content = "알겠다.",
  ui_story_5071_50710701_13_dialog_content = "한스티 회장, 오늘 다시 만날 수 있어서 기쁘게 생각한다.",
  ui_story_5071_50710701_14_dialog_content = "그림자 속 존재와 접촉할 때는 불필요한 문제에 휘말리지 않게 조심해라.",
  ui_story_5071_50710701_15_dialog_content = "후훗. 충고에 감사드립니다, 섀도우마스터.\n하지만 전 제가 뭘 하고 있는지 잘 알고 있어요.",
  ui_story_5071_50710701_16_dialog_content = "누구처럼 입으로만 옛 친구의 「꿈」을 기억한다고 말하진 않을 테니까요.",
  ui_story_5071_50710701_17_dialog_content = "그런데... 생각해 보신 적 있나요?",
  ui_story_5071_50710701_18_dialog_content = "이 오랜 시간 동안, 그 누군가는 정말 친구의 「꿈」을 위해 무언가 바친 게 있나요?",
  ui_story_5071_50710701_19_dialog_content = "......",
  ui_story_5071_50710701_20_dialog_content = "이상하네... 원고가 어디 갔지...",
  ui_story_5071_50710701_21_dialog_content = "설마 방에 두고 왔나...",
  ui_story_5071_50710701_22_dialog_content = "이본 여사님! 여사님 차례야!",
  ui_story_5071_50710701_23_dialog_content = "자, 한스티 씨, 이쪽입니다.",
  ui_story_5071_50710701_24_dialog_content = "아... 금방 갈게요... 어머?",
  ui_story_5071_50710701_25_dialog_content = "당신... 젊은 나이인데 눈동자에 거친 풍파가 담겨 있군요.",
  ui_story_5071_50710701_26_dialog_content = "그 다리... 어머, 나 좀 봐... 또 직업병이 도졌네요... 언짢았다면 미안해요.",
  ui_story_5071_50710701_27_dialog_content = "아니에요, 전 괜찮아요.",
  ui_story_5071_50710701_28_dialog_content = "사실 당신에게서 느껴지는 이야기의 영감이 절 끌어당겼거든요.",
  ui_story_5071_50710701_29_dialog_content = "게다가... 그 백합 향기...",
  ui_story_5071_50710701_30_dialog_content = "옛 친구가 생각이 나네요. 그 사람에게서도 늘 매혹적인 백합 향기가 났거든요.",
  ui_story_5071_50710701_31_dialog_content = "후훗, 그렇게 말씀해 주시니 기쁘네요. 마침 머큐리 부인은 제가 동경하는 사람이거든요.",
  ui_story_5071_50710701_32_dialog_content = "전 여사님 작품 속 머큐리 부인이 정말 좋아요.\n신비롭고, 강인하고, 그 무엇에도 구애받지 않죠.",
  ui_story_5071_50710701_33_dialog_content = "그 침묵의 감시자를 보면서 저도 백합을 좋아하게 됐던 거예요.",
  ui_story_5071_50710701_34_dialog_content = "영원히 사라지지 않는 기억, 위대한 사랑, 진심 어린 축복... 그게 백합의 꽃말이었죠?",
  ui_story_5071_50710701_35_dialog_content = "다만 《레드 머큐리》의 속편은 도저히 좋아할 수 없었어요.\n전 머큐리 부인이 더 나은 결말을 맞이할 자격이 있다고 생각해요.",
  ui_story_5071_50710701_36_dialog_content = "...우리 혹시 전에 만난 적 있나요?",
  ui_story_5071_50710701_37_dialog_content = "아뇨, 없는 것 같네요.",
  ui_story_5071_50710701_38_dialog_content = "이본 선생님...!",
  ui_story_5071_50710701_39_dialog_content = "어머... 누가 부르는 것 같은데...",
  ui_story_5071_50710701_40_dialog_content = "이본 여사님, 섀도우마스터께서 기다리고 계십니다.",
  ui_story_5071_50710701_41_dialog_content = "아! 미안해요... 지금 갈게요.",
  ui_story_5071_50710701_42_dialog_content = "...한발 늦었잖아. 원고를 못 드렸어...",
  ui_story_5071_50710701_43_dialog_content = "우린 문지기 멍멍이다!",
  ui_story_5071_50710701_44_dialog_content = "엿들으면 안 돼!",
  ui_story_5071_50710701_45_dialog_content = "근데 이거 이본 여사님 원고거든. 너희가 가서 좀 돌려줄 수 있을까?",
  ui_story_5071_50710701_46_dialog_content = "멍멍이는 섀도우마스터를 방해해선 안 돼!",
  ui_story_5071_50710701_47_dialog_content = "정말 고집불통이네...",
  ui_story_5071_50710701_48_dialog_content = "어쩔 수 없지. 입구에서 기다리자.",
  ui_story_5071_50710701_49_dialog_content = "형아, 그럼...",
  ui_story_5071_50710701_X49_dialog_content = "...좀 더 읽어볼까?",
  ui_story_5071_50710701_50_dialog_content = "......",
  ui_story_5071_50710701_51_dialog_content = "사나이들의 대국은 초연 냄새를 풍기고, 치열한 승부는 피비린내마저 느껴졌다.",
  ui_story_5071_50710701_52_dialog_content = "배런은 자신만만하게 기물을 옮겼다.\n「체크메이트.」 승부는 정해졌다.",
  ui_story_5071_50710701_53_dialog_content = "「또 내가 이겼네.」\n배런은 굳이 한마디를 보탰지만, 맞은편의 케이드는 묵묵히 체스말을 치우고 있었다.",
  ui_story_5071_50710701_54_dialog_content = "케이드 수중의 백합이 배런의 눈에 들어왔고, 기회를 잡은 그는 말을 꺼냈다.\n「네 그림자 제국이 또 사람들을 거뒀다면서.」",
  ui_story_5071_50710701_55_dialog_content = "멜리사 부인이 죽고, 부하들이 갈 곳을 잃어서 내가 받아줬어.",
  ui_story_5071_50710701_56_dialog_content = "왜 난 처음 듣는 얘기지?",
  ui_story_5071_50710701_57_dialog_content = "네가 관심 없을 줄 알았는데.",
  ui_story_5071_50710701_58_dialog_content = "아인족 사내가 체스판 정리를 마치자, 배런은 얼굴에 드러났던 쓸쓸함을 숨겼다.",
  ui_story_5071_50710701_59_dialog_content = "두 사람은 말없이 늘 하던 대로 기물을 잡았고, 분위기는 나쁘지 않은 듯했다.",
  ui_story_5071_50710701_60_dialog_content = "아직 근황 얘기를 안 했구나. 이제 나도 좀 성과가 있었거든.\n하긴, 내가 집을 떠난 지도 꽤 됐으니 말이야.",
  ui_story_5071_50710701_61_dialog_content = "주변의 군소 세력들을 규합했고, 빈민들도 우릴 지지하고 있어.\n이대로면 내가 꿈꾸던 대상회가 될 날도 머지않았다고.",
  ui_story_5071_50710701_62_dialog_content = "축하한다.",
  ui_story_5071_50710701_63_dialog_content = "...아버지는 좀 어때?",
  ui_story_5071_50710701_64_dialog_content = "뭐, 그런대로... 지금도 널 그리워하셔.",
  ui_story_5071_50710701_65_dialog_content = "하하, 말하고 보니까 기분이 좀 묘하네. 아버지 얘기를 너한테 묻고 말이야.\n꼭 네가 나보다 더 이스타반 가문의 아들 같잖아.",
  ui_story_5071_50710701_66_dialog_content = "......",
  ui_story_5071_50710701_67_dialog_content = "나도 이제 깨달았어. 스스로 길을 여는 건 역시 쉬운 일이 아냐...\n케이드, 역시 난 아버지한테서 「양치기의 지팡이」를 받아내야겠어.",
  ui_story_5071_50710701_68_dialog_content = "그 지팡이는 우리 가문에 대대로 내려오는 가주의 상징이고,\n그게 있으면 내가 일족의 자원을 장악할 수 있어.",
  ui_story_5071_50710701_69_dialog_content = "그러면 각 세력을 통합해서 움브라톤의 보스들을 소집하고...\n전부 없애버릴 수 있어.",
  ui_story_5071_50710701_70_dialog_content = "파란 머리의 사내는 기물을 옮겼고, 그의 목소리는 온화했다.\n「체크메이트.」",
  ui_story_5071_50710701_71_dialog_content = "벼랑 끝에 몰린 눈앞의 대국을 노려보던 케이드는 시선을 들어 올렸다.\n「너무 극단적이야.」",
  ui_story_5071_50710701_72_dialog_content = "움브라톤을 바꾸고, 약자들을 지키기 위해선 타협이란 있을 수 없어.\n티끌만 한 오점조차 남겨선 안 된다고.",
  ui_story_5071_50710701_73_dialog_content = "그건 그자들에겐 불공평한 처사잖아.",
  ui_story_5071_50710701_74_dialog_content = "내가 듣고 싶은 건 네 약속이야, 케이드.",
  ui_story_5071_50710701_75_dialog_content = "무슨 일이 있어도 넌 날 배신하지 않아, 맞지?\n넌 계속 내 편에서 내 모든 결정을 지지해 줄 거고. 그렇지?",
  ui_story_5071_50710701_76_dialog_content = "아인족 사내는 희미한 망설임에 빠졌고, 바람 소리만이 요란하게 들려오고 있었다.\n두 사람이 찰나의 침묵에 빠진 사이, 쿠리어가 불안한 소식과 함께 찾아왔다.",
  ui_story_5071_50710701_77_dialog_content = "「대규모의 암귀가 집결해서 지금 움브라톤을 향해 진군하고 있어요.」\n쿠리어가 말했다.",
  ui_story_5071_50710701_78_dialog_content = "백야성에서도 움직이고 있는 것 같아요. 움브라톤에 지원군을 보낼지 논의하는 중인데,\n이참에 움브라톤을 완전히 병탄하자고 주장하는 쪽도 있어요.",
  ui_story_5071_50710701_79_dialog_content = "선수들이 다시 움직이기 시작했나... 뭐, 어쩔 수 없지.\n우리가 백야성의 그림자에 머무르는 한, 절대로 이 속박에서 벗어날 수 없어.",
  ui_story_5071_50710701_80_dialog_content = "어떻게든 활로가 있는 법이야... 저들이 대화할 생각이 있다면 우리도 응해야지.",
  ui_story_5071_50710701_81_dialog_content = "「룩」은 계속 네 앞길을 개척할 거다. 넌 자신감을 가지라고, 「킹」.",
  ui_story_5071_50710701_X81_dialog_content = "「달그락」 소리와 함께 체스판 위 대국은 새로운 전개를 맞이했다.",
  ui_story_5071_50710701_X82_dialog_content = "그가 움직인 것은 흑의 「룩」이었으나, 그 행마는 오히려 백의 「킹」을 위한 것이었다.",
  ui_story_5071_50710701_82_dialog_content = "으어어... 골디 씨 방이 이쪽이었나...",
  ui_story_5071_50710701_83_dialog_content = "골디 씨...! 제발 사인 좀 해 줘요...!",
  ui_story_5071_50710701_84_dialog_content = "우린 문지기 멍멍이다!",
  ui_story_5071_50710701_85_dialog_content = "공격 준비!",
  ui_story_5071_50710701_86_dialog_content = "자, 잠깐만! 여긴 나한테 맡겨...",
  ui_story_5071_50710701_87_dialog_content = "또 소란 피웠다간 큰일이니까...",
  ui_story_5071_50710701_88_dialog_content = "당신 누구야?",
  ui_story_5071_50710701_89_dialog_content = "난 골디 씨를 만나러 왔어! 골디 씨...!",
  ui_story_5071_50710702_1_dialog_content = "엄청 끈질기네... 여기 경비 일은 왜 이리 힘든지...",
  ui_story_5071_50710702_2_dialog_content = "사람이 너무 많으니까 그렇지. 됐어, 신경 쓰지 마. 일단 보던 거나 계속 보자!",
  ui_story_5071_50710702_3_dialog_content = "몇 년이 지나, 나는 마침내 다시 펜을 잡고 이 전기를 이어서 쓰게 되었다.",
  ui_story_5071_50710702_4_dialog_content = "나는 한때 내가 남의 비위를 맞추거나 객관적인 「진상」이 아닌 것들을 써 왔다고 생각했다.\n더불어 전작의 실패는 내가 수년간 글을 쓸 수 없게 만들었다.",
  ui_story_5071_50710702_5_dialog_content = "그러나 한 친구가 들려주는 과거는 나를 다시 영감의 파도에 빠트렸다.\n허구로 쓰인 《레드 머큐리》의 속편이 혹평을 받은 이상, 이번에는 진실을 따라 써 볼 생각이다.",
  ui_story_5071_50710702_6_dialog_content = "어쩌면 그 결말은 독자들이 상상했던 것과는 다를 수도 있다.\n그러나 탄식을 이끌어 낼 진상은 기록될 만한 가치가 있을 것이다.",
  ui_story_5071_50710702_7_dialog_content = "...그럼 이제 머큐리 부인의 진짜 얘기가 나온다는 거야?!",
  ui_story_5071_50710702_8_dialog_content = "더 기대되잖아!",
  ui_story_5071_50710702_9_dialog_content = "멜리사의 자태는 기품과 아름다움이 있었고, 그녀의 검은 마치 떨어지는 별들처럼 신속했다.\n눈앞의 아인족 사내는 순식간에 압도되고 말았다.",
  ui_story_5071_50710702_10_dialog_content = "「항복해.」 그녀는 차갑게 말했다.\n「움브라톤을 휩쓰는 그림자가 당신인 거 이미 알고 있어.」",
  ui_story_5071_50710702_11_dialog_content = "그 많은 아이들을 납치한 죄는 결코 용서받을 수 없어!",
  ui_story_5071_50710702_12_dialog_content = "멜리사는 잃어버린 딸을 깊이 사랑했고, 그것은 그녀에게 오랜 집념으로 자리 잡았다.",
  ui_story_5071_50710702_13_dialog_content = "상대는 빗발치듯 쏟아지는 검을 계속해서 묵묵히 받아냈다.\n그것은 마치 자신에게도 꺾일 수 없는 이유가 있다는 무언의 외침 같았다.",
  ui_story_5071_50710702_14_dialog_content = "그러나 설령 이곳에서 자신의 딸을 찾을 수 없다 해도,\n멜리사는 이 「비열한 납치범」을 용서할 수 없었다.",
  ui_story_5071_50710702_15_dialog_content = "칼날이 격렬하게 불꽃을 튀기는 가운데, 아인족 사내는 구석까지 몰렸다.\n그 순간, 떠들썩한 소리가 갑자기 터져 나왔다.",
  ui_story_5071_50710702_16_dialog_content = "아버지──!",
  ui_story_5071_50710702_17_dialog_content = "조심해!",
  ui_story_5071_50710702_18_dialog_content = "걱정하는 아이들의 외침이 이어지자, 깜짝 놀란 멜리사의 손도 느려졌다.",
  ui_story_5071_50710702_19_dialog_content = "멜리사는 그제서야 자신이 입수한 정보가 틀렸음을 깨달았다.\n검을 내려놓은 그녀의 얼굴에는 실의가 서려 있었다.",
  ui_story_5071_50710702_20_dialog_content = "「네 딸을 찾는 걸 도와주겠다.」\n그녀의 사정을 알게 된 케이드라는 이름의 아인족 사내는 말했다.",
  ui_story_5071_50710702_21_dialog_content = "다만 내 일에는 개입하지 않았으면 좋겠군. 암흑가를 무너트리는 걸 막지 말라는 뜻이다.",
  ui_story_5071_50710702_22_dialog_content = "이 도시에 타락하지 않은 사람이 몇이나 있다고? 왜 사서 그런 고생을 하는 거지?",
  ui_story_5071_50710702_23_dialog_content = "네 손길 없이도 네 딸이 무사히 자라려면 필요한 일이다.",
  ui_story_5071_50710702_24_dialog_content = "이거... 샤엘 씨 어머니 얘기 같아.",
  ui_story_5071_50710702_25_dialog_content = "픽션인가? 아니면... 아무튼 좀 더 보자.",
  ui_story_5071_50710702_26_dialog_content = "케이드가 마지막으로 멜리사를 만났을 때, 그녀의 병은 이미 걷잡을 수 없는 상태였다.",
  ui_story_5071_50710702_27_dialog_content = "병은 그녀의 아름다움을 앗아갔고, 고통은 그녀를 초췌하게 만들었다.",
  ui_story_5071_50710702_28_dialog_content = "케이드가 시야에 들어오자, 그토록 강인했던 머큐리도 처음으로 나약한 표정을 드러냈다.",
  ui_story_5071_50710702_29_dialog_content = "「부탁할게. 내 딸을 찾아줘.」",
  ui_story_5071_50710702_30_dialog_content = "그것은 그녀의 유일한 소원이었고, 그 대가로 머큐리는 이미 대부분의 검은 사업을 접은 채였다.",
  ui_story_5071_50710702_31_dialog_content = "당신이라면 약속을 지킬 거라 믿어.",
  ui_story_5071_50710702_32_dialog_content = "그러나 눈앞의 케이드는 침묵에 빠졌다.\n그 등 뒤의 손은 서늘한 빛을 발하는 단검을 꽉 쥐고 있었다.",
  ui_story_5071_50710702_33_dialog_content = "안심해라. 반드시 가슴에 새겨 둘 테니.",
  ui_story_5071_50710702_34_dialog_content = "멜리사는 깊게 숨을 내쉬었고, 모든 근심이 그 순간에 사라져 버린 듯했다.",
  ui_story_5071_50710702_35_dialog_content = "「참.」 갑자기 무언가 생각난 듯 그녀가 말했다.\n「뒤에 뭐 들고 있어?」",
  ui_story_5071_50710702_36_dialog_content = "「별거 아니다.」 케이드는 한 발짝 다가갔고, 그 얼굴은 그림자 속으로 가라앉았다.\n「너한테 줄 선물이다.」",
  ui_story_5071_50710702_37_dialog_content = "<color=#e8d9bb>그것이 이 페이지의 마지막 문장이었고, 잉크의 짙은 색을 봤을 때\n아무래도 최근에 쓴 내용 같았다.</color>",
  ui_story_5071_50710702_38_dialog_content = "이게 무슨... 말도 안 돼...",
  ui_story_5071_50710702_39_dialog_content = "이건...",
  ui_story_5071_50710702_40_dialog_content = "거기 꼬마 친구들, 무슨 일이니?",
  ui_story_5071_50710702_41_dialog_content = "슬슬 경매 시간이야. PlayerName, 너도 뭐 필요한 거 없는지 구경 좀 해.",
  ui_story_5071_50710702_42_dialog_content = "이번 경매는 지금까지 움브라톤에 있었던 것들이랑은 달라.\n아주 투명하고 공개적인 경매니까 볼 만할 거야!",
  ui_story_5071_50710702_43_dialog_content = "섀도우마스터와 협력해서 어렵게 성사시킨 자유 거래거든.",
  ui_story_5071_50710702_44_dialog_content = "안 가면 좋은 건 전부 다른 사람들한테 뺏길걸.",
  ui_story_5071_50710702_45_dialog_content = "제 용돈으로는 무리예요... 아니지, 그것보다 샤엘 씨! 이거 좀 보세요!",
  ui_story_5071_50710702_46_dialog_content = "이본 여사님 원고에 사장님 어머니 이름이 나왔어요...",
  ui_story_5071_50710702_47_dialog_content = "뭐?! 좀 볼게... 이본 여사님은 계속 움브라톤을 소재로 작품을 써 왔으니까,\n이번에도 그럴 거야.",
  ui_story_5071_50710702_48_dialog_content = "살인 사건이라... 뭐, 문학 작품은 대부분 허구를 섞어서 만드는 거니까,\n이런 내용이 있어도 이상할 건 없어.",
  ui_story_5071_50710702_49_dialog_content = "근데 왜 여기다 실명을 쓴 거죠...?",
  ui_story_5071_50710702_50_dialog_content = "달링, 너무 신경 쓰지 마. 경매 끝나고 이본 여사님한테 물어보면 되잖아?",
  ui_story_5071_50710702_51_dialog_content = "지금 중요한 건 경매야. 이제 곧 시작하니까 둘 다 여기 있으면 안 돼...",
  ui_story_5071_50710702_52_dialog_content = "적어도 버질 넌 절대 안 되지. 가서 물건 감정해야지!",
  ui_story_5071_50710702_53_dialog_content = "뭔가 진귀한 물건을 구할 수 있을지도 모르잖아...",
  ui_story_5071_50710702_54_dialog_content = "잠깐만요! 샤엘 씨!",
  ui_story_5071_50710801_1_dialog_content = "존경하는 섀도우마스터, 전 다른 부탁은 없어요.\n그저 당신에 대한 전기 소설을 한 권 내고 싶을 뿐이에요.",
  ui_story_5071_50710801_2_dialog_content = "그 정도 일을 내게 허락까지 구할 필요는 없다.",
  ui_story_5071_50710801_3_dialog_content = "움브라톤은 창작의 자유를 존중한다.",
  ui_story_5071_50710801_4_dialog_content = "네... 그렇게 말씀해 주시니 안심이 되네요.\n다만, 과거의 일에 대해 조금 취재를 하고 싶거든요...",
  ui_story_5071_50710801_5_dialog_content = "<color=#e8d9bb>부유 비공정, 경매장</color>",
  ui_story_5071_50710801_6_dialog_content = "크흠... 이번에 저희가 가져온 작품은 《레디젤 사막의 일각》입니다.\n거장 「빈치」가 여행 중에 그린 작품이죠.",
  ui_story_5071_50710801_7_dialog_content = "빈치는 저명한 유랑 화가입니다. 평생 수많은 작품을 그렸고, 이건 그중에서도 특히 명작이죠.",
  ui_story_5071_50710801_8_dialog_content = "이 작품에서 우린 번쩍이는 태양 아래 층층이 늘어선 사막 지형을 볼 수 있습니다.\n빈치만의 독특한 기법으로 낭만적인 모습을 그려내고 있죠.",
  ui_story_5071_50710801_9_dialog_content = "파란색으로 모래알의 윤곽을 표현하는 건 파격적인 방식인데요.\n이렇게 모래의 반짝임을 강조해 사막을 마치 바다처럼 표현한 겁니다.",
  ui_story_5071_50710801_10_dialog_content = "어라? 전 공중상회가 주최하는 경매인 줄 알았는데요.",
  ui_story_5071_50710801_11_dialog_content = "우리 모토는 자유롭고, 공정하며, 투명한 거래야.\n상회는 장소만 제공하고, 나머지는 사람들이 알아서 하는 거지.",
  ui_story_5071_50710801_12_dialog_content = "지금까지 움브라톤에는 「지하경매장」이 많이 열리곤 했어.\n하지만 출품되는 물건 출처도 수상하고, 가격도 불합리했어.",
  ui_story_5071_50710801_13_dialog_content = "우리 경매는 달라. 여기서는 서로 얼굴을 마주 보고 경매를 진행할 수 있고,\n무료 감정 서비스도 제공하고 있어.",
  ui_story_5071_50710801_14_dialog_content = "미안한데, 이거 위작이에요... 진짜라고 속이면 안 되죠.",
  ui_story_5071_50710801_15_dialog_content = "(...역시 자기 전문 분야가 나오면 버질은 완전 다른 사람이 되는 것 같다니까.)",
  ui_story_5071_50710801_16_dialog_content = "(웅성웅성──)",
  ui_story_5071_50710801_17_dialog_content = "다들 조용히 해 주세요!\n이게 위작이라니, 너 증거 있어?",
  ui_story_5071_50710801_18_dialog_content = "그래! 네 코가 우리보다 더 개코야?",
  ui_story_5071_50710801_19_dialog_content = "이래서야 누가 판매자인지 뻔하잖아...",
  ui_story_5071_50710801_20_dialog_content = "알다시피 빈치가 유명해진 건 대륙 곳곳을 여행하면서 각지의 풍경을 그림에 담아내서예요.",
  ui_story_5071_50710801_21_dialog_content = "근데 중요한 건... 그 지역에서 구할 수 있는 물감으로만 그림을 그렸다는 거예요.",
  ui_story_5071_50710801_22_dialog_content = "이 그림에 사용된 색은 확실히 레디젤 사막처럼 거칠고 조잡해 보이잖아?",
  ui_story_5071_50710801_23_dialog_content = "근데 《레디젤 사막의 일각》 속 모래알을 강조할 때 썼던 건\n사막 지하에서 추출한 밝은 청색의 천연물감이에요.",
  ui_story_5071_50710801_24_dialog_content = "반면에 이 그림에 쓰인 건 보석 분말이에요. 이건 레디젤 사막에선 「사치」나 다름없는 일이죠.",
  ui_story_5071_50710801_25_dialog_content = "이 위작을 그린 사람은 분명히 모래땅 지하 깊은 곳에 물감 재료가 있는 걸 몰랐을 거예요...",
  ui_story_5071_50710801_26_dialog_content = "그리고 진품의 모래 색은 더 옅어요.\n빈치는 사막을 바다의 파도에 가깝게 표현하고 싶었거든요.",
  ui_story_5071_50710801_27_dialog_content = "근데 이 위작은 사막에서 그렸단 느낌을 내려고 의도해서인지, 무심코 색을 더 짙게 썼어요...",
  ui_story_5071_50710801_28_dialog_content = "너 때문이야! 그러니까 내가 너무 화려한 기법은 쓰지 말자고 했잖아!",
  ui_story_5071_50710801_29_dialog_content = "잘난 척하지 마. 내가 없었으면 이렇게 비슷하게 그릴 수나 있었겠어?",
  ui_story_5071_50710801_30_dialog_content = "보안팀, 여기 손님 두 분 내보내 줘. 아, 그림도 들고 나가라고 하고.",
  ui_story_5071_50710801_31_dialog_content = "버질... 너 진짜 대단하네!",
  ui_story_5071_50710801_32_dialog_content = "그래...? 난 그냥 예술품을 좋아하는 것뿐인데...",
  ui_story_5071_50710801_33_dialog_content = "그거야 당연하지. 우리 꼬마 직원 실력은 의심할 여지 없이 최고거든.",
  ui_story_5071_50710801_34_dialog_content = "달링, 설마 내가 무턱대고 어린애를 부려먹는 줄 알았니?",
  ui_story_5071_50710801_35_dialog_content = "으엑...",
  ui_story_5071_50710801_36_dialog_content = "손님 여러분, 다음은 제가 새로운 출품작을 소개해 드리겠습니다.",
  ui_story_5071_50710801_37_dialog_content = "이것은 제 익명의 의뢰인이 출품을 부탁한 유화입니다.\n마찬가지로 작가의 이름 또한 알 수 없습니다.",
  ui_story_5071_50710801_38_dialog_content = "하지만 기법으로 볼 때 거장의 작품이라고 해도 과언이 아닐 겁니다.\n그럼 여러분께서 마음에 드셨으면 좋겠군요.",
  ui_story_5071_50710801_39_dialog_content = "그림의 제목은── 《부인의 죽음》입니다!",
  ui_story_5071_50710801_40_dialog_content = "작품의 가치는 아직 확정되지 않았으니, 500만부터 시작하겠습니다.",
  ui_story_5071_50710801_41_dialog_content = "그림 속 저 사람... 머큐리 부인 아냐? 앞에 서 있는 저 살인마... 왠지...",
  ui_story_5071_50710801_42_dialog_content = "아니, 저건 멜리사 부인이야...",
  ui_story_5071_50710801_43_dialog_content = "어떻게 된 거죠? 저 살인마 뒷모습, 아무리 봐도 섀도우마스터 같지 않나요...?",
  ui_story_5071_50710801_44_dialog_content = "저게 무슨... 저 그림 대체...",
  ui_story_5071_50710801_45_dialog_content = "PlayerName, 나 대신 저 그림에 입찰해 줄 수 있을까?",
  ui_story_5071_50710801_46_dialog_content = "누가 출품을 의뢰했는진 나도 몰라... 하지만 난 상회장이라서 입찰할 수 없어.\n부탁할게, 넌 가격만 외치면 돼.",
  ui_story_5071_50710801_47_dialog_content = "600만.",
  ui_story_5071_50710801_48_dialog_content = "1000만.",
  ui_story_5071_50710801_49_dialog_content = "달링, 얼른!",
  ui_story_5071_50710801_50_dialog_content = "...1200만!",
  ui_story_5071_50710801_51_dialog_content = "1400만.",
  ui_story_5071_50710801_52_dialog_content = "(웅성웅성──)",
  ui_story_5071_50710801_53_dialog_content = "아...",
  ui_story_5071_50710801_54_dialog_content = "(이거... 내 용돈으로 치면 대체 얼마나 모아야 하는 돈인 거지...?)",
  ui_story_5071_50710801_55_dialog_content = "달링, 멍하니 있지 말고 입찰해! 얼마든 좋으니까!",
  ui_story_5071_50710801_56_dialog_content = "...2000만...?!",
  ui_story_5071_50710801_57_dialog_content = "......",
  ui_story_5071_50710801_58_dialog_content = "2000만 나왔습니다. 또 누구 없으신가요? 2000만!",
  ui_story_5071_50710801_59_dialog_content = "2000만, 축하드립니다. 아이테르님, 낙찰입니다.",
  ui_story_5071_50710801_60_dialog_content = "무명작가의 작품에 이렇게 비싼 값을 부르시다니, 아이테르님의 훌륭한 안목에 박수를 보냅니다.",
  ui_story_5071_50710801_61_dialog_content = "샤엘 씨, 역시 안목이 좋으시군요.",
  ui_story_5071_50710801_62_dialog_content = "이 그림을 그렇게까지 좋아하실 줄은 몰랐네요.\n규칙을 깨면서까지 대리 입찰을 시키고 말이에요.",
  ui_story_5071_50710801_63_dialog_content = "어쩌면 우리 사이엔 뭔가 통하는 게 있을지도 모르겠어요.\n역시 섀도우마스터가 당신에게 비즈니스를 배우라던 이유가 있었네요.",
  ui_story_5071_50710801_64_dialog_content = "천만에요. 아스트라 전역을 누비는 대상회를 움브라톤 밖에서 키워낸\n당신 쪽이 오히려 더 대단하죠.",
  ui_story_5071_50710801_65_dialog_content = "아무래도 섀도우마스터와 꽤 깊은 인연이 있으신 모양인데요.\n저야말로 여러모로 가르침을 받고 싶네요.",
  ui_story_5071_50710801_66_dialog_content = "...당신이라면 이 그림을 양보할 수 있을 것 같아요. 전 당신이 정말 마음에 들거든요.",
  ui_story_5071_50710801_67_dialog_content = "그거 정말 고맙네요, 한스티 씨.",
  ui_story_5071_50710801_68_dialog_content = "크흠... 저기, 샤엘 씨... 이제 돈 내고 그림 받아가야죠...",
  ui_story_5071_50710801_69_dialog_content = "어머, PlayerName, 누가 보면 내가 너한테 덤터기라도 씌운 줄 알겠네...\n자, 그림 감상하러 가 보자.",
  ui_story_5071_50710801_70_dialog_content = "샤엘 씨, 저도 같이 봐도 될까요?",
  ui_story_5071_50710801_71_dialog_content = "물론이죠.",
  ui_story_5071_50710801_72_dialog_content = "...어라?! 음... 킁킁──",
  ui_story_5071_50710801_73_dialog_content = "이 은은한 향...",
  ui_story_5071_50710801_74_dialog_content = "사장님, 이거 왠지... 제가 제일 좋아하는 위작 작가 A 씨 작품 같아요.",
  ui_story_5071_50710801_75_dialog_content = "지금까지 그 작가 그림을 많이 봤지만, 오리지널 작품을 보는 건 이번이 처음이에요!",
  ui_story_5071_50710801_76_dialog_content = "어머, 그러니? 그럼 이번에 초빙한 경매회사도 결국 너보다 전문성이 떨어졌던 모양이네.",
  ui_story_5071_50710801_77_dialog_content = "꼬마야, 이 작품 작가는 전혀 알려져 있지 않은데, 넌 어떻게 그걸 알았니?",
  ui_story_5071_50710801_78_dialog_content = "음... 전 매일같이 위작을 감정하고 있거든요.\n그래서 솜씨 좋은 위작 작가를 많이 알고 있어요.",
  ui_story_5071_50710801_79_dialog_content = "근데 그중에서도 A 씨 기술은 최고 수준이에요.",
  ui_story_5071_50710801_80_dialog_content = "게다가 A 씨의 위작은 특징이 하나 있어요.\n남들이 찾기 힘든 구석에 작은 「A」 자를 넣는 거예요.",
  ui_story_5071_50710801_81_dialog_content = "인물의 머리카락 사이나 동공 속... 이 작품은 목덜미 주름 속에 있구요.",
  ui_story_5071_50710801_82_dialog_content = "...그런 규칙성까지 찾은 거니? 넌 그 A 씨를 정말 좋아하는 모양이구나.",
  ui_story_5071_50710801_83_dialog_content = "맞아요. 근데 A 씨는 분명히 나르시시스트일 거예요.\n아니면 위작에 이렇게 자기 「존재」를 남길 사람은 없을 테니까요.",
  ui_story_5071_50710801_84_dialog_content = "음... 왠지 목적을 위해서라면 절대로 포기하지 않을 사람 같아요.",
  ui_story_5071_50710801_85_dialog_content = "호오, 그러니...? 재미있네.",
  ui_story_5071_50710801_86_dialog_content = "...어라?",
  ui_story_5071_50710801_87_dialog_content = "으, 으아앗, 모, 모르는 사람이랑 말했다아아...",
  ui_story_5071_50710801_88_dialog_content = "이제 와서 내 뒤에 숨어봤자 뭐 해...",
  ui_story_5071_50710801_89_dialog_content = "무서워하지 마, 꼬마야. 난 네 재능이 무척 마음에 들거든.",
  ui_story_5071_50710801_90_dialog_content = "그리고 넌 잠재력이 있어. 어때? 나랑 같이 일해볼 생각 있니?",
  ui_story_5071_50710801_91_dialog_content = "미안해요, 한스티 씨. 얘는... 제 직원이거든요.",
  ui_story_5071_50710801_92_dialog_content = "어머, 그거 정말 아쉽네요.\n그러고 보면 왠지 제가 좋아하는 건 모두 샤엘 씨가 먼저 차지해 버린 것 같단 말이죠...",
  ui_story_5071_50710801_93_dialog_content = "설마 그럴 리가요. 아니면 사과의 뜻으로 이건 어떨까요?\n제 개인 컬렉션 중 한 점을 선물로 드릴게요. 한스티 씨가 직접 고르세요.",
  ui_story_5071_50710801_94_dialog_content = "그럴 필요 없어요. 전 타인이 아끼는 걸 빼앗는 취미는 없거든요.",
  ui_story_5071_50710801_95_dialog_content = "그나저나 당신도 이 그림의 진짜 작가를 모르는데, 왜 그렇게까지 마음에 들어 한 거죠?",
  ui_story_5071_50710801_96_dialog_content = "알려지지 않은 그림에 높은 값을 부른 게 고작 「마음에 들어서」라는\n단순한 이유는 아닐 것 같은데요.",
  ui_story_5071_50710801_97_dialog_content = "그건... 저도 오랜 친구를 돕고 싶었을 뿐이에요.",
  ui_story_5071_50710801_98_dialog_content = "이 그림의 내용이 움브라톤에 퍼지기라도 한다면,\n그 사람이 힘들게 쌓은 명성에도 영향이 클 테니까요.",
  ui_story_5071_50710801_99_dialog_content = "당신이 그 사람 대신 낙찰받은 이상, 그 공로는 이제 저한테 없다고 해야겠죠.",
  ui_story_5071_50710801_100_dialog_content = "그럼 먼저 가 볼게요, 다음에 또 봐요.",
  ui_story_5071_50710801_101_dialog_content = "한스티 씨, 잠시만요. 한 가지만 더 물어보고 싶어요.",
  ui_story_5071_50710801_102_dialog_content = "당신... 아주 오래전부터 섀도우마스터와 알던 사이였죠?",
  ui_story_5071_50710801_103_dialog_content = "후훗... 그 남자의 본모습을 알게 된 게 언제냐는 말인가요?\n그거라면 당신이 생각하는 것보다 훨씬 오래됐을 거예요.",
  ui_story_5071_50710801_104_dialog_content = "음...",
  ui_story_5071_50710801_105_dialog_content = "왜 그러니? 아까부터 한스티 씨만 보고. 혹시 저 사람 제안에 솔깃했어?",
  ui_story_5071_50710801_106_dialog_content = "아, 아, 아니에요! 그냥...",
  ui_story_5071_50710801_107_dialog_content = "이상해... 버질, 너무 공교롭지 않아?",
  ui_story_5071_50710801_108_dialog_content = "이 그림, 아까 우리가 읽은 원고 내용이잖아...",
  ui_story_5071_50710801_109_dialog_content = "설마 이본 선생님이 말했던 화가 친구가 위작 작가 A 씨인 걸까?",
  ui_story_5071_50710801_110_dialog_content = "이본 선생님도 분명히 말했어. 그 화가 친구 덕분에 신작을 쓸 마음이 생겼다고...",
  ui_story_5071_50710801_111_dialog_content = "맞아, 달링. 모든 게 너무 공교로워.",
  ui_story_5071_50710801_112_dialog_content = "마치 일부러 우리한테 보여주려는 것처럼 말이야.",
  ui_story_5071_50710801_113_dialog_content = "잘 모르겠어요... 그럼 어떻게 되는데요?",
  ui_story_5071_50710801_114_dialog_content = "이런 것들을 계속 보여주는 목적은 두 가지 가능성밖에 없어.",
  ui_story_5071_50710801_115_dialog_content = "「진상」을 알리고 싶거나, 아니면...",
  ui_story_5071_50710801_116_dialog_content = "달링! 그 원고, 다음 내용은 뭐야?",
  ui_story_5071_50710801_117_dialog_content = "얼른 확인해 봐!",
  ui_story_5071_50710901_1_dialog_content = "순금 지팡이를 쥔 아인족 사내는 센트리 폰드 중앙에 서 있었다.\n그리고 그를 에워싼 것은 지난날의 친구를 우두머리로 모시는 자들이었다.",
  ui_story_5071_50710901_2_dialog_content = "「배신자!」 그들은 아인족 사내에게 외쳤다.\n「대체 왜 백야성 군대를 움브라톤으로 끌어들인 거냐!」",
  ui_story_5071_50710901_3_dialog_content = "아인족 사내는 침묵을 지킨 채였고, 그의 칼날 같은 눈빛은 오직 자신의 친구만을 향하고 있었다.\n푸른 머리의 사내 배런의 표정은 비통했고, 그 눈에는 슬픔이 가득했다.",
  ui_story_5071_50710901_4_dialog_content = "잠시 후 배런은 마침내 입을 열었다.\n「케이드... 왜 아버지를 죽이고... 지팡이를 빼앗은 거냐...」",
  ui_story_5071_50710901_5_dialog_content = "정말 우리의 이상을 배반한 거냐? 왜 백야성의 말을 따르는 거냔 말이다!",
  ui_story_5071_50710901_6_dialog_content = "센트리 폰드... 내가 널 대신해 싸웠고 살아남았던 곳이지.\n그 정도 머릿수로 날 막을 수 있을 것 같나?",
  ui_story_5071_50710901_7_dialog_content = "그의 말을 들은 사람들은 머리카락이 곤두서는 것을 느꼈다.",
  ui_story_5071_50710901_8_dialog_content = "어...? 이 둘 가장 가까운 친구 사이 아니었어?",
  ui_story_5071_50710901_9_dialog_content = "...계속 읽어 보자.",
  ui_story_5071_50710901_10_dialog_content = "「넌 너무 약하다! 그게 바로 내가 널 대신하는 이유다!」",
  ui_story_5071_50710901_11_dialog_content = "케이드는 포효하며 지팡이로 친구의 가슴을 꿰뚫었고,\n광기로 비틀린 그의 얼굴은 지난날의 형제조차 분간할 수 없었다.",
  ui_story_5071_50710901_12_dialog_content = "어, 어째서...",
  ui_story_5071_50710901_13_dialog_content = "나는 누군가의 그림자로 남을 생각은 없다.",
  ui_story_5071_50710901_14_dialog_content = "푸른 머리의 사내는 허탈해하며 쓰러졌고, 주변의 사람들도 비통함에 휩싸였다.",
  ui_story_5071_50710901_15_dialog_content = "이윽고 분노와 슬픔 가운데 일제히 그에게 달려들었다──",
  ui_story_5071_50710901_16_dialog_content = "어, 얼른 다음 장...",
  ui_story_5071_50710901_17_dialog_content = "케이드는 마침내 자신의 흉악한 불길을 드러냈고,\n자신을 방해하는 움브라톤의 모든 이들을 잔혹하게 갈기갈기 찢었다.",
  ui_story_5071_50710901_18_dialog_content = "뜻이 다른 자는 모두 배제했고, 푸른 불꽃은 움브라톤의 모든 구석까지\n불태우며 그 누구도 놓아주지 않았다.",
  ui_story_5071_50710901_19_dialog_content = "그렇게 그는 자신의 길의 끝에 다다라 패권을 손에 넣었다.",
  ui_story_5071_50710901_20_dialog_content = "그는 이상을 저버리고, 움브라톤을 배반했다.\n백야성에 무릎을 꿇어 굴복한 것 또한 움브라톤에 대한 지배권을 얻기 위해서였다.",
  ui_story_5071_50710901_21_dialog_content = "그는 형제의 목숨을 빼앗았고, 그의 이름마저 빼앗았다.\n그렇게 본디 자신의 것이 아니었던 유력 가문을 훔쳤다.",
  ui_story_5071_50710901_22_dialog_content = "그 악행의 신조로 왕의 자리까지 걸어온 후, 그는 자신의 과거를 묻어버렸고,\n한때의 형제 「배런」의 존재도 지워버렸다.",
  ui_story_5071_50710901_23_dialog_content = "그림자의 왕좌에 오른 그의 잔혹하고 비참한 과거를 아는 자는 이제 아무도 없다.",
  ui_story_5071_50710901_24_dialog_content = "사람들이 기억하는 것은 그저 피로 물든 양치기의 지팡이를 손에 들고,\n암흑가를 호령하는 자──",
  ui_story_5071_50710901_25_dialog_content = "섀도우마스터, 이스타반뿐이다.",
  ui_story_5071_50710901_26_dialog_content = "...뭐...뭐라고...?!",
  ui_story_5071_50710901_27_dialog_content = "주인공 케이드가... 이스타반 씨였단 말이야?",
  ui_story_5071_50710901_28_dialog_content = "이건 말도 안 돼! 섀도우마스터가 움브라톤을 배신할 리가 없잖아!",
  ui_story_5071_50710901_29_dialog_content = "(이스타반 씨의 내면에 위험한 뭔가가 있다는 건 느낄 수 있어.\n하지만 아무리 그래도 이 내용은 너무 심하잖아...)",
  ui_story_5071_50710901_30_dialog_content = "......",
  ui_story_5071_50710901_31_dialog_content = "사장님, 섀도우마스터는...",
  ui_story_5071_50710901_32_dialog_content = "사람은 원래 복잡한 거야. 우린 한쪽 이야기만 듣고 믿어선 안 돼. 일단은...",
  ui_story_5071_50710901_33_dialog_content = "<color=#e8d9bb>콰아앙──</color>",
  ui_story_5071_50710901_34_dialog_content = "뭐야? 폭발? 어디서 터진 거지?",
  ui_story_5071_50710901_35_dialog_content = "샤엘 씨! 비공정에 갑자기 백야성 경비병들이 나타나서 우릴 공격했습니다!",
  ui_story_5071_50710901_36_dialog_content = "백야성 경비병이 왜 우릴 공격하죠?",
  ui_story_5071_50710901_37_dialog_content = "제가 무슨 잘못이라도 했단 말인가요?",
  ui_story_5071_50710901_38_dialog_content = "그만해! 뭐 하는 거야?! 여긴 샤엘 사장님 비공정이라구!",
  ui_story_5071_50710901_39_dialog_content = "비공정은 아직 비행 중이야! 여기서 난동을 부리면 승객들도 위험해!",
  ui_story_5071_50710901_40_dialog_content = "감히 누구한테 대드는 거냐! 놈들을 잡아!",
  ui_story_5071_50710901_41_dialog_content = "안 돼! 이러지 마...",
  ui_story_5071_50710901_42_dialog_content = "이러다간 다 죽는다고!",
  ui_story_5071_50710901_43_dialog_content = "내 구역에서 설치지 마──!",
  ui_story_5071_50710901_X43_dialog_content = "으앗?!",
  ui_story_5071_50710901_X44_dialog_content = "분수를 모르는 녀석들이...",
  ui_story_5071_50710901_X45_dialog_content = "감히 내 비공정을 부수려고 해?",
  ui_story_5071_50710901_X46_dialog_content = "우와아!",
  ui_story_5071_50710901_X47_dialog_content = "어, 엄청난 발차기다!",
  ui_story_5071_50710901_X48_dialog_content = "저게 진짜 우리 사장님이라구?!",
  ui_story_5071_50710901_X49_dialog_content = "사, 사장님이 싸우는 거 처음 봐!",
  ui_story_5071_50710901_44_dialog_content = "대, 대단해!",
  ui_story_5071_50710901_45_dialog_content = "샤엘 씨...",
  ui_story_5071_50710901_46_dialog_content = "섀도우마스터, 바깥에 소란이 발생했습니다. 아무래도 누가 숨어든 모양입니다.",
  ui_story_5071_50710901_47_dialog_content = "호오.",
  ui_story_5071_50710901_48_dialog_content = "「손님」이 더는 참기 힘들었던 것이겠지... 재미있게 됐군.",
  ui_story_5071_50710901_49_dialog_content = "......?",
  ui_story_5071_50711001_1_dialog_content = "무슨 일이냐.",
  ui_story_5071_50711001_2_dialog_content = "섀도우마스터! 드디어 오셨군요! 이 병사들이...",
  ui_story_5071_50711001_3_dialog_content = "섀도우마스터, 이게 어떻게 된 겁니까?! 당신이 명령한 거 아니었습니까?!",
  ui_story_5071_50711001_4_dialog_content = "당신이 우리한테 방해하는 놈들을 없애라고 해 놓고, 왜 이제 와서...",
  ui_story_5071_50711001_5_dialog_content = "?!",
  ui_story_5071_50711001_6_dialog_content = "섀도우마스터의 명령이었다고?!",
  ui_story_5071_50711001_7_dialog_content = "어쩐지 백야성 경비병이...",
  ui_story_5071_50711001_8_dialog_content = "근데 왜 우리를...",
  ui_story_5071_50711001_9_dialog_content = "조용히 하세요! 아직 상황도 모르는데...",
  ui_story_5071_50711001_10_dialog_content = "<color=#e8d9bb>그 순간, 갑자기 수많은 원고지가 눈처럼 하늘에서 떨어졌다.</color>",
  ui_story_5071_50711001_11_dialog_content = "이거... 이본 선생님 원고잖아?",
  ui_story_5071_50711001_12_dialog_content = "왜 갑자기 원고가 잔뜩... 누가 이런...",
  ui_story_5071_50711001_13_dialog_content = "다 같은 내용이야. 이거 봐.",
  ui_story_5071_50711001_14_dialog_content = "오랜 세월이 흘러, 나는 마침내 이 땅으로 돌아왔다. 이제 이스타반은 움브라톤의 왕이 되었고,\n배런의 꿈이었던 총상회도 그의 권력을 위한 도구로 변모해 있었다.",
  ui_story_5071_50711001_15_dialog_content = "나는 「진상」을 위해 계속해서 펜을 들어야 할까,\n아니면 이 과거를 가슴속 깊이 간직해야 하는 것일까.",
  ui_story_5071_50711001_16_dialog_content = "나는 지금까지 벌어진 잘못된 일들을 방관해 왔고, 늘 양심의 가책에 시달려 왔다.\n한때는 내가 그 모든 것에 이미 익숙해졌다고 생각했다.",
  ui_story_5071_50711001_17_dialog_content = "만약 그의 다음 욕망을 알지 못했다면, 아마도 나는 계속해서 방관했을 것이다.",
  ui_story_5071_50711001_18_dialog_content = "그러나 나는 우연히 이스타반의 수하로부터 듣고 말았다.\n이미 높은 곳에 오른 그의 욕망은 여전히 만족을 얻지 못했다는 것을.",
  ui_story_5071_50711001_19_dialog_content = "그는 겉으로는 관대하나, 배후에서는 중립을 지키는 클랜이나 상회에 대해 불만을 품고 있었다.",
  ui_story_5071_50711001_20_dialog_content = "총상회의 통제를 받지 않는 존재들은 그에게 눈엣가시와도 같았고...\n그는 그러한 「반역자」들을 용납할 수 없었다.",
  ui_story_5071_50711001_21_dialog_content = "그는 공중상회가 사람들을 모을 기회를 노려 그들을 일망타진하기로 결정했고,\n그렇게 해서 그가 바라던 대로 움브라톤을 완전히 장악할 것이다.",
  ui_story_5071_50711001_22_dialog_content = "그래서 나는 결정했다. 내 목숨의 마지막 순간에 잊혀진 정의를 실현하기로.",
  ui_story_5071_50711001_23_dialog_content = "──이본",
  ui_story_5071_50711001_24_dialog_content = "...이게 진짜야?!",
  ui_story_5071_50711001_25_dialog_content = "이본 여사님은 아까 섀도우마스터를 만나러 갔잖아?",
  ui_story_5071_50711001_26_dialog_content = "진정하세요! 이 원고 뭔가 이상하지 않아요?!",
  ui_story_5071_50711001_27_dialog_content = "섀도우마스터가 여기 있다는 건... 그럼 이본 여사님은 설마...",
  ui_story_5071_50711001_28_dialog_content = "이건 일방적인 주장이잖아...",
  ui_story_5071_50711001_29_dialog_content = "...우리도 없애버릴 생각인가?",
  ui_story_5071_50711001_30_dialog_content = "다른 원고도 있나? 빨리 보여줘!",
  ui_story_5071_50711001_31_dialog_content = "아, 안 돼!",
  ui_story_5071_50711001_32_dialog_content = "여러분, 그런 품위 없는 행동은 곤란해요.",
  ui_story_5071_50711001_33_dialog_content = "이, 이 내용...",
  ui_story_5071_50711001_34_dialog_content = "이게 진짜야? 여기 적혀있는 게 정말 섀도우마스터의 과거인가?!",
  ui_story_5071_50711001_35_dialog_content = "하아... 남의 말을 들을 생각이 전혀 없네요...",
  ui_story_5071_50711001_36_dialog_content = "그 소문들이 진짜였단 말이야? 이제 그 칼날이 우릴 향하는 건가?!",
  ui_story_5071_50711001_37_dialog_content = "다들 진정 좀 해! 고작 소설이잖아! 그걸 진짜로 믿는 거야?",
  ui_story_5071_50711001_38_dialog_content = "하지만 소문이랑 완전히 똑같잖아...!",
  ui_story_5071_50711001_39_dialog_content = "소문이라면서 뭘 그렇게 믿고 있어?",
  ui_story_5071_50711001_40_dialog_content = "총상회가 우리 판로를 통제하고 있는 건 사실이야!\n그게 우릴 이용하는 게 아니라고 어떻게 장담하지?",
  ui_story_5071_50711001_41_dialog_content = "우리 자금도 전부 총상회에 맡겨 놨잖아... 우릴 죽이면... 그 자금도 전부...",
  ui_story_5071_50711001_42_dialog_content = "멍청한 장사꾼, 나쁜 장사꾼! 남이 하는 말은 뭐든 다 믿는 거야?",
  ui_story_5071_50711001_43_dialog_content = "보스는 그런 사람이 아냐!",
  ui_story_5071_50711001_44_dialog_content = "그냥 보스를 소재로 쓴 소설일 뿐이잖아!",
  ui_story_5071_50711001_45_dialog_content = "섀도우마스터, 해명하지 않으실 건가요?",
  ui_story_5071_50711001_46_dialog_content = "(이스타반 씨...?)",
  ui_story_5071_50711001_47_dialog_content = "(사람들을... 관찰하고 있잖아?)",
  ui_story_5071_50711001_48_dialog_content = "붉은표범 상회... 잿빛앵무 상회의 책임자도 말을 맞추고 있군.",
  ui_story_5071_50711001_49_dialog_content = "(아, 아니야...)",
  ui_story_5071_50711001_50_dialog_content = "그렇군, 러스티 팔콘 클랜도 있었나...",
  ui_story_5071_50711001_51_dialog_content = "(...사냥감을 주시하고 있는 거야.)",
  ui_story_5071_50711001_52_dialog_content = "회장님! 큰일입니다──!",
  ui_story_5071_50711001_53_dialog_content = "이본 여사가...!",
  ui_story_5071_50711001_54_dialog_content = "<size=45>이본 여사가 응접실에서 숨진 채 발견됐습니다!</size>",
  ui_story_5071_50711101_1_dialog_content = "현장을 발견한 건 이 「임시 응접실」 청소를 담당했던 청소부입니다.",
  ui_story_5071_50711101_2_dialog_content = "현장은 매우 깨끗한 상태로, 피해자가 범인과 다툰 흔적은 없었습니다.",
  ui_story_5071_50711101_3_dialog_content = "유일하게 발견한 단서는 이본 여사가 쓰러져 있던 융단에 남은 모발입니다만...",
  ui_story_5071_50711101_4_dialog_content = "일반 오로리안이 아니라 맹수의 갈기 같은데, 그렇다기에는 손질이 아주 잘 되어 있어서...",
  ui_story_5071_50711101_5_dialog_content = "섀도우마스터, 면담을 위해 이 방을 빌려서 「임시 응접실」로 쓰셨죠...?",
  ui_story_5071_50711101_6_dialog_content = "사건이 발생한 시각에 어디 계셨습니까?",
  ui_story_5071_50711101_7_dialog_content = "...말조심해라. 지금 우리 보스를 의심하는 거냐?",
  ui_story_5071_50711101_8_dialog_content = "세르고.",
  ui_story_5071_50711101_9_dialog_content = "하, 하지만 보스...",
  ui_story_5071_50711101_10_dialog_content = "추측뿐이라면 신중하게 하는 게 좋을 거예요. 경솔한 「고발」은 곤란해요.",
  ui_story_5071_50711101_11_dialog_content = "조금 전까지 이본 여사와 그녀의 작품에 대해 이야기하고 있었다.",
  ui_story_5071_50711101_12_dialog_content = "그러다가 소동이 벌어졌다기에 나는 나와서 상황을 보려고 했다.",
  ui_story_5071_50711101_13_dialog_content = "그러나 이본 여사는 갑자기 영감이 떠올랐다면서 흥분하더군.",
  ui_story_5071_50711101_14_dialog_content = "방해하지 않으려고 나 혼자 방을 나온 것이다.",
  ui_story_5071_50711101_15_dialog_content = "그리고 이본 여사가 죽었다는 건가요? 그거 정말 공교롭네요.",
  ui_story_5071_50711101_16_dialog_content = "방금 알게 된 사실입니다만, 이본 여사는 섀도우마스터께서 숨겼을지도 모르는\n충격적인 옛이야기를 알고 있더군요...",
  ui_story_5071_50711101_17_dialog_content = "그런데 갑자기 목숨을 잃다니, 이렇게 의심스러워서야...",
  ui_story_5071_50711101_18_dialog_content = "여러분, 사람들이 모인 자리에서 그런 무책임한 선동 발언은 삼가 주세요.",
  ui_story_5071_50711101_19_dialog_content = "누구야?! 누가 멋대로 나불대고 있어? 당장 안 나와?!",
  ui_story_5071_50711101_20_dialog_content = "이러다 우리도 이본 여사처럼 그림자에 삼켜질지 누가 알겠어?",
  ui_story_5071_50711101_21_dialog_content = "당신이군요. 아무래도 털어놓고 싶은 <color=#FFB400>진심</color>이 많으신 모양인데, 앞으로 나오시지 그러세요?",
  ui_story_5071_50711101_22_dialog_content = "클레이튼, 되었다.",
  ui_story_5071_50711101_23_dialog_content = "오늘은 샤엘에게 중요한 날이다. 망치지 마라.",
  ui_story_5071_50711101_24_dialog_content = "아... 어떻게 이런...",
  ui_story_5071_50711101_25_dialog_content = "이본 선생님...",
  ui_story_5071_50711101_26_dialog_content = "마치 잠든 것 같아... 미소를 띤 채 온화한 표정이야...",
  ui_story_5071_50711101_27_dialog_content = "외상은 없어 보여. 갑자기 습격당한 것도 아닌 것 같고...",
  ui_story_5071_50711101_28_dialog_content = "설마... 독?",
  ui_story_5071_50711101_29_dialog_content = "<color=#e8d9bb>쿠구구──</color>",
  ui_story_5071_50711101_30_dialog_content = "비, 비공정이 흔들린다──!",
  ui_story_5071_50711101_31_dialog_content = "설마 아까 그 공격 때문인가... 여러분! 걱정 마세요!",
  ui_story_5071_50711101_32_dialog_content = "이 비공정은 아주 튼튼해요! 믿을 만하다고요!",
  ui_story_5071_50711101_33_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_5071_50711101_34_dialog_content = "...정비 담당자한테 연락해서 점검해 보라고 하세요.",
  ui_story_5071_50711101_35_dialog_content = "예!",
  ui_story_5071_50711101_36_dialog_content = "모두 진정들 하고 내 말을 들어줬으면 좋겠군.",
  ui_story_5071_50711101_37_dialog_content = "오늘은 나의 친구에게 있어 무척 중요한 날이다.\n내가 오늘 이 자리에 온 것은 그 친구가 꿈을 이룬 것을 축하하기 위해서다.",
  ui_story_5071_50711101_38_dialog_content = "나는 이 기쁜 날을 망칠 생각이 없고, 다른 이가 그런 짓을 하게도 두지 않는다.",
  ui_story_5071_50711101_39_dialog_content = "비공정이 착륙하고 나면 치안대가 조사를 시작할 것이다.",
  ui_story_5071_50711101_40_dialog_content = "물론 나도 조사를 받는다. 내가 관련이 있다면 순순히 제재를 받을 것이다.",
  ui_story_5071_50711101_41_dialog_content = "하지만 치안대는... 총상회가 이끄는 조직이었을 텐데요.",
  ui_story_5071_50711101_42_dialog_content = "게다가 대원들도 전부 이스타반 클랜 출신이고 말이죠.",
  ui_story_5071_50711101_43_dialog_content = "총상회의 책임자도 당신 딸이지 않습니까?",
  ui_story_5071_50711101_44_dialog_content = "낯선 얼굴이군. 내게 하고 싶은 말이 많아 보이는데.",
  ui_story_5071_50711101_45_dialog_content = "그거 협박입니까?",
  ui_story_5071_50711101_46_dialog_content = "저야말로 묻고 싶군요, 섀도우마스터. 당신이 정말 처벌을 받을 수 있는 겁니까?",
  ui_story_5071_50711101_47_dialog_content = "그 「움브라톤 치안 조례」라는 것도 이제 막 공포했을 뿐인데,\n너무 쉽게 장담하시는 거 아닙니까?!",
  ui_story_5071_50711101_48_dialog_content = "이본 여사님이 돌아가시다니, 정말 유감이네요...",
  ui_story_5071_50711101_49_dialog_content = "전 오랜 친구로서 당신도 조금은 달라졌을 줄 알았어요.",
  ui_story_5071_50711101_50_dialog_content = "그런데 오랜 세월이 흘렀지만, 당신이나 움브라톤이나 여전히 과거의 상처를 잊지 못했군요.",
  ui_story_5071_50711101_51_dialog_content = "이스타반... 아니, 「<color=#FFB400>케이드</color>」, 정말 우릴 놓아주지 않을 생각인가요?",
  ui_story_5071_50711101_52_dialog_content = "설마 오래전 그때처럼...",
  ui_story_5071_50711101_53_dialog_content = "당신에게 복종하지 않는 사람은 모두 없앨 건가요?",
  ui_story_5071_50711101_54_dialog_content = "......",
  ui_story_5071_50711101_55_dialog_content = "(수군수군──)",
  ui_story_5071_50711101_56_dialog_content = "소문에 따르면 섀도우마스터가 모든 반대파를 제거하고 지금의 자리에 올랐지...",
  ui_story_5071_50711101_57_dialog_content = "그 원고에 적혀 있던 「센트리 폰드」 말하는 건가요?",
  ui_story_5071_50711101_58_dialog_content = "「어둠의 위기」 전에 움브라톤을 주름잡던 보스들이 다 모였고,\n섀도우마스터가 혼자서 100명을 상대했다더군.",
  ui_story_5071_50711101_59_dialog_content = "그래, 그 100명은 지금의 우리처럼 모두 움브라톤 조직의 수장들이었지...",
  ui_story_5071_50711101_60_dialog_content = "그런 엄청난 힘이라니... 그러니까 그림자의 주인이 될 수 있었던 건가.",
  ui_story_5071_50711101_61_dialog_content = "<color=#FFB400>「케이드」</color>, 들었나요? 당신 과거는 아직 완전히 감춰지지 않았어요.",
  ui_story_5071_50711101_62_dialog_content = "당신이 자기 친구를 죽이고 「양아버지」를 해친 사실을 기억하는 건 저 혼자만이 아닐 거예요!",
  ui_story_5071_50711101_63_dialog_content = "그 원고에 적혀 있던 게 전부 사실이었다니...",
  ui_story_5071_50711101_64_dialog_content = "아마 진짜 과거는 그것보다 더 잔혹했을지도 모르죠.\n지금의 자리까지 올 수 있었던 것도 더 비열한 본질 덕분일지 누가 알겠어요?!",
  ui_story_5071_50711101_65_dialog_content = "그럼 역시 저런 짓을 하고도 남겠군!",
  ui_story_5071_50711101_66_dialog_content = "지금까지 드러난 것만으로도 참을 수 없을 지경인데, 이제 어떻게 저자를 믿죠?",
  ui_story_5071_50711101_67_dialog_content = "진작부터 들었던 얘기야.\n자기 친구를 팔고 백야성에 빌붙어서 지금 자리에 올랐다고 말이야...",
  ui_story_5071_50711101_68_dialog_content = "전설 속 「악마의 아이」...",
  ui_story_5071_50711101_69_dialog_content = "매번 개혁이라는 이름으로 우리 이익을 무시했던 것도 그 목적은 결국...",
  ui_story_5071_50711101_70_dialog_content = "정말 우릴 없애버릴 생각이었단 말이야?",
  ui_story_5071_50711101_71_dialog_content = "오늘 다시 만나서 기쁘게 생각했던 것은 진심이다... <color=#FFB400>「에바」</color>.",
  ui_story_5071_50711101_72_dialog_content = "하지만 조금 전까지도 난 왜 네가 「이 순간」에 나타났는지 깨닫지 못했지.",
  ui_story_5071_50711101_73_dialog_content = "잠시나마 네가 녀석의 꿈이 이뤄진 것을 보고 와 줬다고 진심으로 믿었다.",
  ui_story_5071_50711101_74_dialog_content = "이제 보니 이것이 네 목적이었군.",
  ui_story_5071_50711101_75_dialog_content = "전 당신과 달라요. 정말로 그 사람 꿈을 잊지 않은 건 저라고요.",
  ui_story_5071_50711101_76_dialog_content = "샤엘, 점검이 끝나는 대로 근처에 착륙하지.",
  ui_story_5071_50711101_77_dialog_content = "치안대가 오고 있을 것이다. 나머지는 저들에게 맡기자고.",
  ui_story_5071_50711101_78_dialog_content = "하지만 이 밑은 황야예요.",
  ui_story_5071_50711101_79_dialog_content = "게다가 암귀가 출몰하는 위험 구역과 가깝죠.",
  ui_story_5071_50711101_80_dialog_content = "저 남자... 아무래도 우릴 이대로 보내줄 생각이 없는 모양이야.",
  ui_story_5071_50711101_81_dialog_content = "설마... 그 개혁이란 걸 위해서 우릴...",
  ui_story_5071_50711101_82_dialog_content = "여러분, 걱정 마세요!",
  ui_story_5071_50711101_83_dialog_content = "저희 상회의 소형 비공정 몇 대가 근처에 있어요.\n절 믿어주신다면, 제가 여러분을 움브라톤까지 모셔다드리겠어요.",
  ui_story_5071_50711101_84_dialog_content = "좋습니다! 같이 가겠습니다!",
  ui_story_5071_50711101_85_dialog_content = "지금은 보는 눈이 많아서 무슨 짓을 못 벌이겠지만, 이대로 여기 남았다간...",
  ui_story_5071_50711101_86_dialog_content = "게다가 전 가족이 있습니다! 아직 죽고 싶지 않다고요!",
  ui_story_5071_50711101_87_dialog_content = "(수군수군──)",
  ui_story_5071_50711101_88_dialog_content = "저, 저도 같이 가겠어요!",
  ui_story_5071_50711101_89_dialog_content = "저도 가겠습니다!",
  ui_story_5071_50711101_90_dialog_content = "얼른 가자고! 여기 있으면 위험해!",
  ui_story_5071_50711101_91_dialog_content = "뭐야? 죄다 낚여가지고는, 우릴 무슨 악당 취급하는 거야?",
  ui_story_5071_50711101_92_dialog_content = "지금까진 툭하면 우리한테 아부해 놓고, 흥!",
  ui_story_5071_50711101_93_dialog_content = "어이! 그 여자 따라가면 진짜로 위험할지도 모른다고!",
  ui_story_5071_50711101_94_dialog_content = "어쩔 수 없죠. 여기 남으면 우리가 뭘 할지 장담 못 하니까요.",
  ui_story_5071_50711101_95_dialog_content = "빨리 도망쳐!",
  ui_story_5071_50711101_96_dialog_content = "가게 두어라.",
  ui_story_5071_50711101_97_dialog_content = "한스티 회장에겐 자기 「계획」이 있는 듯하군.",
  ui_story_5071_50711101_98_dialog_content = "그 계획을 이룰 때까지는 자기 손으로 저 귀중한 「관객」들을 해칠 일은 없을 것이다.",
  ui_story_5071_50711101_99_dialog_content = "저 자식들, 돌아가면 분명히 멋대로 지껄이고 다닐 겁니다!",
  ui_story_5071_50711101_100_dialog_content = "너희도 소형 비공정을 타고 쫓아가라.",
  ui_story_5071_50711101_101_dialog_content = "대신 거리를 유지해라. 사람들의 안전만 확보하면 된다.",
  ui_story_5071_50711101_102_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_5071_50711101_103_dialog_content = "이 비공정, 아무래도 정말 곤란해진 모양이네요. 당신들...",
  ui_story_5071_50711101_104_dialog_content = "이대로 그 남자 곁에 있으면 분명히 위험할 거예요.",
  ui_story_5071_50711101_105_dialog_content = "이스타반 씨는 아직 아무것도 안 했는데, 그런 식으로 말하면 안 되죠.",
  ui_story_5071_50711101_106_dialog_content = "그 남자는 줄곧 자신을 그림자 속에 숨겨 왔어요. 하지만 전 그의 진짜 모습을 알고 있죠.",
  ui_story_5071_50711101_107_dialog_content = "형제를 제 손으로 죽이고, 양아버지의 모든 걸 빼앗고,\n심지어 그들을 아무도 기억하지 못하는 그림자 속에 파묻어 버렸어요.",
  ui_story_5071_50711101_108_dialog_content = "그 남자는 이익을 위해서라면 자신의 이름조차 버릴 수 있는 사람이에요.",
  ui_story_5071_50711101_109_dialog_content = "그저 왕좌에 기어오르기 위해 누구든 짓밟고 나아가는 「악마」일 뿐이라고요.",
  ui_story_5071_50711101_X109_dialog_content = "「케이드」, 당신은 그 <color=#FFB400>지팡이</color>를 가질 자격이 없어요!",
  ui_story_5071_50711101_110_dialog_content = "......",
  ui_story_5071_50711101_111_dialog_content = "...당신이 뭐라고 하든, 전 제가 지금까지 봐 온 이스타반 씨를 믿어요.",
  ui_story_5071_50711101_112_dialog_content = "말 잘했네. 그럼 한스티 씨, 미안하지만 먼저 가세요.",
  ui_story_5071_50711101_113_dialog_content = "미안해요. 전 제가 여기 있는 게 좋을 것 같다고 생각해요.",
  ui_story_5071_50711101_114_dialog_content = "저도 남을래요. 여긴 특종 냄새가 나거든요.",
  ui_story_5071_50711101_115_dialog_content = "......",
  ui_story_5071_50711101_116_dialog_content = "당신들, 반드시 후회할 거예요.",
  ui_story_5071_50711101_117_dialog_content = "그 남자가 얼마나 횡포한 사람인지 이미 다 알고 있으면서,\n왜 정작 눈앞의 위험은 헤아리질 못하는 거죠?",
  ui_story_5071_50711101_118_dialog_content = "불쌍한 사람들... 정말 가엽네요.",
  ui_story_5071_50711101_119_dialog_content = "그럼, 또 보자고. 「한스티」 회장.",
  ui_story_5071_50711101_120_dialog_content = "자, 이제 너희도...",
  ui_story_5071_50711101_121_dialog_content = "...적이에요!",
  ui_story_5071_50711101_122_dialog_content = "샤엘 회장님, 조심하세요! 경비병들이...!",
  ui_story_5071_50711101_123_dialog_content = "한패가 있었습니다! 놈들을...!",
  ui_story_5071_50711101_124_dialog_content = "닥쳐!",
  ui_story_5071_50711101_125_dialog_content = "「보스」의 명령이다! 한 놈도 남기지 마라!",
  ui_story_5071_50711101_126_dialog_content = "이런... 여러분! <size=45>싸울 준비하세요!</size>",
  ui_story_5071_50711102_1_dialog_content = "상회의 보안요원들이 전부...",
  ui_story_5071_50711102_2_dialog_content = "생존자는 없는 것 같아요... 휴...",
  ui_story_5071_50711102_3_dialog_content = "여기 남아서 다행이야...",
  ui_story_5071_50711102_4_dialog_content = "보스! 괜찮으십니까?! 저 여기 있습니다! 창밖이요!",
  ui_story_5071_50711102_5_dialog_content = "내가 가서 사람들의 안전을 지키라고 했을 텐데, 왜 돌아온 거냐.",
  ui_story_5071_50711102_6_dialog_content = "앞에서 수상한 움직임을 보이는 놈들이 보여서요. 보스가 걱정이 돼서 왔죠.",
  ui_story_5071_50711102_7_dialog_content = "그래서 벌써 다 해치우신 겁니까?",
  ui_story_5071_50711102_8_dialog_content = "...됐으니 와서 손님들부터 데려가라.",
  ui_story_5071_50711102_9_dialog_content = "PlayerName 넌 그렇다 쳐도, 버질 넌 왜 남았니?",
  ui_story_5071_50711102_10_dialog_content = "네? 그야 여기가 사장님 비공정이잖아요?",
  ui_story_5071_50711102_11_dialog_content = "왜요? 저 아직 근무시간인데, 맘대로 어디 가면 안 되는 거 아니었어요?",
  ui_story_5071_50711102_12_dialog_content = "......",
  ui_story_5071_50711102_13_dialog_content = "...이스타반 씨, 아까 저도 그 원고 읽었어요.",
  ui_story_5071_50711102_14_dialog_content = "그중엔 이스타반 씨 이야기인 것 같은 내용도 있었죠... 근데 전 하나도 못 믿겠어요.",
  ui_story_5071_50711102_15_dialog_content = "그러니까 말해주세요. 진짜 그런 일을 한 건가요? 그리고 멜리사 부인도...",
  ui_story_5071_50711102_16_dialog_content = "PlayerName!",
  ui_story_5071_50711102_17_dialog_content = "고용주도 제쳐놓고 자기가 나서서 책임을 묻는 건 옳지 않아.",
  ui_story_5071_50711102_18_dialog_content = "죄, 죄송해요...",
  ui_story_5071_50711102_19_dialog_content = "게다가 지금은 그런 얘길 할 때가 아니잖아.",
  ui_story_5071_50711102_20_dialog_content = "우린 아직 비공정을 타고 있잖아. 고장부터 해결하는 게 먼저야.",
  ui_story_5071_50711102_21_dialog_content = "책임질 사람한텐 일 끝나고 내가 어련히 이자까지 쳐서 돌려받을 테니까.",
  ui_story_5071_50711102_22_dialog_content = "기다리도록 하지.",
  ui_story_5071_50711102_23_dialog_content = "그나저나 섀도우마스터도 그렇게 쩨쩨한 편은 아니었을 텐데요.",
  ui_story_5071_50711102_24_dialog_content = "분명히 저 사람들한테 힘도 써 주고 많이 도와줬었는데.",
  ui_story_5071_50711102_25_dialog_content = "정작 저렇게 옆에서 살짝 부추기니까 다 도망가 버렸네요.",
  ui_story_5071_50711102_26_dialog_content = "아니, 지금 이런 상황에 상회장님까지 그런 소릴 하면 어쩝니까?",
  ui_story_5071_50711102_27_dialog_content = "자 여기까지~ 이럴 때일수록 우리끼리 도와야지, 이러면 안 되죠~",
  ui_story_5071_50711102_28_dialog_content = "휴... 섀도우마스터랑 인터뷰 잡고 싶었는데... 타이밍이 영 안 좋네요...",
  ui_story_5071_50711102_29_dialog_content = "섀도우마스터, 저흰 이제 어떻게 하면 좋겠습니까?",
  ui_story_5071_50711102_30_dialog_content = "나를 믿고 여기 남아준 것에 진심으로 감사하지.",
  ui_story_5071_50711102_31_dialog_content = "부하들이 지상까지 데려다 줄 것이다.",
  ui_story_5071_50711102_32_dialog_content = "세르고, 비공정을 준비해서 손님들을 지상으로 보내도록.",
  ui_story_5071_50711102_33_dialog_content = "저 과거의 그림자들이 노리는 것은 나다.",
  ui_story_5071_50711102_34_dialog_content = "너희는 손님들을 지켜라.",
  ui_story_5071_50711102_35_dialog_content = "보스...",
  ui_story_5071_50711102_36_dialog_content = "명령이다.",
  ui_story_5071_50711102_37_dialog_content = "예...",
  ui_story_5071_50711102_38_dialog_content = "여기는 베델, 통신을 요청합니다.",
  ui_story_5071_50711102_39_dialog_content = "아버님, 쌍사성으로 통하는 수송로에 수상한 자들이 나타났어요.",
  ui_story_5071_50711102_40_dialog_content = "그자들은 움브라톤으로 무기와 용병을 보내려고 시도했고, 저희가 이미 현장에서 체포했어요.",
  ui_story_5071_50711102_41_dialog_content = "아버님 쪽 상황은 어떤가요? 샤엘 씨 비공정 초도비행 기념식은 잘되고 있나요?",
  ui_story_5071_50711102_42_dialog_content = "이쪽은 순조롭다. 걱정하지 마라.",
  ui_story_5071_50711102_43_dialog_content = "베델, 소란 피우길 좋아하는 「손님」들이 집에 나타날지도 모른다.",
  ui_story_5071_50711102_44_dialog_content = "넌 주인으로서 「손님」들을 어떻게 대접할지 준비해라.",
  ui_story_5071_50711102_45_dialog_content = "알겠어요. 아버님도 조심하세요.",
  ui_story_5071_50711102_46_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_5071_50711102_47_dialog_content = "이런... 비공정이 균형을 못 잡고 있어요.",
  ui_story_5071_50711102_48_dialog_content = "게다가 지금 이건 흔들림이 아니라 진동이에요... 동력이 점점 약해지고 있는 것 같아요...",
  ui_story_5071_50711102_49_dialog_content = "달링, 콜로서스를 조종하는 네가 그런 말을 하니까 무섭잖아.",
  ui_story_5071_50711102_50_dialog_content = "이상해요. 수리가 끝났으면 이렇게 되진 않았을 텐데요...",
  ui_story_5071_50711102_51_dialog_content = "상태가 계속 악화돼서 이대로 떨어진다면... 우린 움브라톤 중심부에 추락할 거예요!",
  ui_story_5071_50711102_52_dialog_content = "회, 회장님! 큰일 났습니다!",
  ui_story_5071_50711102_53_dialog_content = "내려가 보니 수리를 담당했던 사람들이 전부...",
  ui_story_5071_50711102_54_dialog_content = "뭐라고요?!",
  ui_story_5071_50711201_1_dialog_content = "이런... 얼른 제어실로 가요.",
  ui_story_5071_50711201_2_dialog_content = "기관사들이 아직 안에 있어요!",
  ui_story_5071_50711201_3_dialog_content = "아...",
  ui_story_5071_50711201_4_dialog_content = "늦었어... 기관사도 전부... 게다가 컨트롤러까지 부서졌어.",
  ui_story_5071_50711201_5_dialog_content = "너무해...",
  ui_story_5071_50711201_6_dialog_content = "일단 비공정의 방향을 바꿀 방법부터 찾아야 해.",
  ui_story_5071_50711201_7_dialog_content = "또 한발 늦다니...",
  ui_story_5071_50711201_8_dialog_content = "......",
  ui_story_5071_50711201_9_dialog_content = "...아니, 잠깐만요...!",
  ui_story_5071_50711201_10_dialog_content = "진짜로 스카이워커호 모양대로 여길 만든 거였어요?!",
  ui_story_5071_50711201_11_dialog_content = "저번에 그 말 그냥 농담인 줄 알았는데요...",
  ui_story_5071_50711201_12_dialog_content = "네가 행사에 귀빈으로 참가해 준다면...",
  ui_story_5071_50711201_13_dialog_content = "내가 제어실을 콜로서스랑 똑같이 만들어 줄게, 어때?",
  ui_story_5071_50711201_14_dialog_content = "그래서, 와 줄 거야?",
  ui_story_5071_50711201_X11_dialog_content = "후훗, 이 정도는 나한테는 어려운 일도 아니잖아.",
  ui_story_5071_50711201_15_dialog_content = "당연하지. 넌 내 소중한 「세일즈 포인트」인걸.",
  ui_story_5071_50711201_16_dialog_content = "그럼... 제가 조종할 수 있을지도 모르겠네요?",
  ui_story_5071_50711201_17_dialog_content = "그래! 넌 콜로서스 조종사잖아. 얼마든지 시도해 봐.",
  ui_story_5071_50711201_18_dialog_content = "그럼 평소처럼 「연주」하면...",
  ui_story_5071_50711201_19_dialog_content = "음...",
  ui_story_5071_50711201_20_dialog_content = "반응이 없어요!",
  ui_story_5071_50711201_21_dialog_content = "이건 스카이워커호의 시스템이랑은 전혀 달라요!",
  ui_story_5071_50711201_X21_dialog_content = "역시... 어떻게 해야 할지 잘 모르겠어요...",
  ui_story_5071_50711201_X22_dialog_content = "휴, 그것도 그렇네.\n애초에 이 컨트롤러는 아이테르의 물건도 아니고, 내가 구해 온 골동품인걸.",
  ui_story_5071_50711201_22_dialog_content = "심지어 고장까지 났고요...",
  ui_story_5071_50711201_23_dialog_content = "모방은 어디까지나 모방이니까... 휴, 역시 무리구나.",
  ui_story_5071_50711201_24_dialog_content = "그럼 어떻게...",
  ui_story_5071_50711201_25_dialog_content = "어... 골동품?",
  ui_story_5071_50711201_26_dialog_content = "형아, 사장님, 저 이런 컨트롤러 본 적 있어요.",
  ui_story_5071_50711201_27_dialog_content = "구조를 알고 있어? 그럼 수리도 가능할까?",
  ui_story_5071_50711201_28_dialog_content = "조금만 시간을 주시면 「복원」할 수 있을 거 같아요.",
  ui_story_5071_50711201_29_dialog_content = "시간은 충분한가.",
  ui_story_5071_50711201_30_dialog_content = "추락하는 속도가 점점 빨라지고 있는 듯하군.",
  ui_story_5071_50711201_31_dialog_content = "잠깐만요... 만약 이 비공정 구조가... 정말 콜로서스를 본뜬 거라면...",
  ui_story_5071_50711201_32_dialog_content = "저한테 방법이 있어요!",
  ui_story_5071_50711201_33_dialog_content = "바깥쪽에서 「날개」 방향을 바꿀 수만 있다면, 하강 속도를 늦춰서 긴급 착륙을 할 수 있어요.",
  ui_story_5071_50711201_34_dialog_content = "어떻게 해야 하지?",
  ui_story_5071_50711201_35_dialog_content = "절 따라오세요.",
  ui_story_5071_50711201_36_dialog_content = "PlayerName, 가져가!",
  ui_story_5071_50711201_37_dialog_content = "비공정 간이 매뉴얼이야. 구조를 이해하는 데 도움이 될 거야.",
  ui_story_5071_50711201_38_dialog_content = "난 여기서 버질을 지키고 있을 테니까, 그럼 비공정을 부탁할게.",
  ui_story_5071_50711201_39_dialog_content = "가지.",
  ui_story_5071_50711201_40_dialog_content = "잠깐만요... 또 문제가 있어요. 이 비공정의 날개는 공중에 노출돼 있어요.\n가까이 가려면 작은 비공정이 필요해요!",
  ui_story_5071_50711201_41_dialog_content = "그럼 일단 갑판으로 간다!",
  ui_story_5071_50711201_42_dialog_content = "(PlayerName, 섀도우마스터, 부디...)",
  ui_story_5071_50711201_X42_dialog_content = "휴, 다행이에요. 여기 비공정이 하나 남아 있네요!",
  ui_story_5071_50711201_44_dialog_content = "세르고가 남기고 간 모양이군.",
  ui_story_5071_50711201_45_dialog_content = "타라. 그리고 내가 뭘 해야 하는지 말해봐라.",
  ui_story_5071_50711201_46_dialog_content = "일단 매뉴얼에서 구조도를 좀 볼게요... 아, 찾았어요!",
  ui_story_5071_50711201_47_dialog_content = "이 비공정도 콜로서스처럼 날개가 있네요. 구조가 완전히 똑같진 않지만 원리는 같아요.",
  ui_story_5071_50711201_48_dialog_content = "날개 뒤쪽으로 가서 관절을 조정하면 날개의 방향이 바뀌고, 비공정도 방향을 틀게 될 거예요.",
  ui_story_5071_50711201_49_dialog_content = "꽉 잡아라!",
  ui_story_5071_50711201_50_dialog_content = "으앗──!",
  ui_story_5071_50711201_51_dialog_content = "자네가 말한 「날개」가 저건 아니겠지?",
  ui_story_5071_50711201_52_dialog_content = "하하! 정말 큰 날개로군.",
  ui_story_5071_50711201_53_dialog_content = "저걸 정말 움직일 수 있는 거냐.",
  ui_story_5071_50711201_54_dialog_content = "음... 조금만 더 가까이 갈 수 있을까요? 구조를 좀 확인해 봐야겠어요.",
  ui_story_5071_50711201_55_dialog_content = "어라...",
  ui_story_5071_50711201_56_dialog_content = "안 되겠어요...! 저 장치, 콜로서스에 비해 너무 투박해요!",
  ui_story_5071_50711201_57_dialog_content = "저건 동력으로 움직이는 점에만 중점을 둬서 합리적인 구조를 포기한 설계예요.\n저래서는 절대 수동으로 조정할 수가 없다구요...",
  ui_story_5071_50711201_58_dialog_content = "하하! 사소한 일에 연연하지 않고 낭만을 좇은 것인가. 그래야 젊은이의 <color=#FFB400>꿈</color>이라 할 수 있지!",
  ui_story_5071_50711201_59_dialog_content = "그 정도는 이해해 줄 수 있다.",
  ui_story_5071_50711201_60_dialog_content = "하늘을 날기를 꿈꾸는 날개가 그리 쉽게 현실에 굴복해선 안 되는 법 아니겠나!",
  ui_story_5071_50711201_61_dialog_content = "이스타반 씨! 더 가까이 가면 안 돼요! 말려들 거라구요──!",
  ui_story_5071_50711201_62_dialog_content = "가까이 안 가고 어떻게 방향을 조정하라는 거냐.",
  ui_story_5071_50711201_63_dialog_content = "이스타반 씨?!",
  ui_story_5071_50711201_64_dialog_content = "비공정 조종은 자네에게 맡기도록 하지.",
  ui_story_5071_50711201_65_dialog_content = "으으읍──!",
  ui_story_5071_50711201_66_dialog_content = "무리예요! 그런 거대한 전동장치에 손을 넣었다간...!",
  ui_story_5071_50711201_67_dialog_content = "PlayerName! 어느 쪽으로 돌리면 되는 거냐!",
  ui_story_5071_50711201_68_dialog_content = "네──?!",
  ui_story_5071_50711201_69_dialog_content = "<color=#e8d9bb>철컥──</color>",
  ui_story_5071_50711201_70_dialog_content = "(말도 안 돼... 저 큰 날개의 무게를 견디고 있어...)",
  ui_story_5071_50711201_71_dialog_content = "이스타반 씨한테서 왼쪽이요! 그걸 힘껏 돌리면 날개 전체가 움직일 거예요!",
  ui_story_5071_50711201_72_dialog_content = "흐아압──!",
  ui_story_5071_50711201_73_dialog_content = "그렇게 급하게── 떨어지지── 말란 말이다──!",
  ui_story_5071_50711201_74_dialog_content = "<color=#e8d9bb>철컥── 철컥──</color>",
  ui_story_5071_50711201_75_dialog_content = "(날개가... 움직였어...? 이렇게 큰 날개가 움직인다고?!)",
  ui_story_5071_50711201_76_dialog_content = "방향이 바뀌었어요! 성공이에요!",
  ui_story_5071_50711201_77_dialog_content = "아직이다──",
  ui_story_5071_50711201_78_dialog_content = "움브라톤에서 더 멀어져야 한다──",
  ui_story_5071_50711201_79_dialog_content = "움직여라──!",
  ui_story_5071_50711201_80_dialog_content = "<color=#e8d9bb>콰아앙──</color>",
  ui_story_5071_50711201_81_dialog_content = "큰일이에요! 후방 엔진이 폭발했어요!",
  ui_story_5071_50711201_82_dialog_content = "(이러다간 방향을 바꾸기 전에 추락해버리겠어...!)",
  ui_story_5071_50711201_83_dialog_content = "이대로면 여전히 움브라톤 범위 안이다. 아직 멀었다...",
  ui_story_5071_50711201_84_dialog_content = "얼른 돌아오세요! 이러다간 이스타반 씨까지──",
  ui_story_5071_50711201_85_dialog_content = "바람을 타고 날아올라라──!",
  ui_story_5071_50711201_86_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5071_50711201_87_dialog_content = "부, 불꽃?!",
  ui_story_5071_50711201_88_dialog_content = "뭐야... 비공정에 갑자기 웬 불꽃이...",
  ui_story_5071_50711201_89_dialog_content = "오! 저기 좀 봐!",
  ui_story_5071_50711201_90_dialog_content = "공중상회 비공정이 왔어!",
  ui_story_5071_50711201_91_dialog_content = "저거 알아! 아마 초도비행 기념식 프로그램일 거야...\n근데 이렇게 가까이서 할 줄은 몰랐네!",
  ui_story_5071_50711201_92_dialog_content = "불꽃이 정말 예쁘네! 저 부유 비공정도 정말 끝내주잖아!",
  ui_story_5071_50711201_93_dialog_content = "아마 샤엘 회장님이 축제 분위기 띄우려고 준비해 주신 거겠지!",
  ui_story_5071_50711201_94_dialog_content = "야! 이 바보들아! 지금 구경할 때가 아냐!",
  ui_story_5071_50711201_95_dialog_content = "빨리 튀어! 비공정이 곧 떨어질 거라구!",
  ui_story_5071_50711201_96_dialog_content = "이스타반 클랜 사람들 아냐? 왜 저렇게 흥분한 거지? 뭐라는 거야?",
  ui_story_5071_50711201_97_dialog_content = "다들 도망쳐! 섀도우마스터가 부유 비공정의 손님을 몰살했다!",
  ui_story_5071_50711201_98_dialog_content = "이제 부유 비공정으로 빈민굴을 들이받을 작정이야!",
  ui_story_5071_50711201_99_dialog_content = "우릴 따라와! 얼른 도시 밖으로 도망쳐!",
  ui_story_5071_50711201_100_dialog_content = "오, 오지 마! 우리가 뭘 잘못했다고 그러는 거야?!",
  ui_story_5071_50711201_101_dialog_content = "가까이 오면 공격하겠다!",
  ui_story_5071_50711201_102_dialog_content = "왜 우릴 경계하는 거야?! 젠장! 사람한테 돌 던지지 말라고!",
  ui_story_5071_50711201_103_dialog_content = "이스타반 클랜이 평민을 공격했다──!",
  ui_story_5071_50711201_104_dialog_content = "<size=45>저 망할 자식이!</size>",
  ui_story_5071_50711201_105_dialog_content = "다들 진정하세요... 우릴 계속 공격한다면 우리도 반격할 수밖에 없잖아요.",
  ui_story_5071_50711201_106_dialog_content = "흥, 저 자식들 왜 갑자기...",
  ui_story_5071_50711201_107_dialog_content = "비공정에서 헛소리 지껄이던 놈! 또 너냐?!",
  ui_story_5071_50711201_108_dialog_content = "거기 서라!",
  ui_story_5071_50711201_109_dialog_content = "휴, 정말 충동적인 녀석이라니까. 이래서야 처리하기 힘들겠어.",
  ui_story_5071_50711201_110_dialog_content = "어...?",
  ui_story_5071_50711201_111_dialog_content = "비공정 방향이 바뀌고 있잖아...?",
  ui_story_5071_50711201_112_dialog_content = "아무래도 컨트롤러를 수리한 모양이군.",
  ui_story_5071_50711201_113_dialog_content = "돌아가지.",
  ui_story_5071_50711201_114_dialog_content = "꽉 잡아라.",
  ui_story_5071_50711201_115_dialog_content = "이건 불 뿜는 버튼, 이건 방송 버튼, 그리고 이건...",
  ui_story_5071_50711201_116_dialog_content = "버질! 다 고친 거야?",
  ui_story_5071_50711201_117_dialog_content = "아니, 방향 조종은 되는데, 상승이 안 돼.",
  ui_story_5071_50711201_118_dialog_content = "음... 아무래도 엔진이 폭발했으니까...",
  ui_story_5071_50711201_119_dialog_content = "그럼 결국 추락을 면할 수 없다는 거구나...",
  ui_story_5071_50711201_120_dialog_content = "만약 방향을 제어해서 골드리버에 비상 착륙할 수만 있다면,\n비행선도 그나마 온전하게 건질 수 있을 거예요.",
  ui_story_5071_50711201_121_dialog_content = "사장님, 강 쪽으로 갈까요?",
  ui_story_5071_50711201_122_dialog_content = "...그랬다간 강 양쪽 주민들이 피해를 입진 않을까?",
  ui_story_5071_50711201_123_dialog_content = "역시 협곡 쪽으로 가자. 거긴 사람이 없으니까.",
  ui_story_5071_50711201_124_dialog_content = "근데 그럼 이 비공정은 산산조각 날 거예요.",
  ui_story_5071_50711201_125_dialog_content = "내 탓이다. 네 비공정을...",
  ui_story_5071_50711201_126_dialog_content = "무슨 말을 그렇게 하세요, 섀도우마스터. 꼭 자기가 흑막인 것처럼.",
  ui_story_5071_50711201_127_dialog_content = "......",
  ui_story_5071_50711201_128_dialog_content = "조종 방법을 가르쳐 줘. 그리고 다들 먼저 피해.",
  ui_story_5071_50711201_129_dialog_content = "사장님?",
  ui_story_5071_50711201_130_dialog_content = "결국 누군가 남아서 조종해야 하는 거잖아? 그리고 이건 내 비공정인걸.",
  ui_story_5071_50711201_131_dialog_content = "그러니까 다들──",
  ui_story_5071_50711201_132_dialog_content = "너흰 가라. 내가 조종하지.",
  ui_story_5071_50711201_133_dialog_content = "이스타반 씨?!",
  ui_story_5071_50711201_134_dialog_content = "그게 무슨...",
  ui_story_5071_50711201_135_dialog_content = "샤엘, 남이 할 일을 빼앗지 마라.",
  ui_story_5071_50711201_136_dialog_content = "게다가 이런 일이라면 이미 경험이 있다.",
  ui_story_5071_50711201_137_dialog_content = "가라. 하늘을 나는 것을 갈망한 자의 꿈은 하늘에서 부서지진 않을 테니.",
  ui_story_5071_50711201_138_dialog_content = "이스타반 씨...",
  ui_story_5071_50711201_139_dialog_content = "아이들을 데리고 무사히 돌아가라.",
  ui_story_5071_50711201_140_dialog_content = "...기억하시죠? 저한테 빚진 거.",
  ui_story_5071_50711201_141_dialog_content = "맹세는 결코 잊지 않는다.",
  ui_story_5071_50711201_142_dialog_content = "그럼 됐어요. 애들은 제가 지킬게요.",
  ui_story_5071_50711201_143_dialog_content = "대신 조건이 있어요. 당신이 처음 약속한 대로 제 소원을 들어주세요.",
  ui_story_5071_50711201_144_dialog_content = "...꼭 살아요. 그게 제 소원이에요.",
  ui_story_5071_50711201_145_dialog_content = "...그 소원, 들어주지.",
  ui_story_5071_50711201_146_dialog_content = "자, 시간이 없다. 가라!",
  ui_story_5071_50711201_147_dialog_content = "부디 그림자가 너흴 지켜주길 빌겠다.",
  ui_story_5071_50711201_148_dialog_content = "<color=#FFB400>「배런」</color>... 나의 친구여, 이 꿈이 좀 더 강해질 수 있게 해 주게...",
  ui_story_5071_50711202_1_dialog_content = "브리지먼 회장님, 드디어 돌아오셨군요.",
  ui_story_5071_50711202_2_dialog_content = "제 소개는 필요 없겠죠.",
  ui_story_5071_50711202_3_dialog_content = "베, 베델 님? 아이고, 여긴 어쩐 일로 다...",
  ui_story_5071_50711202_4_dialog_content = "미리 연락도 안 주시고...",
  ui_story_5071_50711202_5_dialog_content = "교외에서 용병 일당을 붙잡았어요. 무장하고 움브라톤으로 들어오려고 하더군요.",
  ui_story_5071_50711202_6_dialog_content = "사용하는 운송 수단이나 협력자 및 자백 내용에 따라...",
  ui_story_5071_50711202_7_dialog_content = "우린 당신의 「붉은표범 상회」, 그리고 당신 파트너인 「잿빛앵무 상회」,\n「러스티 팔콘 클랜」...",
  ui_story_5071_50711202_8_dialog_content = "적어도 이 세 조직이 이번 일에 관여한 것으로 의심하고 있어요.",
  ui_story_5071_50711202_9_dialog_content = "여기 당신이 규정을 어기고 무기 밀수를 한 증거 사진이에요.",
  ui_story_5071_50711202_10_dialog_content = "《움브라톤 치안 조례》에 근거해 동행을 요구하겠어요. 같이 가 주시죠.",
  ui_story_5071_50711202_11_dialog_content = "자, 잠깐만요! 이거 분명히 무슨 오해가 있는 겁니다!",
  ui_story_5071_50711202_12_dialog_content = "당신들 멋대로 이렇게 사람을 끌고 가려고 해도 되는 겁니까?!",
  ui_story_5071_50711202_13_dialog_content = "한 시간만... 아니, 삼십 분만 시간을 좀...",
  ui_story_5071_50711202_14_dialog_content = "무슨 뜻이죠?",
  ui_story_5071_50711202_15_dialog_content = "뭔가 다른 계획이라도 있으신 모양이군요...",
  ui_story_5071_50711202_16_dialog_content = "<size=45>꺄아악──!</size>",
  ui_story_5071_50711202_17_dialog_content = "밖에 무슨 일이죠?",
  ui_story_5071_50711202_18_dialog_content = "뭔가요? 왜 다들 난리가 난 거죠?",
  ui_story_5071_50711202_19_dialog_content = "일단 이 사람부터 압송하세요.",
  ui_story_5071_50711202_20_dialog_content = "예!",
  ui_story_5071_50711202_21_dialog_content = "베델입니다. 총상회, 응답하세요. 무슨 일이죠?",
  ui_story_5071_50711202_22_dialog_content = "베델 님! 돌아오셨습니까?!",
  ui_story_5071_50711202_23_dialog_content = "섀, 섀도우마스터... 섀도우마스터께서... 아...",
  ui_story_5071_50711202_24_dialog_content = "일단 진정해요. 아버님께 무슨 일이라도 있나요? 말해 보세요.",
  ui_story_5071_50711202_25_dialog_content = "섀도우마스터와 샤엘 회장님이 탄 비공정이 추락하고 있습니다!",
  ui_story_5071_50711202_26_dialog_content = "뭐라고요?!",
  ui_story_5071_50711202_27_dialog_content = "<color=#e8d9bb>콰아아앙──!</color>",
  ui_story_5071_50711202_28_dialog_content = "바, 방금 그거... 비공정이 추락한 건가요...?",
  ui_story_5071_50711202_29_dialog_content = "베델 님... 저흰 이제 어떡해야 합니까?",
  ui_story_5071_50711202_30_dialog_content = "방금 비공정에서 추락한 물건이 거리에 떨어진 것 같습니다.",
  ui_story_5071_50711202_31_dialog_content = "지금 거리엔 주민들 사이에 섞여 소란을 부추기는 자들이 있고...\n도시 밖에는 용병들이 곳곳에 있습니다...",
  ui_story_5071_50711202_32_dialog_content = "세르고 님이 저희한테 섀도우마스터를 도우러 가라고 하셨지만,\n베델 님 허락 없이 움직일 순 없어서...",
  ui_story_5071_50711202_33_dialog_content = "(아버님...)",
  ui_story_5071_50711202_34_dialog_content = "(그랬군요.)",
  ui_story_5071_50711202_35_dialog_content = "(절 데리고 가지 않으신 건 위험을 짐작하셨기 때문인가요.)",
  ui_story_5071_50711202_36_dialog_content = "...베델 님?",
  ui_story_5071_50711202_37_dialog_content = "섀도우마스터는 분명히 무사하실 거예요. 침착하게 대응하세요.",
  ui_story_5071_50711202_38_dialog_content = "먼저 총상회 전원에게 제 명령을 전달하세요.",
  ui_story_5071_50711202_39_dialog_content = "네, 네!",
  ui_story_5071_50711202_40_dialog_content = "지금 누군가 움브라톤을 노리고 있어요. 절대 상대가 파고들 허점을 보여선 안 돼요.",
  ui_story_5071_50711202_41_dialog_content = "제가 명단과 증거를 치안대에 전달할게요. 클레이튼을 치안대 본부로 보내세요.",
  ui_story_5071_50711202_42_dialog_content = "치안대와 협조해서 명단에 있는 사람들을 체포하라고 하세요.\n혼란을 틈타 도주하거나 저항할지도 모르니 절대 방심해선 안 돼요.",
  ui_story_5071_50711202_43_dialog_content = "네!",
  ui_story_5071_50711202_44_dialog_content = "세르고에겐 치안대 전투요원을 소집해 절반은 교외에 주둔시키라고 하세요.",
  ui_story_5071_50711202_45_dialog_content = "파티와 파시는 저와 합류해서 거리의 소란을 해결하라고 전하고요.",
  ui_story_5071_50711202_46_dialog_content = "그 외 구조대 주력은 저와 함께 주민을 구조하고,\n두 팀을 차출해서 섀도우마스터를 찾도록 보내세요.",
  ui_story_5071_50711202_47_dialog_content = "섀도우마스터께서 돌아오실 때까지, 그 누구도 혼란에 빠져선 안 돼요.\n우리가 그분 대신 움브라톤을 지키는 거예요, 알겠어요?",
  ui_story_5071_50711202_48_dialog_content = "네! 베델 님!",
  ui_story_5071_50711202_49_dialog_content = "(아버님... 전 아버님을 믿어요. 그러니까 꼭 그때처럼...)",
  ui_story_5071_50711202_50_dialog_content = "(다시 한번 <color=#FFB400>「영웅」</color>처럼 등장해 주세요.)",
  ui_story_5071_50711301_1_dialog_content = "비공정이... 그렇게 예뻤던 비공정이 이렇게 사라져 버리다니...",
  ui_story_5071_50711301_2_dialog_content = "사람이 없는 교외로 떨어졌어. 이스타반 씨가 성공한 거야.",
  ui_story_5071_50711301_3_dialog_content = "달링, 조금 더 가까이 착륙해 줘.",
  ui_story_5071_50711301_4_dialog_content = "방금까지만 해도 하늘에 있었는데, 지금은...",
  ui_story_5071_50711301_5_dialog_content = "어쩔 수 없잖니. 움브라톤 사람의 꿈은 오래가는 법이 없거든.",
  ui_story_5071_50711301_6_dialog_content = "으, 불길이 너무 세요... 주변이 다 불탄 잔해들이에요...",
  ui_story_5071_50711301_7_dialog_content = "비공정에 있던 예술 작품도 전부... 사장님, 이, 이제 어떡하죠?",
  ui_story_5071_50711301_8_dialog_content = "내 개인 소장품은 둘째치고, 일부는 손님의 경매 물품인 데다가,\n미술품 레플리카 제작도 불가능한 소장품들이었으니... 내가 배상하는 수밖에 없겠네.",
  ui_story_5071_50711301_9_dialog_content = "샤엘 씨...",
  ui_story_5071_50711301_10_dialog_content = "난 괜찮아, 달링. 사업하는 사람들은 이런 데 익숙해.\n벌 때가 있으면, 손해 볼 때도 있기 마련이거든.",
  ui_story_5071_50711301_11_dialog_content = "그래도 배상 때문에 깡통 찰 정도는 아냐. 일단 섀도우마스터의 행방부터 확인해 보자.",
  ui_story_5071_50711301_12_dialog_content = "뜨, 뜨거워요... 섀도우마스터는... 이런 상황에서도 무사하실 수 있는 건가요?",
  ui_story_5071_50711301_13_dialog_content = "그림자가 제일 잘하는 건 보이지 않는 구석에서 살아남는 거야.\n그러니까 섀도우마스터는 분명 살아 있어.",
  ui_story_5071_50711301_14_dialog_content = "사장님, 위험해요! 거긴 불길이 너무 세요!",
  ui_story_5071_50711301_15_dialog_content = "(감응해 봐도... 이스타반 씨의 기운이 안 느껴져.)",
  ui_story_5071_50711301_16_dialog_content = "섀도우마스터? 섀도우마스터?!",
  ui_story_5071_50711301_17_dialog_content = "나이가 들더니 귀까지 어두워진 건가요? 숨바꼭질은 이제 그만하세요.",
  ui_story_5071_50711301_18_dialog_content = "(베델은 어떡하지... 움브라톤은 또 어떡하고... 베델한테 뭐라고 말해줘야 하지...?)",
  ui_story_5071_50711301_19_dialog_content = "사장님, 안 돼요! 얼른 나오세요! 조금 있으면 여기도 다 불타 버릴 거라구요...",
  ui_story_5071_50711301_20_dialog_content = "아직 받아야 할 빚이 남아 있단 말이야.\n섀도우마스터는 신용 있는 사람이니까, 절대 나한테 진 빚을 떼먹을 리 없어!",
  ui_story_5071_50711301_21_dialog_content = "그치만 사장님...",
  ui_story_5071_50711301_22_dialog_content = "전 잘 모르겠어요... 섀도우마스터는 착한 사람인가요? 아니면 악당인가요?",
  ui_story_5071_50711301_23_dialog_content = "...버질.",
  ui_story_5071_50711301_24_dialog_content = "어른들의 세계엔 그저 착한 사람도, 악당도 없어.",
  ui_story_5071_50711301_25_dialog_content = "그래도 섀도우마스터가 자기 목숨도 아끼지 않고 우릴 구한 건 의심의 여지가 없는 사실이야.",
  ui_story_5071_50711301_26_dialog_content = "이 불길... 얼른 사람들을 불러서 불을 끄는 게 좋겠어.",
  ui_story_5071_50711301_27_dialog_content = "베델한테도 말해야겠죠?",
  ui_story_5071_50711301_28_dialog_content = "...음, 물론 말해줘야지.",
  ui_story_5071_50711301_29_dialog_content = "이번 일에는 「음모」의 기운이 짙게 느껴지니 말이야.",
  ui_story_5071_50711301_30_dialog_content = "이본 여사님은 독살이 의심되는 정황이 있고, 비공정엔 우릴 공격하는 백야성 경비병까지 있었어.",
  ui_story_5071_50711301_31_dialog_content = "이 모든 걸 꾸민 사람은 날 노리는 게 아닌 것 같아.\n저들의 목적은 움브라톤... 아니면 섀도우마스터겠지.",
  ui_story_5071_50711301_32_dialog_content = "이스타반 씨가 「과거의 그림자」란 얘길 했었는데,\n혹시 상대가 누군지 이미 알고 계시던 건 아닐까요?",
  ui_story_5071_50711301_33_dialog_content = "...과거의 그림자? 그럼 「한스티」 씨가 할 말이 많겠는걸.",
  ui_story_5071_50711301_34_dialog_content = "잠깐만요, 누가 오고 있어요!",
  ui_story_5071_50711301_35_dialog_content = "우우우── 우우우──",
  ui_story_5071_50711301_36_dialog_content = "이건... 부엉이 울음소리?",
  ui_story_5071_50711301_37_dialog_content = "찾았구나, 돌아오렴.",
  ui_story_5071_50711301_38_dialog_content = "우우우── 우우우──",
  ui_story_5071_50711301_39_dialog_content = "...「한스티」 씨?",
  ui_story_5071_50711301_40_dialog_content = "(부엉이...? 뭔가 익숙한 느낌인데...)",
  ui_story_5071_50711301_41_dialog_content = "하필 여기라니 정말 공교롭네요... 수년 전, 여긴 그 웅장한 「센트리 폰드」가 있었죠.",
  ui_story_5071_50711301_42_dialog_content = "바로 그 「배신자」가 자기 형제를 살해한 곳 말이에요.",
  ui_story_5071_50711301_43_dialog_content = "?!",
  ui_story_5071_50711301_44_dialog_content = "이게 바로 운명이라는 걸까요? 「배런」, 제가 또 당신 곁으로 돌아왔어요...",
  ui_story_5071_50711301_45_dialog_content = "공교롭게도 그 「배신자」까지 여기로 추락했고 말이에요!",
  ui_story_5071_50711301_46_dialog_content = "녀석이 끝내 천벌을 받은 걸 보면, 아무리 움브라톤이라도 신은 있었던 모양이네요.",
  ui_story_5071_50711301_47_dialog_content = "제가 손을 더럽힐 필요도 없었고 말이죠...",
  ui_story_5071_50711301_48_dialog_content = "훗... 후훗.",
  ui_story_5071_50711301_49_dialog_content = "섀도우마스터의 「과거의 그림자」라는 건 역시 당신이었군요, 「한스티」 씨.",
  ui_story_5071_50711301_50_dialog_content = "그때 대체 무슨 일이 있었던 거죠? 여긴 대체...",
  ui_story_5071_50711301_51_dialog_content = "그 작가가 아주 자세히 적어 줬잖아?",
  ui_story_5071_50711301_52_dialog_content = "「배신자 케이드」가 자기 손으로 형제 「배런」의 목숨과 모든 것을 빼앗고,\n움브라톤을 팔아넘겼다고 말이야.",
  ui_story_5071_50711301_53_dialog_content = "그리고 난 그자가 지워야 할 「과거」로서, 외지를 정처 없이 떠돌았지.",
  ui_story_5071_50711301_54_dialog_content = "내가 바깥에서 온갖 치욕을 참아 가며 수년간 활동해 온 이유는...\n언젠간 「고향」에 돌아와...",
  ui_story_5071_50711301_55_dialog_content = "내 손으로 직접 저 치밀한 「배신자」 녀석의 가면을 벗기기 위해서였어!",
  ui_story_5071_50711301_56_dialog_content = "심지어 녀석은 이스타반이라 불릴 자격도 없어! 그건 「배런」의 성이었으니까!",
  ui_story_5071_50711301_57_dialog_content = "죄송한데요... 잠깐 좀 끼어들게요...",
  ui_story_5071_50711301_58_dialog_content = "방금까진 상황이 급해서 계속 타이밍을 못 잡았거든요...",
  ui_story_5071_50711301_59_dialog_content = "저 계속 궁금했어요. 우리가 마지막에 본 그 원고들, 진짜 이본 선생님이 직접 적은 건가요?",
  ui_story_5071_50711301_60_dialog_content = "버질, 무슨 얘길 하고 싶은 거야?",
  ui_story_5071_50711301_61_dialog_content = "이본 선생님은 창작에 무척 열정적인 분이셨어요. 그래서 원고는 항상 글자가 힘차게 휘날렸고,\n미적인 건 신경 쓰지 않고 한 획에 이어 쓰는 필체였어요.",
  ui_story_5071_50711301_62_dialog_content = "근데 그 마지막 원고는 한 글자 한 글자 꼼꼼하게, 꾹꾹 눌러 적으셨더라구요.\n필체가 주는 전체적인 「인상」이 전혀 달랐어요.",
  ui_story_5071_50711301_63_dialog_content = "뭐랄까... 「매너리즘」이 잔뜩 느껴졌죠.",
  ui_story_5071_50711301_64_dialog_content = "게다가 원고에서 은은하게 향기도 났는데...",
  ui_story_5071_50711301_65_dialog_content = "...그건 위작 작가 A의 특징이에요.",
  ui_story_5071_50711301_66_dialog_content = "향기...",
  ui_story_5071_50711301_67_dialog_content = "그래! <color=#FFB400>백합</color> 향이었어!",
  ui_story_5071_50711301_68_dialog_content = "「전 여사님 작품 속 머큐리 부인이 정말 좋아요.\n신비롭고, 강인하고, 그 무엇에도 구애받지 않죠.」",
  ui_story_5071_50711301_69_dialog_content = "「그 침묵의 감시자를 보면서 저도 백합을 좋아하게 됐던 거예요.」",
  ui_story_5071_50711301_70_dialog_content = "「영원히 사라지지 않는 기억, 위대한 사랑, 진심 어린 축복... 그게 백합의 꽃말이었죠?」",
  ui_story_5071_50711301_71_dialog_content = "「한스티」 씨...",
  ui_story_5071_50711301_72_dialog_content = "<color=#e8d9bb>한스티는 빙긋 미소만 지을 뿐, 아무런 긍정도, 부정도 하지 않았다.</color>",
  ui_story_5071_50711301_73_dialog_content = "<color=#e8d9bb>진상은 이미 검게 물든 뒤였다.\n그 글을 적은 것이 이본인지, 한스티인지는 더는 중요하지 않았다.</color>",
  ui_story_5071_50711301_74_dialog_content = "사람은 저마다 다른 얼굴을 갖고 있어.\n내가 위작 작가 A인지 아닌지는 결과에 아무런 영향도 주지 않아.",
  ui_story_5071_50711301_75_dialog_content = "으... 왜 그런 짓을 한 거죠...? 진짜로... 쭉 동경해 왔는데...",
  ui_story_5071_50711301_76_dialog_content = "그러고 보니 이본 여사님이 어떤 「화가 친구」한테서 영감을 받았단 얘길 했었죠.",
  ui_story_5071_50711301_77_dialog_content = "아무래도 그 친구라는 게 당신이었던 모양이네요.",
  ui_story_5071_50711301_78_dialog_content = "지나간 일 때문에 그렇게나 애써 뛰어다니고, 당신도 참 뭐든 직접 다 한다고 고생이 많네요.",
  ui_story_5071_50711301_79_dialog_content = "당신 복수에 말려든 사람으로서, 전 당신이 비공정을 비롯해서 제가 입은\n이 막대한 손실을 배상할 의향이 있는지 궁금하네요.",
  ui_story_5071_50711301_80_dialog_content = "그런 「훔친 꿈」 따윈 이렇게 망가지는 게 당연하잖아요.",
  ui_story_5071_50711301_81_dialog_content = "한스티 씨, 이건 명실상부한 진짜 제 꿈이에요.",
  ui_story_5071_50711301_82_dialog_content = "당신이 멋대로 꾸며낸 얘기와는 다르다고요.",
  ui_story_5071_50711301_83_dialog_content = "우리 어머니의 마지막에 대한 부분부터 당신 멋대로 불필요한 창작 욕구를 발휘한 거죠?",
  ui_story_5071_50711301_84_dialog_content = "사실일 수도...",
  ui_story_5071_50711301_85_dialog_content = "소문에 불과할 수도 있겠죠.",
  ui_story_5071_50711301_86_dialog_content = "아무 근거도 없었으면 그런 뜬소문이 퍼지지도 않았겠지만요.",
  ui_story_5071_50711301_87_dialog_content = "뭐, 전 멜리사 부인의 「진상」엔 관심도 없고, 어찌 되든 신경 쓸 생각도 없어요.\n그냥 제게 이용만 당해 주면 되니까요.",
  ui_story_5071_50711301_88_dialog_content = "자, 그럼 이제 당신들도 마침내 「케이드의 본모습」을 알아볼 수 있겠죠.",
  ui_story_5071_50711301_89_dialog_content = "아니야...",
  ui_story_5071_50711301_90_dialog_content = "당신 얘기는... 틀렸어!",
  ui_story_5071_50711301_91_dialog_content = "애송아, 네가 뭘 안다고 그러는 걸까?",
  ui_story_5071_50711301_92_dialog_content = "말끝마다 그때의 진상을 보여 주겠다면서, 왜 다른 사람의 과거는 보고도 모른 척해?",
  ui_story_5071_50711301_93_dialog_content = "어머니에 대한 일을 알아내는 게 샤엘 씨한테 얼마나 중요한 일인데...",
  ui_story_5071_50711301_94_dialog_content = "그걸 도구 취급하면서, 아무 검증도 없이 남의 마음을 해치는 데 쓰다니...",
  ui_story_5071_50711301_95_dialog_content = "그런 제멋대로인 사람이 어디 있어!",
  ui_story_5071_50711301_96_dialog_content = "PlayerName...",
  ui_story_5071_50711301_97_dialog_content = "적당히 해!",
  ui_story_5071_50711301_98_dialog_content = "당신은 위작 제작으로 생계를 유지해 왔지만, 작품에 자기 표식을 남기는 건 참지 못했어.",
  ui_story_5071_50711301_99_dialog_content = "입으로는 복수를 말하지만 수단은 더 비열하고 잔인했고...",
  ui_story_5071_50711301_100_dialog_content = "이스타반 씨의 과거를 폭로하겠다면서, 정작 당신이 한 짓 중에선 그 어떤 「진실」도 없잖아?",
  ui_story_5071_50711301_101_dialog_content = "당신처럼 거만하고 자기밖에 모르는 사람이 이스타반 씨를 부정하는 것도,\n결국엔 다 자기 사욕 때문인 거 아냐?",
  ui_story_5071_50711301_102_dialog_content = "내가 적당히 하라고 했지? 이 빌어먹을 애송이가!",
  ui_story_5071_50711301_103_dialog_content = "어머, 그래서야 너무 품위가 없지 않나요? 한스티 씨.",
  ui_story_5071_50711301_104_dialog_content = "봐요, 당신 때문에 우리 버질이 깜짝 놀랐잖아요.",
  ui_story_5071_50711301_105_dialog_content = "이본 선생님은 독 때문에 목숨을 잃었어.",
  ui_story_5071_50711301_106_dialog_content = "그리고 난 전에 비슷한 독을 본 적이 있어...",
  ui_story_5071_50711301_107_dialog_content = "그만, 그만해! 더는 못 들어 주겠으니까.",
  ui_story_5071_50711301_108_dialog_content = "아직도 잘못을 깨닫지 못하고 미련하게 틀린 길을 선택하는구나.",
  ui_story_5071_50711301_109_dialog_content = "어쩔 수 없네...\n「배런」이 잠든 이 땅에 「케이드」의 졸개 몇 마리도 함께 보내주는 수밖에.",
  ui_story_5071_50711301_110_dialog_content = "다들 나와!",
  ui_story_5071_50711301_111_dialog_content = "이제 내숭은 그만두기로 했나 봐요?",
  ui_story_5071_50711301_112_dialog_content = "저희 포위당한 거죠...?",
  ui_story_5071_50711301_113_dialog_content = "달링, 이제 네가 제일 잘하는 걸 보여 줄 때가 된 것 같아.",
  ui_story_5071_50711301_114_dialog_content = "이제까진 항상 네가 다른 사람들을 지휘하는 걸 보기만 했는데,\n오늘은 나도 네 지휘를 경험하게 해 줘.",
  ui_story_5071_50711301_115_dialog_content = "버질을 데리고 내 뒤에 서 있어!",
  ui_story_5071_50711301_116_dialog_content = "가장 중요한 손님과 직원을 잃을 순 없으니까!",
  ui_story_5071_50711302_1_dialog_content = "인원이 계속 늘어나고 있어. 상황이 안 좋아.",
  ui_story_5071_50711302_2_dialog_content = "달링, 아무리 네 지원이 있다지만, 이대로는 곤란해.",
  ui_story_5071_50711302_3_dialog_content = "이 정도 소동이 벌어진 이상, 베델 쪽도 이미 알았을 거예요. 분명히 와줄 거예요...",
  ui_story_5071_50711302_4_dialog_content = "문제는 우리가 그때까지 못 버틸지도 모른다는 거야.",
  ui_story_5071_50711302_5_dialog_content = "난 상인이야. 힘쓰는 일은 나한테 안 맞아. 뭐, 그래도 어쩔 수 없네...",
  ui_story_5071_50711302_6_dialog_content = "PlayerName, 버질. 너흰 섀도우마스터를 찾으러 가. 여긴 나한테 맡기고.",
  ui_story_5071_50711302_7_dialog_content = "하지만...!",
  ui_story_5071_50711302_8_dialog_content = "난 섀도우마스터를 믿어!\n내가 지금까지 사업을 해 오면서, 그 사람만큼 약속을 잘 지키는 사람은 본 적 없으니까.",
  ui_story_5071_50711302_9_dialog_content = "그러니까 PlayerName 너도 섀도우마스터를 믿어 줘. 그리고 너 자신도.",
  ui_story_5071_50711302_10_dialog_content = "지금 이런 곳에서 섀도우마스터를 찾아낼 수 있는 건 너뿐이야, 포기하지 마!",
  ui_story_5071_50711302_11_dialog_content = "...알겠어요.",
  ui_story_5071_50711302_12_dialog_content = "가자, 버질.",
  ui_story_5071_50711302_13_dialog_content = "가게 내버려둘 것 같아?",
  ui_story_5071_50711302_14_dialog_content = "한스티 씨, 뭘 그렇게 서둘러요? 우리 쪽 계산도 아직 안 끝났잖아요.",
  ui_story_5071_50711302_15_dialog_content = "남의 어머니 이야기를 자기 멋대로 지어내다니, 너무 천박하지 않나요?",
  ui_story_5071_50711302_16_dialog_content = "역시 「레드 머큐리」의 딸답네요. 본성도 그 사람과 똑같고 말이죠.",
  ui_story_5071_50711302_17_dialog_content = "전 「레드 머큐리」를 정말 좋아했어요. 하지만 당신은 처음부터 마음에 안 들었죠.",
  ui_story_5071_50711302_18_dialog_content = "제가 뭐 잘못이라도 했나요? 혹시 제 사과가 필요한가요?",
  ui_story_5071_50711302_19_dialog_content = "정말 사리 분별도 못 하는군요.",
  ui_story_5071_50711302_20_dialog_content = "사업은 그럭저럭 운영해도, 안목은 형편없잖아요.",
  ui_story_5071_50711302_21_dialog_content = "저번부터 참 열심히도 제 일을 망치고 있고 말이에요.",
  ui_story_5071_50711302_22_dialog_content = "「저번」이라뇨? 그렇게 말씀하시면 그게 언제 얘기인지 제가 또 되물어야 하잖아요.",
  ui_story_5071_50711302_23_dialog_content = "...모두 사소한 일들이었어요. 하지만 당신은 기어코 뻔뻔하게 남의 꿈을 훔쳤죠.",
  ui_story_5071_50711302_24_dialog_content = "「배런」의 꿈을 이어받을 사람은 오직 저뿐이에요!",
  ui_story_5071_50711302_25_dialog_content = "당신에겐 어울리지 않는다고요!",
  ui_story_5071_50711302_26_dialog_content = "PlayerName 말이 맞았네요.\n상회의 수장이라는 사람이 어린애보다도 더 이기적이잖아요.",
  ui_story_5071_50711302_27_dialog_content = "당신이나 「케이드」나 똑같아... 당신 어머니 체면을 생각해서 봐주는 것도 이젠 끝이야.",
  ui_story_5071_50711302_28_dialog_content = "비열한 인간들. 내가 당신, 「케이드」, 그리고 당신 그 「공중상회」까지...\n모조리 없애 주겠어...",
  ui_story_5071_50711302_29_dialog_content = "전부 이 <color=#FFB400>「대륙」</color>에서 부서져 버려!",
  ui_story_5071_50711302_30_dialog_content = "좋아요... 이제 당신한테 욕도 먹었겠다, 나도 이미지 좀 망가져 볼까?\n그래도 별 타격은 없겠지만, 안 그래?",
  ui_story_5071_50711302_31_dialog_content = "(이스타반 씨, 이스타반 씨... 진짜 아직 살아 계신 거 맞나요? 대체 어디 계세요?)",
  ui_story_5071_50711302_32_dialog_content = "(아니면 설마... 샤엘 씨가 우릴 먼저 도망치게 하려고...?)",
  ui_story_5071_50711302_33_dialog_content = "(아무튼 얼른 대답 좀 해 주세요... 더 늦었다간...)",
  ui_story_5071_50711302_34_dialog_content = "형아... 콜록, 콜록콜록... 연기 때문에 숨 막혀...",
  ui_story_5071_50711302_35_dialog_content = "미안해, 버질... 난 계속 이스타반 씨를 찾아볼 테니까,\n넌 빨리 움브라톤에 돌아가서 도움을 요청해.",
  ui_story_5071_50711302_36_dialog_content = "안 돼, 샤엘 사장님이 우리 둘이 같이 찾아보라고 하셨잖아.",
  ui_story_5071_50711302_37_dialog_content = "사장님이 섀도우마스터는 약속을 꼭 지키는 사람이라고 하셨어.\n그러니까 나도 섀도우마스터를 믿을 거야!",
  ui_story_5071_50711302_38_dialog_content = "버질... 어라?!",
  ui_story_5071_50711302_39_dialog_content = "(...엄청나게 복잡한 감정이야. 화염 속에서 느껴지는 것 같은데...?)",
  ui_story_5071_50711302_40_dialog_content = "버질, 이 불길을 지나가야 돼! 따라 와!",
  ui_story_5071_50711302_41_dialog_content = "으앗, 뜨거워... 같이 가!",
  ui_story_5071_50711302_42_dialog_content = "(이스타반 씨... 맞다면 대답 좀 해 주세요...!)",
  ui_story_5071_50711302_43_dialog_content = "섀도우마스터... 섀도우마스터!",
  ui_story_5071_50711302_44_dialog_content = "이스타반 씨──!",
  ui_story_5071_50711302_45_dialog_content = "PlayerName?",
  ui_story_5071_50711302_46_dialog_content = "이스타반 씨! 정말 살아... 어?!",
  ui_story_5071_50711302_47_dialog_content = "뒤에 적이 있어요!",
  ui_story_5071_50711302_48_dialog_content = "아니.",
  ui_story_5071_50711302_49_dialog_content = "걱정 마라, 이미 다 쓰러졌으니.",
  ui_story_5071_50711302_50_dialog_content = "끈질긴 녀석들이네요. 다들 미리 아래에서 기다리고 있던 건가요?",
  ui_story_5071_50711302_51_dialog_content = "녀석들이 우리보다 먼저 섀도우마스터를 발견했어요.",
  ui_story_5071_50711302_52_dialog_content = "한스티 그 사람... 정말 무서울 정도로 집착이 심한 사람이네요.",
  ui_story_5071_50711302_53_dialog_content = "멋대로 하게 둬라...",
  ui_story_5071_50711302_54_dialog_content = "이스타반 씨?",
  ui_story_5071_50711302_55_dialog_content = "조금... 지친 것 같군...",
  ui_story_5071_50711302_56_dialog_content = "어디 다치신 건가요? 많이 괴로워 보여요...",
  ui_story_5071_50711302_57_dialog_content = "콜록, 콜록콜록...",
  ui_story_5071_50711302_58_dialog_content = "얼른 저희랑 같이 나가요. 여긴 연기가 너무 짙어요!",
  ui_story_5071_50711302_59_dialog_content = "연기가 아니다.",
  ui_story_5071_50711302_60_dialog_content = "네? 그럼 이 검은 안개는 뭔데요?",
  ui_story_5071_50711302_61_dialog_content = "(...잠깐만, 검은 안개...? 설마... 그때 그 <color=#FFB400>알트의 독</color>?)",
  ui_story_5071_50711302_62_dialog_content = "하하, 이제야 알아채신 겁니까?",
  ui_story_5071_50711302_63_dialog_content = "네놈들의 숨통을 붙여 둔 건 그 입으로 자백을 듣기 위해서였다.",
  ui_story_5071_50711302_64_dialog_content = "쓸데없는 말은 삼가라.",
  ui_story_5071_50711302_65_dialog_content = "이 안개들은... 한스티 회장님이 당신을 위해 준비한 작은 안부 인사입니다.",
  ui_story_5071_50711302_66_dialog_content = "우리가 당신과 싸우기 시작한 그 순간부터, 이 검은 안개들은 공기 중에 가득했죠.",
  ui_story_5071_50711302_67_dialog_content = "당신이 열심히 싸울수록 더 많은 양을 들이마시도록 말입니다.",
  ui_story_5071_50711302_68_dialog_content = "지금은 전부 불타버려서, 당신이 얼마나 들이마셨는지는 저희도 모르겠군요.",
  ui_story_5071_50711302_69_dialog_content = "빨리 해독제를 내놔!",
  ui_story_5071_50711302_70_dialog_content = "「블랙울프 클랜」은 이미 몰락했을 텐데... 어떻게 아직도 그런 「독」을 가지고 있는 거지?!",
  ui_story_5071_50711302_71_dialog_content = "「독」? 하하하... 뭔가 오해하고 계시는군요.",
  ui_story_5071_50711302_72_dialog_content = "게다가 블랙울프 클랜도 그저 사냥개에 불과한 녀석들이었죠.",
  ui_story_5071_50711302_73_dialog_content = "대체 너흰 놈들이랑 무슨 관계지? 그리고 알트랑 한스티는 대체...",
  ui_story_5071_50711302_74_dialog_content = "됐어, 빨리 해독제나 내놔!",
  ui_story_5071_50711302_75_dialog_content = "긴장할 거 없다, PlayerName... 놈들도 이 「검은 안개」를 들이마셨다.",
  ui_story_5071_50711302_76_dialog_content = "독성이 있었다면 나약한 저들이 나보다 더 빨리 죽었을 것이다.",
  ui_story_5071_50711302_77_dialog_content = "이런 상황에서도 침착하실 수 있다니, 역시 섀도우마스터답군요.",
  ui_story_5071_50711302_78_dialog_content = "이제 네 입으로 계획을 털어놓을 시간이다.",
  ui_story_5071_50711302_79_dialog_content = "기회를 줄 때 지껄여 봐라, 졸렬한 광대.",
  ui_story_5071_50711302_80_dialog_content = "흥, 이건 한스티 회장님의 명령이자, 우리 모두의 바람입니다.",
  ui_story_5071_50711302_81_dialog_content = "이미 느껴지지 않으십니까? 마음속에서 끓어오르는 「흥분」, 아니... 「폭력」 말입니다.",
  ui_story_5071_50711302_82_dialog_content = "그건 개량된 「검은 안개」입니다. 당신을 죽게 만들진 않을 겁니다.\n그저 당신이 점점 더 「흥분」해서 「야성」의 부름에 몸을 맡기게 만들겠죠.",
  ui_story_5071_50711302_83_dialog_content = "보통은 그런 상황에 처하면 마음속의 진정한 자신을 억누르지 못하더군요.",
  ui_story_5071_50711302_84_dialog_content = "설마, 이 자식들...!",
  ui_story_5071_50711302_85_dialog_content = "그렇습니다! 우린... 「이스타반」이란 가면 아래의 아수를 해방시킬 겁니다!",
  ui_story_5071_50711302_86_dialog_content = "<size=50>센트리 폰드의 악마... 케이드를 말입니다!</size>",
  ui_story_5071_50711302_87_dialog_content = "우리가 당신 마음속 깊은 곳의 야수를 해방시켜 드리겠습니다!",
  ui_story_5071_50711302_88_dialog_content = "그래서 당신을 구하러 온 사람들에게, 진짜 당신이 어떤 사람인지 보여 줄 겁니다!",
  ui_story_5071_50711302_89_dialog_content = "당신이 깊이 사랑하는 척하는 사람들 앞에서,\n다시 한번 그 마음속 추악한 광기를 드러내는 겁니다!",
  ui_story_5071_50711302_90_dialog_content = "광기에 휩싸인 건... 오히려 너희들이야!",
  ui_story_5071_50711302_91_dialog_content = "빨리 해독제를... 됐어, 내가 직접 찾겠어...",
  ui_story_5071_50711302_92_dialog_content = "난 오로리안과 강제로 감응할 수 있거든. 만약 너희가 해독제를 갖고 있다면, 분명히...",
  ui_story_5071_50711302_93_dialog_content = "...어?!",
  ui_story_5071_50711302_94_dialog_content = "(이, 이 남자의 「존재」가... 완전히 사라져 버렸잖아?)",
  ui_story_5071_50711302_95_dialog_content = "야! 정신 차려! 이 자식...",
  ui_story_5071_50711302_96_dialog_content = "......",
  ui_story_5071_50711302_97_dialog_content = "애쓰지 마라, PlayerName.",
  ui_story_5071_50711302_98_dialog_content = "놈은 이미 스스로 목숨을 끊었다.",
  ui_story_5071_50711302_99_dialog_content = "이미 모두 그만한 각오를 하고 왔겠지.\n애초부터 살아 돌아갈 생각이 없었으니, 해독제도 가지고 있지 않을 거다.",
  ui_story_5071_50711302_100_dialog_content = "아직 다른 녀석들도 있잖아요! 빨리 막아야 해요...",
  ui_story_5071_50711302_101_dialog_content = "(말도 안 돼... 주변엔 불길이 타오르고 있는데... 여기 생명의 불꽃들은...\n하나둘씩 꺼져 가고 있어...)",
  ui_story_5071_50711302_102_dialog_content = "안 돼! 대체 왜 그렇게까지 하는 거야?! 목숨이...",
  ui_story_5071_50711302_103_dialog_content = "으으으...",
  ui_story_5071_50711302_104_dialog_content = "정말 기쁘군, PlayerName.",
  ui_story_5071_50711302_105_dialog_content = "자네 같은 소년이 적의 생명을 위해 슬퍼할 줄도 알다니.",
  ui_story_5071_50711302_106_dialog_content = "하지만 미안하다. 이곳에 있는 자들은 모두 이미...",
  ui_story_5071_50711302_107_dialog_content = "왜... 어째서 자기 목숨까지 걸어 가면서 저런 짓을 하는 거죠...?",
  ui_story_5071_50711302_108_dialog_content = "자네 마음속에는 이미 그에 대한 답이 있을 텐데.",
  ui_story_5071_50711302_109_dialog_content = "이건...",
  ui_story_5071_50711302_110_dialog_content = "그 당시... 「감비 패밀리」의 증표다...",
  ui_story_5071_50711302_111_dialog_content = "내 손으로 파괴한 패밀리지.",
  ui_story_5071_50711302_112_dialog_content = "이 사람들 모두 비슷한 걸 가지고 있어요.",
  ui_story_5071_50711302_113_dialog_content = "이건 「콜로 패밀리」, 이쪽은 「루체 패밀리」, 그리고 이건 「보나 패밀리」인가...",
  ui_story_5071_50711302_114_dialog_content = "그랬군. 센트리 폰드에서 몰락했던 보스들 모두 그림자를 남겼던 것이다...",
  ui_story_5071_50711302_115_dialog_content = "과거의 그림자는 결국 이 정도까지 잔혹해진 것인가.",
  ui_story_5071_50711302_116_dialog_content = "으윽... 가슴이 불타고 있다...",
  ui_story_5071_50711302_117_dialog_content = "모든 것을 불태우고... 찢어버리고 싶은 충동이 드는군...",
  ui_story_5071_50711302_118_dialog_content = "이스타반 씨, 얼굴이...",
  ui_story_5071_50711302_119_dialog_content = "상태가 안 좋아 보이겠지... 어떤가, 인상이 험악한가?",
  ui_story_5071_50711302_120_dialog_content = "(엄청 사나운 표정이야... 핏줄까지 선명히 보일 정도잖아.\n지금까지 봐 왔던 이스타반 씨랑은 전혀...)",
  ui_story_5071_50711302_121_dialog_content = "우리 가요, 이스타반 씨...",
  ui_story_5071_50711302_122_dialog_content = "해독제가 없더라도, 움브라톤에 돌아가면 분명히...",
  ui_story_5071_50711302_123_dialog_content = "아무튼 일단 여기서 빠져나가고 다시 얘기해요!",
  ui_story_5071_50711302_124_dialog_content = "맞는 말이다만... 으윽...",
  ui_story_5071_50711302_125_dialog_content = "제가 부축할게요! 가요!",
  ui_story_5071_50711302_126_dialog_content = "지금 내 몸속 흉포함은 이곳의 불길보다 더 뜨겁다.",
  ui_story_5071_50711302_127_dialog_content = "이제 곧... 억누를 수 없게 될 거다.",
  ui_story_5071_50711302_128_dialog_content = "결국 이곳이 정말 숙명의 땅이었던 것인가...\n마치 내 과거가 이미 날 쫓아 온 것만 같군...",
  ui_story_5071_50711302_129_dialog_content = "그만 가라. 내 신경은 쓰지 말고... 내 손으로 너흴 상처입힐 순 없단 말이다...",
  ui_story_5071_50711302_130_dialog_content = "지금 무슨 말씀을 하시는 거예요?",
  ui_story_5071_50711302_131_dialog_content = "내 말이! 가서 우리 사장님 구해 주셔야죠!",
  ui_story_5071_50711302_132_dialog_content = "나도 가고 싶다만... 으윽...",
  ui_story_5071_50711302_133_dialog_content = "놈들 말이 사실이었군. 뭐든지 파괴하고 싶은 충동이 지금 날 집어삼키려 한다...",
  ui_story_5071_50711302_134_dialog_content = "어서 가라! 농담이 아니다! 난...",
  ui_story_5071_50711302_135_dialog_content = "안 돼요! 이스타반 씨를 내버려두고 갈 순 없어요! 분명히 방법이 있다구요!",
  ui_story_5071_50711302_136_dialog_content = "내가 가라고 했을 텐데! 내 말이 들리지 않는 거냐?!",
  ui_story_5071_50711302_137_dialog_content = "내게서 떨어져라!",
  ui_story_5071_50711302_138_dialog_content = "크윽... 이젠 방법이 없다... 내 상태는 누구보다도 내가 잘 안다...",
  ui_story_5071_50711302_139_dialog_content = "아니요...",
  ui_story_5071_50711302_140_dialog_content = "방법은 분명히 있어요.",
  ui_story_5071_50711302_141_dialog_content = "(분명히 있어... 설령...)",
  ui_story_5071_50711302_142_dialog_content = "죄송해요... 절 나무라실 수도 있겠지만, 지금은 역시 이 방법밖에 없네요.",
  ui_story_5071_50711302_143_dialog_content = "PlayerName, 자네...",
  ui_story_5071_50711302_144_dialog_content = "버질, 나랑 이스타반 씨 좀 잘 지켜봐 줘!",
  ui_story_5071_50711302_145_option_content = "(강제 감응!)",
  ui_story_5071_50711401_1_dialog_content = "(이게 이스타반 씨의 속마음인가? 감정들이 왜 이렇게 많이 느껴지는 거지?\n엄청 혼란스러워...)",
  ui_story_5071_50711401_2_dialog_content = "기억에 있는 장소군. 여긴...",
  ui_story_5071_50711401_3_dialog_content = "(이스타반 씨 목소리잖아...?)",
  ui_story_5071_50711401_4_dialog_content = "「어둠의 위기」가 찾아왔을 때, 나는 「아버지」, 그리고 임시 연합 상회를 대표해\n백야성의 지원군과 지원 협정을 맺으러 갔었지. 그리고...",
  ui_story_5071_50711401_5_dialog_content = "이스타반 씨, 어디 계세요?",
  ui_story_5071_50711401_6_dialog_content = "이날을... 다시 보게 될 줄이야.",
  ui_story_5071_50711401_7_dialog_content = "(내 목소리가 안 들리는 모양이네... 이 방법으로 이스타반 씨를 못 깨운다면,\n일단은 감정의 「허점」을 찾아보는 수밖에 없겠어.)",
  ui_story_5071_50711401_8_dialog_content = "(근데 이스타반 씨는 대체 어디 있는 거지...)",
  ui_story_5071_50711401_9_dialog_content = "(여긴... 격투장인가?)",
  ui_story_5071_50711401_10_dialog_content = "...이렇게나 많이들 모인 건가?",
  ui_story_5071_50711401_11_dialog_content = "나도 깜짝 놀랐다니까! 이렇게 많은 보스들이 모였던 게 마지막으로 언제였더라?",
  ui_story_5071_50711401_12_dialog_content = "(이 사람들이... 다 암흑가 사람들인 건가?)",
  ui_story_5071_50711401_13_dialog_content = "자, 이렇게 다들 말을 하겠다고 혼자 올 엄두를 낸 이상,\n어디 당신들 의견도 좀 들어 보자고.",
  ui_story_5071_50711401_14_dialog_content = "「이스타반 영감」이 여러 상회와 연합해서 움브라톤을 팔아먹으려 한다고 들었다.\n<color=#FFB400>영감의 양자가 그 증거인 지팡이를 가지고 갈 거라고 하더군.</color>",
  ui_story_5071_50711401_15_dialog_content = "그 지팡이를 손에 넣어서 연합 상회에 물자를 풀라고 명령하고,\n패밀리들을 무장시켜 암귀와 싸우자는 게 내 의견이다.",
  ui_story_5071_50711401_16_dialog_content = "도시 밖의 백야성 「나리」들도 다 영감이랑 상회 쪽에서 불러들인 건가?\n이런 위급한 상황에 완전 무장을 하고 저렇게 있는 걸 보면,\n놈들은 우릴 여기서 다 죽일 생각인 게 분명해!",
  ui_story_5071_50711401_17_dialog_content = "애초에 백야성 놈들이 노리는 건 이참에 움브라톤을 점거하는 거라고!\n차라리 그냥 줘 버리고 우린 여길 떠나자고!",
  ui_story_5071_50711401_18_dialog_content = "여기가 우리 고향인데 어딜 가자는 거냐?!",
  ui_story_5071_50711401_19_dialog_content = "고향 좋아하네. 난 이딴 시궁창을 고향으로 인정할 생각 없어.",
  ui_story_5071_50711401_20_dialog_content = "여긴 「센트리 폰드」다! 여기서 나랑 한판 붙기라도 할 생각이냐?!",
  ui_story_5071_50711401_21_dialog_content = "백야성 놈들이 우리 구역에 들어오는 건 나도 반대다!\n놈들은 암귀가 무서워서 움브라톤을 포기하고 돌아갔었잖아? 왜 다시 돌아온다는 거지?",
  ui_story_5071_50711401_22_dialog_content = "그 잘난 귀족 나리들을 겨우 돌려보냈는데, 또 놈들 군대가 기어들어 온다니,\n이래서야 우리보고 살라는 거야, 말라는 거야?",
  ui_story_5071_50711401_23_dialog_content = "자자, 그만 떠들고 다들 내 말이나 좀 들어 봐. 이참에 다 같이 손잡고 한탕 하는 게 어때?\n도시의 거지 놈들이 우리랑 뭔 상관이야? 그놈들 쥐어짜서 백야성 놈들한테 약이나 치자고!",
  ui_story_5071_50711401_24_dialog_content = "그거 좋지. 기왕 패밀리들이 이렇게 모였는데, 이참에 그냥 상회를 다 먹어 버리자고!",
  ui_story_5071_50711401_25_dialog_content = "헛소리 집어치워! 거기 내 돈줄에 어디 손만 대 봐라!",
  ui_story_5071_50711401_26_dialog_content = "여긴 「센트리 폰드」다. 이렇게 된 이상, 오랜 규칙에 따라 지팡이의 주인을 결정하자고.",
  ui_story_5071_50711401_27_dialog_content = "아직 몇 놈이 지팡이를 호송하는지도 모르는데, 그냥 우리끼리 힘을 합치지 그래?",
  ui_story_5071_50711401_28_dialog_content = "살아남은 놈이 부하들 데리고 가서 지팡이를 차지하면 그만이지. 단순하고 좋잖아.",
  ui_story_5071_50711401_29_dialog_content = "너희들한테는 움브라톤보다 그 지팡이가 훨씬 더 중요한 거냐?",
  ui_story_5071_50711401_30_dialog_content = "「양치기의 지팡이」가 「이스타반 영감」네 패밀리의 상징인 이상, 그거야 당연하지.\n게다가 이젠 연합 상회의 상징이기도 하다고...",
  ui_story_5071_50711401_31_dialog_content = "<size=45>그만 좀 해라!</size>",
  ui_story_5071_50711401_32_dialog_content = "지금 중요한 건 「케이드」 그 망할 놈이 지팡이를 가지고 어디로 튀었냐는 거야.\n여기서 한참을 기다렸는데 코빼기도 안 보이잖아.",
  ui_story_5071_50711401_33_dialog_content = "(이 사람들이 그 시절 움브라톤의 「보스」들이라고? 정말 끔찍하네...)",
  ui_story_5071_50711401_34_dialog_content = "(빨리 이스타반 씨를 찾아야 돼... 조금 더 집중해서 감응해 보자...)",
  ui_story_5071_50711401_35_dialog_content = "듣자하니 「이스타반 영감」 친아들 「배런」도 수완이 꽤 좋다더군.\n벌써 상회를 몇 개나 굴리고 있을 정도니 말이야.",
  ui_story_5071_50711401_36_dialog_content = "우리도 배런 덕에 재미 깨나 보고 있긴 하지.\n그나저나 그 자식은 암귀들의 이번 습격을 어떻게 생각할지 모르겠군.",
  ui_story_5071_50711401_37_dialog_content = "(찾았다! 젊은 이스타반 씨야! 저쪽 모퉁이에 숨어 있었네...)",
  ui_story_5071_50711401_38_dialog_content = "(어? 이스타반 씨 앞에 있는 사람은... 누구지...?)",
  ui_story_5071_50711401_39_dialog_content = "케이드, 잘 들었겠지?",
  ui_story_5071_50711401_40_dialog_content = "저것들이 바로 네가 구해주려는 움브라톤의 「보스」들이야.",
  ui_story_5071_50711401_41_dialog_content = "배런, 너랑 이러고 있을 시간 없다! 난 가야 해! 이러다간 다 늦고 말 거다!",
  ui_story_5071_50711401_X41_dialog_content = "(저 사람이 그 「배런」?! 근데... 왜 이스타반 씨 기억 속 배런 씨 모습은 저렇게 흐릿한 거지?)",
  ui_story_5071_50711401_42_dialog_content = "그 젊은 성주와 이미 이야기가 끝났어. 우리가 이번 위기를 넘길 수 있게 그가 도와줄 거라고!",
  ui_story_5071_50711401_43_dialog_content = "지원군은 이미 도시 밖에 도착했고, 아직 어떤 움직임도 보이지 않고 있어.\n그것만 해도 이미 충분히 우릴 존중해 주고 있는 거라고...",
  ui_story_5071_50711401_44_dialog_content = "내가 가서 협정에 서명만 하면 저들은 우리와 함께 싸워줄 거다.\n그럼 암귀 군단을 막아낼 수 있어!",
  ui_story_5071_50711401_45_dialog_content = "네가 지금 이대로 나갔다간 저 보스들을 전부 상대해야 할 거다.\n일단 나랑 얘기부터 좀 하자고. 여기서 나갈 방법은 내가 찾아줄 테니까.",
  ui_story_5071_50711401_46_dialog_content = "걱정할 거 없어. 여긴 잘 숨겨진 곳이고, 우리 대화는 저들에게 들리지 않아.",
  ui_story_5071_50711401_47_dialog_content = "...케이드, 그래서 그 협정 체결의 대가가 뭐냐.\n아버지와 넌 백야성에 뭘 팔아넘길 생각이냔 말이다.",
  ui_story_5071_50711401_48_dialog_content = "움브라톤의 주민들? 자유로운 거래? 아니면 더 많은 세금?\n놈들은 이미 움브라톤을 버렸어. 다시 돌아와 봤자 전보다 더 가혹해질 뿐이야!",
  ui_story_5071_50711401_49_dialog_content = "왜 움브라톤을 팔아서 백야성에 굽신거리려는 거냔 말이다! 우리의 이상을 저버릴 생각이냐?",
  ui_story_5071_50711401_50_dialog_content = "이건 「아버지」는 물론이고, 연합 상회에서도 동의한 사안이다.\n이 지팡이와 내가 갖고 있는 연판장이 그 증거다.",
  ui_story_5071_50711401_51_dialog_content = "이건 모두의 공통된 의견이다.",
  ui_story_5071_50711401_52_dialog_content = "움브라톤의 하층민들, 백야성과 여러 상회에 착취당하던 그들의 의견은 물은 적 있나?",
  ui_story_5071_50711401_53_dialog_content = "정보에 따르면 암귀들은 하루만 더 있으면 여기 도착할 거다.\n하지만 움브라톤의 모든 세력은 저마다 속셈이 다르지.",
  ui_story_5071_50711401_54_dialog_content = "아버지와 상회는 자기들 보신을 위해 백야성과 결탁했었다는 사실을 뒤늦게 털어놨고,\n「감비 패밀리」와 놈의 동맹은 움브라톤 탈출 티켓을 고액에 팔기 시작했다...",
  ui_story_5071_50711401_55_dialog_content = "저 빈곤한 이들은 싸울 능력도 없고, 이곳을 떠날 수조차 없다.\n결국 저들은 죽음만 기다리는 수밖에 없단 말이다...",
  ui_story_5071_50711401_56_dialog_content = "우리가 함께 이곳을 지킬 거다!",
  ui_story_5071_50711401_57_dialog_content = "그건 너희 바람일 뿐이고, 대부분 그저 여길 떠나고 싶어 하지.\n게다가 움브라톤을 탈출하는 사람들만 노려 강도질을 하는 갱단들까지 있다더군.",
  ui_story_5071_50711401_58_dialog_content = "힘 있는 자들은 하나같이 거리의 약자를 외면하고 있다...\n우리의 움브라톤은 어째서 이런 곳이냔 말이다...",
  ui_story_5071_50711401_59_dialog_content = "그나마 다행인 건 적어도 저 암흑가 놈들에겐 가장 순수한 움브라톤의 피가 흐른다는 거겠지.\n조금만 자극해 주면 놈들은 그 핏줄 속에 흐르는 폭력을 기억해 낼 거라고.",
  ui_story_5071_50711401_60_dialog_content = "그래서 난 은연중에 놈들을 부추겼다. 여기 와서 바람이나 좀 쐬라고 말이야.\n약간의 이익을 미끼로 던지면, 그중에 하나라도 저들 입에 맞는 게 있기 마련이거든.",
  ui_story_5071_50711401_61_dialog_content = "너... 대체 뭘 하려는 거냐.",
  ui_story_5071_50711401_62_dialog_content = "케이드, 말했잖아. 난 줄곧 내 세력을 키우기 위해 노력해 왔어.",
  ui_story_5071_50711401_63_dialog_content = "그리고 암귀의 습격을 기회로 삼아 움브라톤의 병폐를 철저히 제거할 거다.",
  ui_story_5071_50711401_64_dialog_content = "저놈들만 없애면 우린 무고한 이들을 데리고 아무 방해 없이 떠날 수 있어.",
  ui_story_5071_50711401_65_dialog_content = "그러니까 네가 지금 할 일은 백야성의 쓰레기들을 찾아가는 게 아니라,\n나와 함께 저 피고름을 제거하는 거다. 그게 진정 움브라톤을 위하는 일이니까.",
  ui_story_5071_50711401_66_dialog_content = "배런... 넌 변했어...",
  ui_story_5071_50711401_67_dialog_content = "넌 저들 사이에 내분을 일으킬 수 있으면서,\n왜 저들이 힘을 합쳐 암귀와 싸우게 만들 생각은 없는 거냐.",
  ui_story_5071_50711401_68_dialog_content = "지금의 네가 움브라톤의 피를 빨던 저 귀족들과 뭐가 다르냔 말이다...",
  ui_story_5071_50711401_69_dialog_content = "저놈들은 움브라톤을 타락시킨 원흉들이야!\n저들을 살려둬 봤자 다른 이들에게 해만 끼칠 뿐이라고!",
  ui_story_5071_50711401_70_dialog_content = "겨우 얻은 기회야, 케이드. 나와 함께 놈들을 없애고, 무고한 이들을 데리고 떠나자...",
  ui_story_5071_50711401_71_dialog_content = "놈들을 완전히 제거해야만 움브라톤의 약자들에게도 떠날 기회가 주어질 거야.",
  ui_story_5071_50711401_72_dialog_content = "...도망쳐 봤자 무슨 의미가 있지?",
  ui_story_5071_50711401_73_dialog_content = "결국 움브라톤은 완전히 백야성의 수중에 떨어지겠지.\n그리고 훗날 이곳에서 살아갈 이들은 우리와 똑같은 일을 겪게 될 거다.",
  ui_story_5071_50711401_74_dialog_content = "나처럼 그림자 속에서 태어나 멸시받는 「악마의 아이」도 계속해서 태어날 테고 말이다.",
  ui_story_5071_50711401_75_dialog_content = "그리고 이 모든 게 계속 되풀이되겠지.",
  ui_story_5071_50711401_76_dialog_content = "백야성과의 협정은 어렵게 이룬 결실이다.\n동등하게 대화할 수 있는 이 기회를 절대 놓쳐선 안 된단 말이다...",
  ui_story_5071_50711401_77_dialog_content = "역시 널 설득할 순 없는 건가...",
  ui_story_5071_50711401_78_dialog_content = "<size=45><color=#FFB400>다들 들어라! 케이드는 여기 있다!</color></size>",
  ui_story_5071_50711401_79_dialog_content = "......",
  ui_story_5071_50711401_80_dialog_content = "배런?! 지금 뭘 하는 거냐...!",
  ui_story_5071_50711401_81_dialog_content = "저 발소리가 들리나? 넌 이제 놈들과 싸울 수밖에 없어.\n그러니까 내가 저 그림자 속 「더러운 피」를 뽑아내는 걸 도와줘.",
  ui_story_5071_50711401_82_dialog_content = "걱정 마. 내가 너와 함께 싸워줄 테니까. 내가 고용한 용병들도 있고 말이야.",
  ui_story_5071_50711401_83_dialog_content = "성급하게 굴지 마! 아직 협상할 수 있으니까! 저놈한테 지팡이를 내놓으라고 해!\n가서 물자를 동원하고 움브라톤을 지키는 거다!",
  ui_story_5071_50711401_84_dialog_content = "으아악! 누, 누구냐...",
  ui_story_5071_50711401_85_dialog_content = "공격이다! 제기랄, 역시 이럴 작정이었어! 협상이고 뭐고 집어치워!",
  ui_story_5071_50711401_86_dialog_content = "일단 저 「악마의 아이」부터 없애! 누가 지팡이를 가질진 그다음에 따지자고!",
  ui_story_5071_50711401_87_dialog_content = "비켜라! 네놈들한테 쓸 시간은 없다!",
  ui_story_5071_50711401_88_dialog_content = "내 먹잇감 뺏을 생각 말라고!",
  ui_story_5071_50711401_89_dialog_content = "비키라고 했을 텐데!",
  ui_story_5071_50711401_90_dialog_content = "케이드, 공격하지 않으면 넌 죽을 거다! 그렇게 되면, 모든 꿈도 물거품이 되겠지!",
  ui_story_5071_50711401_91_dialog_content = "빌어먹을... 내 앞에서 다 꺼지란 말이다!",
  ui_story_5071_50711401_92_dialog_content = "한 치 앞도 내다볼 줄 모르는 놈들, 비켜라!",
  ui_story_5071_50711401_93_dialog_content = "내가 찔렀어! 빨리 제껴버려!",
  ui_story_5071_50711401_94_dialog_content = "크으윽!",
  ui_story_5071_50711401_95_dialog_content = "버러지 같은 놈들... 원하는 게 이거냐? 그럼 덤벼라!",
  ui_story_5071_50711401_96_dialog_content = "안 돼요! 빨리 멈춰요! 이건 아무 의미도 없는 싸움이라고요!",
  ui_story_5071_50711401_97_dialog_content = "모조리 잿더미로 만들어 주마──!",
  ui_story_5071_50711401_98_dialog_content = "(아무도 내 말을 안 듣잖아...)",
  ui_story_5071_50711401_99_dialog_content = "(끔찍해... 이스타반 씨한테 저런 포악한 면이 있었다니...\n저게 바로 이스타반 씨가 폭주했을 때의 모습인가?)",
  ui_story_5071_50711401_100_dialog_content = "(그럼 설마... 저때 실수로 친구의 목숨을 빼앗았던 건가?)",
  ui_story_5071_50711401_101_dialog_content = "(아, 아니겠지... 내가 지금 무슨 생각하는 거야? 아무튼 이스타반 씨의 정신에\n「허점」이 생긴 지금을 노려야 돼!)",
  ui_story_5071_50711401_102_dialog_content = "이스타반 씨! 제 목소리를 듣고 다시 돌아와 주세요──!",
  ui_story_5071_50711402_1_dialog_content = "보스들이 전부...",
  ui_story_5071_50711402_2_dialog_content = "저기 좀 봐! 백야성 군대가 움직이기 시작한 것 같은데? 이쪽으로... 오려는 건가?",
  ui_story_5071_50711402_3_dialog_content = "이제 남은 건 너와 나뿐이다...",
  ui_story_5071_50711402_4_dialog_content = "케이드, 또다시 센트리 폰드를 제패하는 쾌거를 이룬 걸 축하한다.",
  ui_story_5071_50711402_5_dialog_content = "크아아아──!",
  ui_story_5071_50711402_6_dialog_content = "배런! 비켜라... 난 반드시 증표를 가지고 가서 협정을 체결해야만 한다...",
  ui_story_5071_50711402_7_dialog_content = "그토록 많은 일을 당하고도 아직까지 백야성에 환상을 품고 있는 거냐?",
  ui_story_5071_50711402_8_dialog_content = "케이드, 내가 말했던 <color=#FFB400>꿈</color>을 아직 기억하고 있나?",
  ui_story_5071_50711402_9_dialog_content = "기틀은 이미 갖춰졌다. 「양치기의 지팡이」를 가지고 나와 함께 가자.\n우리가 연합 상회를 이끌고 모든 약자들을 거둬줄 수 있다.",
  ui_story_5071_50711402_10_dialog_content = "우린 새로운 가족이 되어 서로를 지켜 주고,\n우리와 같은 처지의 떠돌이들도 지켜줄 수 있을 거다.",
  ui_story_5071_50711402_11_dialog_content = "그리고 이 <color=#FFB400>대륙</color>에서 평등하고 즐겁게 살아가며,\n어디든 갈 수 있고, 그 누구와도 거래할 수 있게 될 거다.",
  ui_story_5071_50711402_12_dialog_content = "(대륙을 여행하는 상회...? 설마 저게 <color=#FFB400>대륙상회</color>의 전신이었던 건가?\n게다가 자유로운 거래란 이념은 <color=#FFB400>공중상회</color>랑 딱 들어맞잖아!)",
  ui_story_5071_50711402_13_dialog_content = "(그럼 샤엘 씨가 갈망하던 꿈은... 배런 씨의 꿈이었던 거였구나.\n저게 한스티 그 사람이 샤엘 씨한테 꿈을 훔쳤다고 한 이유였어!)",
  ui_story_5071_50711402_14_dialog_content = "하지만... 「아버지」는 어쩔 생각이냐.\n떠나길 원치 않는 상회의 일원들은 또 어떡하란 말이냐.",
  ui_story_5071_50711402_15_dialog_content = "발을 잘못 들여 조직원이 된 아이들... 그 아이들도 떠나지 않겠다고 한다면...",
  ui_story_5071_50711402_16_dialog_content = "...아버지와 저들은 그저 자신들의 기반을 아까워하고 있을 뿐이야.\n이곳을 「사랑」해서가 아니라고.",
  ui_story_5071_50711402_17_dialog_content = "일찍이 수많은 이들이 이곳에 모든 걸 빼앗기고 그저 떠날 날만을 기다려 왔다.\n그런 사람들을 이 부패한 움브라톤을 위해서 죽게 만들 생각이냐?",
  ui_story_5071_50711402_18_dialog_content = "넌 거리의 아이들을 보며 눈물을 흘리면서, 왜 저들을 위해 상회에서 일하는\n그 부모와 가족들은 보지 않는 거냐!",
  ui_story_5071_50711402_19_dialog_content = "우리와 터전 사이의 관계는 네가 생각하는 것보다 더 끈끈하다.\n그 누구도 이 관계를 끊어낼 순 없단 말이다.",
  ui_story_5071_50711402_20_dialog_content = "사람은 고향을 사랑할 수도 있고, 미워할 수도 있겠지... 하지만 결코 버릴 수는 없는 거다.",
  ui_story_5071_50711402_21_dialog_content = "난 남겠다... 「아버지」와 함께... 우리 방식대로 이 고향을 지킬 거다.",
  ui_story_5071_50711402_22_dialog_content = "암귀 군단이 코앞까지 다가왔고, 백야성 군대도 점점 목을 조여오고 있어!\n지금 떠나지 않으면 앞으로는 더 큰 혼란에 빠질 뿐이야!",
  ui_story_5071_50711402_23_dialog_content = "여길 계속 지키더라도, 결국엔 죽을 수도 있다고... 백야성의 말은 믿을 수 없으니까!",
  ui_story_5071_50711402_24_dialog_content = "그럼 적어도 우린... 고향을 위해 죽은 거다.",
  ui_story_5071_50711402_25_dialog_content = "예전부터 난 「아버지」와는 이념이 달랐지...",
  ui_story_5071_50711402_26_dialog_content = "그리고 난 너처럼 아버지한테 인정받지도 못했다.\n이제 보니 너야말로 진정한 「이스타반의 아들」일지도 모르겠군.",
  ui_story_5071_50711402_27_dialog_content = "하지만 넌 달라... 내가 꿈을 좇기 시작한 순간부터 넌 날 격려해 줬었지.\n그때부터 난 알고 있었다. 정말로 날 이해해 주는 사람은 너뿐이었던 거다.",
  ui_story_5071_50711402_28_dialog_content = "케이드, 부탁이다. 우리의 꿈을 위해 나와 떠나자...",
  ui_story_5071_50711402_29_dialog_content = "우리의 꿈은 이 땅을 바꾸는 게 아니었나?! 만약 우리마저 이곳을 지키지 않는다면...\n그 꿈은 거짓말이 되어 버리겠지.",
  ui_story_5071_50711402_30_dialog_content = "저들은 이제야 비로소 연합의 의미를 이해하고, 마침내 단결을 이뤄냈다.\n이제 와서 포기할 순 없단 말이다...",
  ui_story_5071_50711402_31_dialog_content = "그건 다 허상이야, 케이드! 놈들이 관심을 두는 건 오직 이익뿐이라고!\n그 이익을 위해 놈들은 앞으로도 계속 내분을 벌일 거다!",
  ui_story_5071_50711402_32_dialog_content = "놈들에 대한 실망감은 나도 이해할 수 있다...\n하지만 그렇다고 구제할 수 없는 놈들은 아냐.",
  ui_story_5071_50711402_33_dialog_content = "선택의 여지가 없었던 이들도 많았으니... 분명히 다시 돌아오는 이들이 있을 거다.\n나 같은 놈조차 빛나는 꿈을 위해 몸을 던졌으니 말이야!",
  ui_story_5071_50711402_34_dialog_content = "우리가 참고 버틴다면... 언젠가는 「씨앗」을 남길 수 있을 거다.",
  ui_story_5071_50711402_35_dialog_content = "설령 우리가 아니더라도, 먼 훗날 누군가는 우리의 꿈을 이루어 줄 거다.",
  ui_story_5071_50711402_36_dialog_content = "케이드... 넌 언제나 눈앞의 상황을 두고 발버둥 쳤지.\n체스를 둘 때도 오로지 진격을 위해 무모하게 위험을 무릅썼다.",
  ui_story_5071_50711402_37_dialog_content = "악을 처단하는 일도 그저 당장 눈앞에 보이는 것들을 파괴할 뿐이던 네가...\n대체 언제... 그렇게 멀리 보게 된 거냐.",
  ui_story_5071_50711402_38_dialog_content = "미래의 움브라톤은 스스로 서게 될 거다. 하지만 그게 친구를 만들어선 안 된다는 뜻은 아니잖나.\n우린 백야성과 협력해야 한다... 고군분투는 올바른 답이 아니다.",
  ui_story_5071_50711402_39_dialog_content = "내게 친구의 의미를 알게 해 준 것도 배런 너였지...\n그런데 왜 지금은 그렇게 변해버린 거냐.",
  ui_story_5071_50711402_40_dialog_content = "백야성은 움브라톤이란 심연을 만들어 낸 장본인이다...\n저들의 오만한 빛이 드리운 그림자는 우리의 삶을 평생 옭아맬 거다.",
  ui_story_5071_50711402_41_dialog_content = "네가 부럽군... 그토록 쉽게 원한을 내려놓고, 응어리 없이 나아갈 수 있다니 말이야.",
  ui_story_5071_50711402_42_dialog_content = "하지만 난 저들을 용서할 수 없고, 「오점」과도 타협할 수 없었다.\n부당함을 보고도 못 본 척할 수 없었단 말이다.",
  ui_story_5071_50711402_43_dialog_content = "난... 내 곁의 사람들을 지키려는 것만으로도 온 힘을 다 써야만 했어.",
  ui_story_5071_50711402_44_dialog_content = "배런...",
  ui_story_5071_50711402_45_dialog_content = "케이드, 넌 체스로는 단 한 번도 날 이긴 적이 없었지.\n그런 네가 백야성 놈들과 도박을 할 수 있을 거라 생각하나?",
  ui_story_5071_50711402_46_dialog_content = "놈들이 가장 잘하는 게 바로 속임수란 말이다!",
  ui_story_5071_50711402_47_dialog_content = "케이드, 내가 널 구해 주마. 「양치기의 지팡이」를 내게 넘기고, 함께 떠나자...",
  ui_story_5071_50711402_48_dialog_content = "...거절하겠다.",
  ui_story_5071_50711402_49_dialog_content = "넌 정말 이게 우리의 결말이길 바라는 거냐?\n이 센트리 폰드에서... 기어코 우리가 마지막 승부를 겨뤄야 하는 거냔 말이다...",
  ui_story_5071_50711402_50_dialog_content = "우리가 서로 칼끝을 겨눌 날이 올 줄은 단 한 번도 생각해 본 적 없었다.\n하지만... 난...",
  ui_story_5071_50711402_51_dialog_content = "여기서 대체 무슨 일이 벌어진 거지? 케이드 씨는 어디 계신 거냐!",
  ui_story_5071_50711402_52_dialog_content = "?!",
  ui_story_5071_50711402_53_dialog_content = "어이! 안에는 못 들어간다!",
  ui_story_5071_50711402_54_dialog_content = "네놈들한테 허비할 시간 없다. 케이드 씨가 어디 계시는지 말해라.",
  ui_story_5071_50711402_55_dialog_content = "백야성 놈들... 감히 우리 터전에 군대를 이끌고 발을 들이다니!",
  ui_story_5071_50711402_56_dialog_content = "놈들을 쫓아내!",
  ui_story_5071_50711402_57_dialog_content = "이 움브라톤 시궁창의 쓰레기 놈들! 함부로 설치지 않는 게 좋을 거다!",
  ui_story_5071_50711402_58_dialog_content = "놈들을 제압하고 케이드 씨를 찾아라. 그 사람이 이런 놈들 손에 죽게 만들어선 안 된다!",
  ui_story_5071_50711402_59_dialog_content = "이 망할 놈들...! 크억...",
  ui_story_5071_50711402_60_dialog_content = "당신이 케이드 씨겠군요! 약속 시간이 한참 지났는데 오질 않아서...",
  ui_story_5071_50711402_61_dialog_content = "케이드! 그게 네 「다음 행마」였던 거냐?!",
  ui_story_5071_50711402_62_dialog_content = "그런 비열한 짓을 하다니... 완전히 타락했구나!",
  ui_story_5071_50711402_63_dialog_content = "물러서라! 너흰 움브라톤 영내에 들어올 수 없다!",
  ui_story_5071_50711402_64_dialog_content = "케이드 씨, 아무래도 약속에 대해 뭔가 착오가 있는 모양입니다만,\n지금 가장 중요한 건 협정입니다!",
  ui_story_5071_50711402_65_dialog_content = "물러서라고 했을 텐데!",
  ui_story_5071_50711402_66_dialog_content = "벌써 움브라톤을 놈들에게 팔아넘겼던 거냐?! 케이드! 대답해 보란 말이다!",
  ui_story_5071_50711402_67_dialog_content = "움브라톤 놈! 말조심해라!",
  ui_story_5071_50711402_68_dialog_content = "우리 고향을 더럽히게 둘 것 같으냐!",
  ui_story_5071_50711402_69_dialog_content = "멈춰라! 배런! 어서 무기를 내려놔!",
  ui_story_5071_50711402_70_dialog_content = "후퇴! 후퇴하라! 쳇, 저놈 루미나틱스가... 크헉!",
  ui_story_5071_50711402_71_dialog_content = "대장님이 부상을 입으셨다! 반격해라! 어서!",
  ui_story_5071_50711402_72_dialog_content = "오만한 네놈들이 이 땅에 멋대로 발을 들이게 두지 않겠다! 전부...",
  ui_story_5071_50711402_73_dialog_content = "(안 돼! 백야성 병사들이 닥치는 대로 공격하고 있어! 빨리 막아야 해!)",
  ui_story_5071_50711402_74_dialog_content = "(이런... 내 의식으론 저 사람들을 전혀 막을 수가 없어...!)",
  ui_story_5071_50711402_75_dialog_content = "<color=#e8d9bb>탕──</color>",
  ui_story_5071_50711402_76_dialog_content = "이, 이놈들... 케이드...!",
  ui_story_5071_50711402_77_dialog_content = "<size=40>배런──!</size>",
  ui_story_5071_50711402_78_dialog_content = "<size=50>크아아아아──!</size>",
  ui_story_5071_50711402_79_dialog_content = "꺼져라! 내 앞에서 전부 꺼지란 말이다!",
  ui_story_5071_50711402_80_dialog_content = "후퇴해라! 저놈은 지금 제정신이 아냐! 협정이고 뭐고 일단 후퇴해!",
  ui_story_5071_50711402_81_dialog_content = "후퇴해라! 빨리──!",
  ui_story_5071_50711402_82_dialog_content = "배런... 너...",
  ui_story_5071_50711402_83_dialog_content = "케이드... 아무래도 움브라톤에선... 일이 늘 최악으로 향하는 모양이다...\n이제 우린... 어떻게 해야 이 땅을... 구원할 수 있지...?",
  ui_story_5071_50711402_84_dialog_content = "백야성의 그림자가... 다시 드리워졌다...\n불길을 멈춘다면... 움브라톤은 「정화」될 수 없어...",
  ui_story_5071_50711402_85_dialog_content = "부당함에 시달려 온 저들을... 이제 누가 구해줄 수 있냔 말이다...",
  ui_story_5071_50711402_86_dialog_content = "구할 거다! 배런, 구할 수 있다고! 조금만 더 시간을 준다면...\n우리가 같이 이번 위기만 넘긴다면... 반드시...!",
  ui_story_5071_50711402_87_dialog_content = "네 꿈은 실현될 거다... 이 땅은 활력이 충만한 곳으로 변할 거다!",
  ui_story_5071_50711402_88_dialog_content = "하하... 정말 굳게 믿고 있군... 그럼 됐다...",
  ui_story_5071_50711402_89_dialog_content = "내가 뭘 했는지... 아버지한테는 말하지 마라...\n면목 없는 건 아니지만... 상심하시게 만들고 싶진 않아...",
  ui_story_5071_50711402_90_dialog_content = "...약속하지.",
  ui_story_5071_50711402_91_dialog_content = "가까이 와라, 케이드... 아직 할 말이 남았어...",
  ui_story_5071_50711402_92_dialog_content = "쿨럭, 쿨럭... 우린 결국 뼛속까지 움브라톤 사람이라...\n내면의 폭력을 떨쳐 버릴 수 없어...",
  ui_story_5071_50711402_93_dialog_content = "넌 이미 일을 벌였고... 난 막을 수 없어... 그럼 적어도 하나만 약속해라...",
  ui_story_5071_50711402_94_dialog_content = "이제 그 어떤 수단과 방법도... 가리지 말고... 움브라톤을 살리는 거다...",
  ui_story_5071_50711402_95_dialog_content = "...약속하지.",
  ui_story_5071_50711402_96_dialog_content = "형제여.",
  ui_story_5071_50711402_97_dialog_content = "......",
  ui_story_5071_50711402_98_dialog_content = "아니야... 아니었어... 결국 이스타반 씨가 그런 게 아니었잖아요? 이스타반 씨...",
  ui_story_5071_50711402_99_dialog_content = "...저들은 소동이 벌어진 것을 보고 협정 체결에 문제가 생기지 않도록\n움브라톤에 발을 들였을 뿐이었다.",
  ui_story_5071_50711402_100_dialog_content = "그러나 오만한 저들은 우릴 존중하는 법을 모르는 듯했고, 우리도 다소 예민하게 반응했지.\n결국 대가를 치르고 나서야 우린 조금씩 협력하는 법을 배울 수 있었다.",
  ui_story_5071_50711402_101_dialog_content = "하지만 그렇다고 해서 내가 저지른 죄가 씻기는 것은 아니다.",
  ui_story_5071_50711402_102_dialog_content = "어떤 현자가 이런 말을 했었지... 「말에는 영혼까지 닿는 힘이 있다」고 말이야. 그래서...",
  ui_story_5071_50711402_103_dialog_content = "나는 배런이 남긴 말에서 벗어날 수 없었다.",
  ui_story_5071_50711501_1_dialog_content = "나는 백야성과의 동맹 관계를 지키기 위해, 누구에게도 배런의 죽음에 대해 해명하지 않았다.\n어차피 그건 확실히 내 잘못이었으니 말이야.",
  ui_story_5071_50711501_2_dialog_content = "그치만 진상은 그게 아니었잖아요...",
  ui_story_5071_50711501_3_dialog_content = "「이스타반의 아들」이 되었을 때, 나는 결코 가족을 해치지 않고,\n가문의 이익을 침해하지 않겠다고 맹세했다...",
  ui_story_5071_50711501_4_dialog_content = "하지만 결국 그 모든 맹세를 저버렸지.\n그 무슨 이유를 대더라도 내겐 「아버지」를 다시 뵐 자격이 없었다.",
  ui_story_5071_50711501_5_dialog_content = "그러나 「아버지」는 임종을 앞두고 변함없이 내게 모든 것을 맡기셨다.\n그렇게 나는 「이스타반」이 되었던 것이다.",
  ui_story_5071_50711501_6_dialog_content = "이스타반 씨...",
  ui_story_5071_50711501_7_dialog_content = "그리고 나는 그림자가 되기로 결심했다.",
  ui_story_5071_50711501_8_dialog_content = "어둠에 숨어, 온갖 형태로 변화하며, 수단과 방법을 가리지 않고 움브라톤을 살아남게 했다.",
  ui_story_5071_50711501_9_dialog_content = "과거의 진상은 오래전 깊은 곳에 묻었고, 다시는 떠올리지 않았지...\n그러나 죄업은 악몽으로 변해 날 괴롭혀 왔다.",
  ui_story_5071_50711501_10_dialog_content = "생존의 대가로는 공정하다고 할 수 있다.",
  ui_story_5071_50711501_11_dialog_content = "아니요... 그건 전혀 공정하지 않아요.",
  ui_story_5071_50711501_12_dialog_content = "움브라톤의 미래를 위해서라면, 난 모든 것을 희생할 수 있다.\n오랫동안 계속 그리 해 왔고 말이야.",
  ui_story_5071_50711501_13_dialog_content = "나는 모든 것을 짊어질 수 있다. 물론 오만하게 「모든 것」을 희생할 수도 있지.\n배런은... 내가 치렀던 첫 번째 「대가」였다.",
  ui_story_5071_50711501_14_dialog_content = "이스타반 씨는 잘못한 게 없잖아요... 사실 본인도 알고 계신 거죠?\n그런데도 자신에게 벌을 주는 걸 선택하셨죠.",
  ui_story_5071_50711501_15_dialog_content = "...이는 내가 움브라톤을 위해 내린 선택이고, 나는 그 결과를 받아들일 것이다.\n움브라톤을 지킬 수만 있다면, 옳고 그름은 상관없다.",
  ui_story_5071_50711501_16_dialog_content = "그리고 언젠가는 이 어둠 위에 설 수 있는 자가 나타날 거라 믿어왔다.\n그때가 되면, 누군가가 우리의 꿈을 이어받아 주겠지.",
  ui_story_5071_50711501_17_dialog_content = "그리고 지금 이미 그런 희망을 보게 되어 무척 기쁘게 생각한다.",
  ui_story_5071_50711501_18_dialog_content = "진짜로 그렇게 생각하시는 거면 왜 이 기억 속에 갇혀 계신 건데요...?",
  ui_story_5071_50711501_19_dialog_content = "...한밤중에 놀라 잠에서 깰 때면 나도 스스로에게 그런 질문을 하곤 했지.",
  ui_story_5071_50711501_20_option_content = "양심의 가책 때문인가요?",
  ui_story_5071_50711501_21_dialog_content = "내가 아직도 자신을 탓하고 있다는 뜻인가.",
  ui_story_5071_50711501_22_option_content = "후회 때문인가요?",
  ui_story_5071_50711501_23_dialog_content = "후회라... 내가 후회하고 있다고?",
  ui_story_5071_50711501_24_dialog_content = "전 이스타반 씨가 저 일에 여한이 남아 있어서 그런 거라 생각해요.",
  ui_story_5071_50711501_X24_dialog_content = "그래서 계속... 배런 씨의 모습을 기억해 내실 수 없는 거겠죠.",
  ui_story_5071_50711501_X25_dialog_content = "......",
  ui_story_5071_50711501_25_dialog_content = "정말 단 한 번도 다른 사람한테 그날의 진실을 말하고 싶었던 적이 없으셨나요?",
  ui_story_5071_50711501_26_dialog_content = "진실이란 때로는 칼날처럼 날카롭지.\n설령 표면적인 평화일지라도, 난 그것을 위해 거짓말을 계속할 것이다.",
  ui_story_5071_50711501_27_dialog_content = "후회는 하지 않는다.",
  ui_story_5071_50711501_28_dialog_content = "이미 느끼고 계시잖아요... 지금까지 계속 양심의 가책과 회한 속에서 살아오셨단 걸요.",
  ui_story_5071_50711501_29_dialog_content = "이스타반 씨는 배런 씨와 아버님께 진상을 말하지 못했던 게 후회되셨던 거예요.",
  ui_story_5071_50711501_30_dialog_content = "예리하군. 하지만 지나간 옛 그림자들이다.\n이제 저들과 화해할 기회는 내게 다시는 주어지지 않는다.",
  ui_story_5071_50711501_31_dialog_content = "그래서 자신을... 악몽에 가두는 벌을 주고 계신 거네요...",
  ui_story_5071_50711501_32_dialog_content = "너무나도 오랫동안 그림자를 연기해 오면서, 가끔은 구분이 잘 되질 않더군.\n내가 그림자에 녹아든 것인지, 아니면 그림자가 날 연기하고 있는 것인지 말이야.",
  ui_story_5071_50711501_33_dialog_content = "내가 해온 일들이 정말 충분했는지도...",
  ui_story_5071_50711501_34_dialog_content = "이스타반 씨는 움브라톤을 위해 이미 충분히 많은 걸 해 주셨어요...",
  ui_story_5071_50711501_35_dialog_content = "그때 내가 망설이지 않았더라면, 가장 먼저 배런을 막았더라면,\n일이 이 지경에 이르진 않았겠지.",
  ui_story_5071_50711501_36_dialog_content = "나는 배런을 「대가」로 삼겠다는 생각은 결코 해본 적도 없었다.",
  ui_story_5071_50711501_37_dialog_content = "훗... 이런 생각을 하는 걸 보면, 난 여전히 케이드인 모양이군.\n그러니 지금까지도 여전히 네 용서를 바라고 있는 거겠지. 나의 형제, 내 오랜 친구여...",
  ui_story_5071_50711501_38_dialog_content = "하하...",
  ui_story_5071_50711501_39_dialog_content = "하하, 하하하하──!",
  ui_story_5071_50711501_40_dialog_content = "이스타반 씨?",
  ui_story_5071_50711501_41_dialog_content = "나이를 먹긴 한 모양이야. 젊음의 패기를 잃어버린 건 아닌가 모르겠군...",
  ui_story_5071_50711501_42_dialog_content = "이런 감상에 빠져 있었다니 말이야.",
  ui_story_5071_50711501_43_dialog_content = "이스타반 씨! 드디어 기운을 차리셨네요!",
  ui_story_5071_50711501_44_dialog_content = "부족하다. 아직 부족해!",
  ui_story_5071_50711501_45_dialog_content = "더 많은 불길이 타올라야 한다!",
  ui_story_5071_50711501_46_dialog_content = "(이스타반 씨의 감정이 안정되고 있어... 근데 왠지 뭔가 어렴풋하게...)",
  ui_story_5071_50711501_47_dialog_content = "자네가 아니었다면 잊을 뻔했군.\n과거의 그림자는 내가 같은 전철을 밟지 않도록 일깨워 주기 위해 존재하는 것이다.",
  ui_story_5071_50711501_48_dialog_content = "그러니 더는 망설이고 있을 순 없다!",
  ui_story_5071_50711501_49_dialog_content = "저들이 기어코 내 야성을 깨워야겠다면, 제대로 보여 주도록 하지...\n분노의 불길을 더는 억누르지 않을 테니 말이다!",
  ui_story_5071_50711501_50_dialog_content = "바로 그거예요! 이스타반 씨! 얼른 깨어나세요!",
  ui_story_5071_50711501_51_dialog_content = "(성공한 건가? 내 몸이... 의식이 희미해져 가... 날 밖으로 밀어내고 있어...)",
  ui_story_5071_50711501_52_dialog_content = "이스타반 씨... 전 밖에서 기다리고 있을게요...",
  ui_story_5071_50711501_53_dialog_content = "감사하지, 선량한 아이테르여.",
  ui_story_5071_50711501_54_dialog_content = "그렇다면 나도 이제...",
  ui_story_5071_50711501_55_dialog_content = "케이드.",
  ui_story_5071_50711501_56_dialog_content = "?!",
  ui_story_5071_50711501_57_dialog_content = "정말... 오랜만이군.",
  ui_story_5071_50711501_58_dialog_content = "배런...?",
  ui_story_5071_50711501_59_dialog_content = "케이드... 네가 다시 한번 답해 줬으면 하는 질문이 있다.",
  ui_story_5071_50711501_60_dialog_content = "내 눈을 보면서 한 치의 거짓 없이 대답해 줄 수 있겠나?",
  ui_story_5071_50711501_61_dialog_content = "......",
  ui_story_5071_50711501_62_dialog_content = "움브라톤을 구하기 위해 넌 어떤 대가를 치를 수 있지?",
  ui_story_5071_50711501_63_dialog_content = "...그걸 꼭 말로 해야 하나?",
  ui_story_5071_50711501_64_dialog_content = "모든 것이다! 내 모든 것을 대가로 치르겠다!",
  ui_story_5071_50711501_65_dialog_content = "그거 정말... 케이드 너다운 대답이군...",
  ui_story_5071_50711501_66_dialog_content = "그렇다면 가라, 형제여. 움브라톤의 적에게 네 결심을 보여주는 거다!",
  ui_story_5071_50711501_67_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5071_50711501_68_dialog_content = "하아, 하아... 내가 이렇게까지 오래 버틸 줄은 몰랐는데.",
  ui_story_5071_50711501_69_dialog_content = "비공정은 박살이 났는데, 아직도 「케이드」가 돌아오길 꿈꾸고 있는 거야?",
  ui_story_5071_50711501_70_dialog_content = "돌아올 거야. PlayerName도 말했거든. 섀도우마스터랑 함께 돌아오겠다고.",
  ui_story_5071_50711501_71_dialog_content = "「케이드」의 본질은 거짓이야...\n설령 그 남자가 살아있다고 해도, 돌아와서 당신을 구할 일은 없어.",
  ui_story_5071_50711501_72_dialog_content = "그 남자의 본모습을 보고 나면 당신도 절망하게 될 거야.",
  ui_story_5071_50711501_73_dialog_content = "회장님, 데려왔습니다.",
  ui_story_5071_50711501_74_dialog_content = "아직도 한패가 있었단 말이야?",
  ui_story_5071_50711501_75_dialog_content = "이젠 암귀까지 조종해서 부리는 거야? 이번엔 정말 쉽지 않겠는걸.",
  ui_story_5071_50711501_76_dialog_content = "한꺼번에 공격해! 숨 돌릴 틈도 주지 마!",
  ui_story_5071_50711501_77_dialog_content = "섀도우마스터...",
  ui_story_5071_50711501_78_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5071_50711501_79_dialog_content = "뭐야?",
  ui_story_5071_50711501_80_dialog_content = "갑자기 엄청난 폭발이...",
  ui_story_5071_50711501_81_dialog_content = "자, 잠깐, 저게 뭐지?",
  ui_story_5071_50711501_82_dialog_content = "불길 속에 사람이... 서, 설마...!",
  ui_story_5071_50711501_83_dialog_content = "섀, 섀도우마스터다!",
  ui_story_5071_50711501_84_dialog_content = "온몸의 흉터... 푸른 불꽃... 맞아...",
  ui_story_5071_50711501_85_dialog_content = "<size=45>센트리 폰드의 악마다!</size>",
  ui_story_5071_50711501_86_dialog_content = "안 돼... 놈은 불패의 신화 그 자체야... 놈과 싸우는 건...",
  ui_story_5071_50711501_87_dialog_content = "겁쟁이들! 도망치지 마! 우리가 복수하려던 건 저 녀석이잖아!",
  ui_story_5071_50711501_88_dialog_content = "녀석은 이미 늙었어! 이 많은 사람을 쓰러트릴 순 없다고...",
  ui_story_5071_50711501_89_dialog_content = "이제 와서 도망치겠다고?",
  ui_story_5071_50711501_90_dialog_content = "도, 도망치게 놔둘 줄 알고?!",
  ui_story_5071_50711501_91_dialog_content = "섀도우마스터... 많이 늦으셨네요. 역시 나이는 못 속이는 모양이죠?",
  ui_story_5071_50711501_92_dialog_content = "미안하군, 샤엘 회장. 그 말대로다. 지금까지 난 무기력한 가면 속에 갇혀 있었지.",
  ui_story_5071_50711501_93_dialog_content = "아무래도 이제 나의 옛 그림자를 돌려보낼 때가 된 것 같군.",
  ui_story_5071_50711501_94_dialog_content = "「에바」... 한때 내 망설임은 우리에게서 「배런」을 앗아갔지.",
  ui_story_5071_50711501_95_dialog_content = "이제 나는 결코 망설이지 않을 것이다. 설령 그 적이 너라도 말이야.",
  ui_story_5071_50711501_96_dialog_content = "입 닥쳐! 당신은 「배런」이란 이름을 입에 올릴 자격조차 없어!",
  ui_story_5071_50711501_97_dialog_content = "사건이 발생했을 때부터 나는 네가 꾸민 음모라는 것을 알고 있었다.",
  ui_story_5071_50711501_98_dialog_content = "날 찾아와 복수를 하는 것은 좋다. 하지만 죄 없는 사람들을 끌어들이진 않았어야 했다.",
  ui_story_5071_50711501_99_dialog_content = "닥쳐... 닥쳐! 그 입 닥치라고! 내가 겪은 고통을 알지도 못하면서!",
  ui_story_5071_50711501_100_dialog_content = "오늘을 위해 내가 원하지 않는 일을 얼마나 많이 해 왔는지 알아?!",
  ui_story_5071_50711501_101_dialog_content = "돈 때문에 지긋지긋한 위작을 수없이 그렸고...\n당신의 진상을 폭로하려고 역겨운 실험과 연구를 셀 수 없이 해야만 했어...",
  ui_story_5071_50711501_102_dialog_content = "그리고 오직 당신한테 복수하기 위해 이 많은 사람과 힘을 모았어!",
  ui_story_5071_50711501_103_dialog_content = "당신 계획은 실패야! 이스타반 씨의 내면은 아주 담담해!\n이제 당신 뜻대로 이성을 잃을 일은 없어!",
  ui_story_5071_50711501_104_dialog_content = "좋아... 당신이 여전히 자신을 숨길 수 있고, 미쳐버리지도 않는다면...",
  ui_story_5071_50711501_105_dialog_content = "내 손으로 당신을 없애 「배런」의 영혼을 달래겠어!",
  ui_story_5071_50711501_106_dialog_content = "전부 공격해!",
  ui_story_5071_50711501_107_dialog_content = "영혼을 판 쓰레기들뿐이로군. 고작 이런 놈들밖에 모으지 못한 거냐.",
  ui_story_5071_50711501_108_dialog_content = "으아악──!",
  ui_story_5071_50711501_109_dialog_content = "우리를 얕보지 마라, 「에바」!",
  ui_story_5071_50711501_110_dialog_content = "어, 얼른 튀어! 전혀 상대가 안 된다고!",
  ui_story_5071_50711501_111_dialog_content = "지난날의 움브라톤에서 나와 배런이 없앤 어둠은, 네가 본 것보다 더욱 깊었다!",
  ui_story_5071_50711501_112_dialog_content = "괴, 괴물이야...",
  ui_story_5071_50711501_113_dialog_content = "섀도우마스터... 너무 터프하신 거 아니에요?!",
  ui_story_5071_50711501_114_dialog_content = "스스로 「품위」를 찢어버린 이상, 용서를 빌 준비나 해라!",
  ui_story_5071_50711501_115_dialog_content = "어, 어떻게 된 거야? 심하게 다친 거 아니었어? 근데 왜 아직도...",
  ui_story_5071_50711501_116_dialog_content = "공격해! 계속 공격하라고! 분명히 지쳤을 거라고!",
  ui_story_5071_50711501_117_dialog_content = "지쳐? 이제 막 몸이 풀린 참이다!",
  ui_story_5071_50711501_118_dialog_content = "저, 전부 다 타버렸어... 저놈은 늙지도 않는 건가...",
  ui_story_5071_50711501_119_dialog_content = "끄아아악!",
  ui_story_5071_50711501_120_dialog_content = "저게 바로 섀도우마스터가 숨기고 있던 모습이었구나... 혼돈을 불사르는 거대한 불길...",
  ui_story_5071_50711501_121_dialog_content = "이제 만족했나?",
  ui_story_5071_50711501_122_dialog_content = "이게 바로 네가 불러내고 싶었던 야수다. 소원이 이뤄진 걸 축하해 주마!",
  ui_story_5071_50711501_123_dialog_content = "빠, 빨리 그 녀석을 데려와! 어서!",
  ui_story_5071_50711501_124_dialog_content = "돈은 다 줄 테니까! 얼른 「이 녀석」을...!",
  ui_story_5071_50711501_125_dialog_content = "<size=50>「에바」──!</size>",
  ui_story_5071_50711502_1_dialog_content = "다들 봤지?! 저런 암귀도 녀석을 막지 못해...! 이스타반이야말로 진짜 괴물이라고!",
  ui_story_5071_50711502_2_dialog_content = "도망칠 생각인가?",
  ui_story_5071_50711502_3_dialog_content = "가, 가까이 오지 마...!",
  ui_story_5071_50711502_4_dialog_content = "?!",
  ui_story_5071_50711502_5_dialog_content = "배런...",
  ui_story_5071_50711502_6_dialog_content = "녀석을 놓아주길 바라는 거냐.",
  ui_story_5071_50711502_7_dialog_content = "살려 줘...!",
  ui_story_5071_50711502_8_dialog_content = "추하구나, 「에바」!",
  ui_story_5071_50711502_9_dialog_content = "시, 싫어...",
  ui_story_5071_50711502_10_dialog_content = "저항은 포기해라. 멋대로 널 해치진 않을 거다.\n넌 네가 마땅히 받아야 할 심판을 받게 되겠지.",
  ui_story_5071_50711502_11_dialog_content = "배런의 꿈과 우리의 꿈은 내가 계속 이어 나갈 것이다.",
  ui_story_5071_50711502_12_dialog_content = "꿈은 이미... 산산조각 났는걸...",
  ui_story_5071_50711502_13_dialog_content = "유감이군, 「에바」... 네가 이렇게까지 타락할 줄은 몰랐다.",
  ui_story_5071_50711502_14_dialog_content = "넌 배런의...",
  ui_story_5071_50711502_15_dialog_content = "헛수작 집어치워, 당신 동정 따윈 필요 없으니까!",
  ui_story_5071_50711502_16_dialog_content = "네가 이 지경이 되기까지, 수많은 조력자가 배후에서 널 도왔겠지.",
  ui_story_5071_50711502_17_dialog_content = "나를 적대하는 자들이 널 이용한 것이다... 그들을 결코 용서하지 않겠다.",
  ui_story_5071_50711502_18_dialog_content = "......",
  ui_story_5071_50711502_19_dialog_content = "네가 말하지 않더라도 내가 직접 조사할 것이다.",
  ui_story_5071_50711502_20_dialog_content = "약속하지, 넌 공정한 재판을 받게 될 거다.",
  ui_story_5071_50711502_21_dialog_content = "위선 떨지 마! 역겨워서 참을 수가 없으니까!",
  ui_story_5071_50711502_22_dialog_content = "배런을 죽이고... 배런의 모든 걸 빼앗아 간 주제에...\n아무런 심판도 받지 않았으면서...",
  ui_story_5071_50711502_23_dialog_content = "왜 우리가 당신의 희생양이 돼야 하는 거야?!",
  ui_story_5071_50711502_24_dialog_content = "당신을 저주할 거야! 영원히 심연에 빠져버려!",
  ui_story_5071_50711502_25_dialog_content = "...오래전, 배런과 나는 움브라톤에도 이곳만의 법률이 생길 그날을 기대했다.",
  ui_story_5071_50711502_26_dialog_content = "배런은 질서를 갈망했고, 그 꿈을 내게 맡겼지.",
  ui_story_5071_50711502_27_dialog_content = "할 수만 있다면, 그 짐을 네가 짊어지게 하고 싶진 않았다.",
  ui_story_5071_50711502_28_dialog_content = "배런...",
  ui_story_5071_50711502_29_dialog_content = "네 대륙상회는 배런의 꿈을 위한 것이었겠지.",
  ui_story_5071_50711502_30_dialog_content = "설령 네 마음은 증오로 가득 차 있었더라도, 사랑에서 비롯된 순수함도 남아 있었을 거다.",
  ui_story_5071_50711502_31_dialog_content = "됐어, 더 듣고 싶지 않으니까...",
  ui_story_5071_50711502_32_dialog_content = "오랜 세월 그림자 속에 몸을 숨겨오면서,\n나는 오래전부터 구제할 수 있는 자와 없는 자를 분간해 왔다.",
  ui_story_5071_50711502_33_dialog_content = "「에바」, 네 마음속에는 아직 마지막 「순수함」이 남아 있다.",
  ui_story_5071_50711502_34_dialog_content = "그것은 과거의 네가 남긴 그림자다.",
  ui_story_5071_50711502_35_dialog_content = "그러니 지금 여기서 네게 맹세하지.",
  ui_story_5071_50711502_36_dialog_content = "언젠가 네가 모든 속죄를 마치고, 나 역시 움브라톤의 개혁을 끝내는 그날이 오면...",
  ui_story_5071_50711502_37_dialog_content = "그때는 내 목숨을 얼마든지 가져가도 좋다.",
  ui_story_5071_50711502_38_dialog_content = "당신...",
  ui_story_5071_50711502_39_dialog_content = "자, 이제 그만~ 치안대 사람들이 구조대랑 같이 오고 있네요~",
  ui_story_5071_50711502_40_dialog_content = "나머지 이야기는 그 사람들한테 하는 게 어때?",
  ui_story_5071_50711502_41_dialog_content = "...이거 놔!",
  ui_story_5071_50711502_42_dialog_content = "내가 뭘 어쨌는데?!",
  ui_story_5071_50711502_43_dialog_content = "진짜 원흉은 당신들 눈앞에 있잖아!",
  ui_story_5071_50711502_44_dialog_content = "저 추악한 흉터로 가득한 몸뚱이를 보고도 모르겠어?!",
  ui_story_5071_50711502_45_dialog_content = "저 남자야말로 움브라톤의 가장 큰 죄인이라고!",
  ui_story_5071_50711502_46_dialog_content = "당신... 자기 어머니가 어떻게 죽었는지 잊었어?!",
  ui_story_5071_50711502_47_dialog_content = "......",
  ui_story_5071_50711502_48_dialog_content = "이런 멘트는 나도 참 어색하긴 한데...\n치안대 여러분~ 여기예요~ 빨리 오세요~",
  ui_story_5071_50711502_49_dialog_content = "당신들 이미 저 남자의 본모습을 봤잖아!",
  ui_story_5071_50711502_50_dialog_content = "저 남자 곁에 남은 사람들, 당신들 모두... 두려워하는 게 좋을 거야!",
  ui_story_5071_50711502_51_dialog_content = "언젠가는 모든 진상이 밝혀질 테니까!",
  ui_story_5071_50711502_52_dialog_content = "<color=#FFB400>케이드! 당신을 저주할 거야──!</color>",
  ui_story_5071_50711601_1_dialog_content = "이본 여사님의 사인이 드디어 밝혀졌어. 역시나 「독액」이 원인이었어.\n참 열정적인 분이셨는데, 한스티에게 살해당하다니...",
  ui_story_5071_50711601_2_dialog_content = "진작 더 많이 이야기를 나누지 못해서 유감이야.",
  ui_story_5071_50711601_3_dialog_content = "정말 좋은 분이셨는데...",
  ui_story_5071_50711601_4_dialog_content = "버질 그 에는 며칠째 밥도 잘 못 먹고 잠도 잘 못 자고 있어.\n휴, 버질의 슬픔을 덜어 주려면 역시 일감을 더 늘리는 수밖에 없겠어.",
  ui_story_5071_50711601_5_dialog_content = "샤엘 씨, 그런 걸 보통 「착취」라고 하지 않나요...",
  ui_story_5071_50711601_6_dialog_content = "참, 이본 여사님을 추모하는 뜻에서 여사님의 작품을 재발간했어. 이게 1쇄 발행본이야.",
  ui_story_5071_50711601_7_dialog_content = "그럼 부탁 좀 할게. 이거 몇 권만 좀 섀도우마스터한테 전해 줘.",
  ui_story_5071_50711601_8_dialog_content = "이스타반 씨도 기뻐하실 거예요... 어? 샤엘 씨 뒤에 있는 책들은 뭐예요?",
  ui_story_5071_50711601_9_dialog_content = "아! 이거? 이건 《레드 머큐리》 신장판이야. 난 역시 이 책이 제일 마음에 들거든.",
  ui_story_5071_50711601_X9_dialog_content = "표지에 백합이 있으니까 깔끔하고 예쁘네요...\n머큐리 부인... 샤엘 씨 어머님이랑 잘 어울려요...",
  ui_story_5071_50711601_X10_dialog_content = "영원히 사라지지 않는 기억, 위대한 사랑, 진심 어린 축복... 그게 바로 백합의 꽃말이니까.",
  ui_story_5071_50711601_X11_dialog_content = "...내게 묻고 싶은 건 없나?",
  ui_story_5071_50711601_X12_dialog_content = "제 어머니에 대한 일은 이미 한 번 말씀해 주셨잖아요?",
  ui_story_5071_50711601_X13_dialog_content = "그렇지.",
  ui_story_5071_50711601_X14_dialog_content = "혹시 더 보충해 줄 내용이라도 있는 건가요?",
  ui_story_5071_50711601_X15_dialog_content = "...진실이란 때로는 칼날처럼 날카롭다.\n그럴 때면 난 오만하게 선의의 거짓말을 선택하곤 하지.",
  ui_story_5071_50711601_X16_dialog_content = "네 어머니는 확실히 병으로 세상을 떠났다...\n네 행방을 찾느라 심신이 상했고, 그리움이 병이 되었던 거다.",
  ui_story_5071_50711601_X17_dialog_content = "그리고 네 어머니의 문병을 갔을 때, 그녀에게서 마지막 부탁을 받았다.",
  ui_story_5071_50711601_X18_dialog_content = "그것은 딸을 향한 한 어머니의 위대한 사랑이었지.\n난 네가 양심의 가책을 느끼지 않았으면 했다... 그래서...",
  ui_story_5071_50711601_X19_dialog_content = "그럼 그것도 저한테 또 빚을 지신 걸로 쳐도 될까요?",
  ui_story_5071_50711601_X20_dialog_content = "...농담이에요. 고마워요, 「어르신」.",
  ui_story_5071_50711601_X21_dialog_content = "그래도 다음부턴 그런 독단적인 결정은 하지 마세요.",
  ui_story_5071_50711601_X22_dialog_content = "움브라톤 사람이라면 사업에 신용이 있어야죠.",
  ui_story_5071_50711601_X23_dialog_content = "하하, 샤엘 회장의 황금 같은 조언이니 꼭 기억해 두도록 하지.",
  ui_story_5071_50711601_X24_dialog_content = "딸도 당신처럼 이런 백합이 어울리는 걸 아시면 어머니도 분명히 기뻐하실 거야!",
  ui_story_5071_50711601_10_dialog_content = "뭐, 정작 지금은 눈코 뜰 새 없이 바빠서, 책을 다시 읽을 시간이 안 나는 게 아쉽지만.",
  ui_story_5071_50711601_11_dialog_content = "비공정 일은 정말 유감이에요...",
  ui_story_5071_50711601_12_dialog_content = "괜찮아, 이런 나쁜 일을 겪은 게 처음도 아닌걸. 사업이란 벌 때도 있고 잃을 때도 있는 법이야.\n그건 사업하는 사람들의 숙명이거든.",
  ui_story_5071_50711601_13_dialog_content = "그리고 난 자유로우니까, 비공정에 의지하지 않아도 곳곳에서 내 사업을 할 수 있어.",
  ui_story_5071_50711601_14_dialog_content = "그렇게 말씀하시니까 저도 기쁘네요. 샤엘 씨가 긍정적인 사람이라서 다행이에요!",
  ui_story_5071_50711601_15_dialog_content = "PlayerName 네가 위로해 주니까 나도 기쁜걸...\n근데 콜로서스를 끌고 와서 나한테 그런 소릴 하니까 솔직히 좀 화나네?",
  ui_story_5071_50711601_16_dialog_content = "아, 하하... 죄송해요! 그럼 이스타반 씨한테 가 볼게요──!",
  ui_story_5071_50711601_17_dialog_content = "휴, 정말...",
  ui_story_5071_50711601_18_dialog_content = "그래, 마음껏 자랑스럽게 하늘을 누벼 줘. 우리 꿈과 함께...",
  ui_story_5071_50711601_19_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5071_50711601_20_dialog_content = "들어와라.",
  ui_story_5071_50711601_21_dialog_content = "저예요, 이스타반 씨. 책을 전해 드리려고... 아?",
  ui_story_5071_50711601_22_dialog_content = "뭐지? 자네가 놀랄 정도의 모습은 아닐 텐데.",
  ui_story_5071_50711601_23_dialog_content = "그 모습은...",
  ui_story_5071_50711601_24_dialog_content = "그림자 속의 초연은 아직 가라앉지 않았다.\n싸움에 임하려는 자라면 마땅한 자태라고 생각했을 뿐이다만.",
  ui_story_5071_50711601_25_dialog_content = "...책은 여기 둘게요.",
  ui_story_5071_50711601_26_dialog_content = "샤엘은 늘 자네에게 이런 심부름을 시키는군... 고맙다.",
  ui_story_5071_50711601_27_dialog_content = "요즘도 악몽을 꾸시나요?",
  ui_story_5071_50711601_28_dialog_content = "하하, 악몽을 어떻게 정의하느냐에 따라 다르겠지.\n전에는 양심의 가책에 얽매여 뒤틀린 과거에 대한 꿈만 꿨었다.",
  ui_story_5071_50711601_29_dialog_content = "하지만 이젠 꿈에서 날것 그대로의 진실을 보고 있다.\n자네 생각에는 이게 좋은 꿈인 것 같나, 악몽인 것 같나.",
  ui_story_5071_50711601_30_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5071_50711601_31_dialog_content = "눈치 볼 필요 없다. 여기 있어라.",
  ui_story_5071_50711601_32_dialog_content = "들어와라.",
  ui_story_5071_50711601_33_dialog_content = "이스타반 님! 이스타반 님!",
  ui_story_5071_50711601_34_dialog_content = "친애하는 이스타반 님... 부디 제 존경을 받아 주십시오. 아직 절 기억하고 계시겠지요...?\n우린 한때 협력 파트너였으니 말입니다.",
  ui_story_5071_50711601_35_dialog_content = "아직 우리의 우정을 기억하고 계신다면, 부디 제 진심 어린 참회를 들어 주십시오...",
  ui_story_5071_50711601_36_dialog_content = "말해라.",
  ui_story_5071_50711601_37_dialog_content = "부유 비공정에서 확실히 전 조금 「동요」했고, 나쁜 무리들과 부적절한 행동을 했습니다...",
  ui_story_5071_50711601_38_dialog_content = "그리고 이번에 총상회에서 놈들을 조사하면서 저희 가문 상회까지...\n부디 절 믿어 주십시오! 전 지금 진심으로 뉘우치고 있습니다!",
  ui_story_5071_50711601_39_dialog_content = "그러니... 부디 제게 자비와 아량을 베풀어, 제가 총상회에 복귀할 수 있게 해 주십시오...",
  ui_story_5071_50711601_40_dialog_content = "자네는 우리가 파트너라고 말했지.",
  ui_story_5071_50711601_41_dialog_content = "하지만 개혁을 시작했을 때 자네는 내 곁에 서기는커녕, 오히려 그림자의 시선을 피했다.",
  ui_story_5071_50711601_42_dialog_content = "아, 아닙니다...",
  ui_story_5071_50711601_43_dialog_content = "자넨 내게 등을 돌리고, 자네의 친구들과 「검은 사업」으로 큰돈을 벌었지...",
  ui_story_5071_50711601_44_dialog_content = "자네가 더없이 잘나갈 무렵엔, 내 제안을 전혀 고려하지 않았지.",
  ui_story_5071_50711601_45_dialog_content = "그런데 이제 총상회의 제재를 받고서야 날 생각해 내고, 그림자의 용서를 바라는 건가.",
  ui_story_5071_50711601_46_dialog_content = "그, 그건 그러니까...",
  ui_story_5071_50711601_47_dialog_content = "핑계 댈 필요 없다.\n자네는 날 파트너로 생각한 적도 없고, 날 존경한 적도 더더욱 없으니 말이야.",
  ui_story_5071_50711601_48_dialog_content = "자네 마음속의 「섀도우마스터」는 한낱 장애물에 불과했겠지.",
  ui_story_5071_50711601_49_dialog_content = "그, 그렇지 않습니다... 제발 제 이야기 좀 들어 주십시오.",
  ui_story_5071_50711601_50_dialog_content = "잘못을 뉘우치고 새사람이 되겠습니다!\n다시는 그런 자들과 결탁하지 않고, 「검은 사업」도 포기하겠습니다!",
  ui_story_5071_50711601_51_dialog_content = "그러니 부디 총상회에 말씀 좀 해 주십시오... 저희 밥줄만은 끊지 말아 달라고 말입니다!\n이렇게 부탁드립니다, 섀도우마스터!",
  ui_story_5071_50711601_52_dialog_content = "돌아가라.",
  ui_story_5071_50711601_53_dialog_content = "그럼... 저희 가문의 상회는 어떻게... 섀도우마스터...?",
  ui_story_5071_50711601_54_dialog_content = "......",
  ui_story_5071_50711601_55_dialog_content = "예! 예! 갑니다! 지금 바로 가겠습니다...!",
  ui_story_5071_50711601_56_dialog_content = "우스운 꼴을 보였군.",
  ui_story_5071_50711601_57_dialog_content = "<color=#FFB400>(전보다 위압감이 더 강렬하잖아?!)</color>",
  ui_story_5071_50711601_58_dialog_content = "솔직히 말씀드리자면... 이스타반 씨가 그러시는 걸 보니까 좀 무서웠어요...",
  ui_story_5071_50711601_59_dialog_content = "하하, 그리 어려워하지 않았으면 좋겠군.\n자네에게 같이 체스도 두자고 할 생각이었는데 말이야.",
  ui_story_5071_50711601_60_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_5071_50711601_61_dialog_content = "아버님.",
  ui_story_5071_50711601_62_dialog_content = "...들어와라.",
  ui_story_5071_50711601_63_dialog_content = "투표 결과가 나왔어요. 개혁안에 반대하는 사람은 아무도 없었어요.",
  ui_story_5071_50711601_64_dialog_content = "사람들은 지금 내가 강압적이라고 생각하겠지?",
  ui_story_5071_50711601_65_dialog_content = "바라던 바는 아니었다만, 이젠 정말 저들 말대로 돼 버렸군.",
  ui_story_5071_50711601_66_dialog_content = "하하, 뭐, 나쁘진 않겠지. 골치 아픈 일이 간단해졌으니 말이야.",
  ui_story_5071_50711601_67_dialog_content = "그리고 한스티의 배후에 대한 조사도 어느 정도 결과가 나왔어요...",
  ui_story_5071_50711601_68_dialog_content = "놈들은 이번 한 번으로 끝내진 않을 거예요. 이건 관련 자료예요.",
  ui_story_5071_50711601_69_dialog_content = "얼마든지 오라고 해라.",
  ui_story_5071_50711601_70_dialog_content = "난 이미 싸울 준비도 되어 있다. 숨는 일은 없을 것이다.",
  ui_story_5071_50711601_71_dialog_content = "지금의 움브라톤은 더는 나약하지 않다. 그렇다면 우리도 손님을 맞이할 준비를 해야겠군.",
  ui_story_5071_50711601_72_dialog_content = "클레이튼.",
  ui_story_5071_50711601_73_dialog_content = "네, 말씀하십시오.",
  ui_story_5071_50711601_74_dialog_content = "준비하라고 전해라. 이제 바빠질 때가 됐다.",
  ui_story_5071_50711601_75_dialog_content = "알겠습니다. 지금 바로 연회를 준비하겠습니다.",
  ui_story_5071_50711601_76_dialog_content = "아버님, 그러지 말고 일을 좀 줄이세요.",
  ui_story_5071_50711601_77_dialog_content = "부상에, 중독까지, 그러고도 안 쉬시면 어떡해요?",
  ui_story_5071_50711601_78_dialog_content = "(어라? 베델이 이스타반 씨 대하는 태도도 왠지 달라진 것 같은데?\n이러니까 뭔가 평범한 부녀 사이처럼 보이네...)",
  ui_story_5071_50711601_79_dialog_content = "난 아직 안 늙었다. 좀 더 움직이고 싶구나.",
  ui_story_5071_50711601_80_dialog_content = "죄송한데, 그럼 저 먼저 실례할게요...",
  ui_story_5071_50711601_81_dialog_content = "아직 많이 바쁘신 것 같아서요. 방해 안 하는 게 좋을 것 같아요.",
  ui_story_5071_50711601_82_dialog_content = "자네와 체스를 두려고 했는데, 아쉽게 됐군.",
  ui_story_5071_50711601_83_dialog_content = "그럼 다음에 보도록 하지.",
  ui_story_5071_50711601_84_dialog_content = "네, 안녕히 계세요!",
  ui_story_5071_50711601_85_dialog_content = "당신, 아버님한테 뭘 한 거죠?",
  ui_story_5071_50711601_86_dialog_content = "너무 많이 변하셔서 다들 깜짝 놀랐다고요.",
  ui_story_5071_50711601_87_dialog_content = "아냐, 난 아무것도 안 했어! 전부 다 이스타반 씨가 알아서 깨달으신 거지.",
  ui_story_5071_50711601_88_dialog_content = "...그런가요?",
  ui_story_5071_50711601_89_dialog_content = "그것도 나쁘지 않네요. 아버님께서 훨씬 솔직해지셨거든요.\n덕분에 저도 아버님을 더 잘 이해할 수 있어서 기뻐요.",
  ui_story_5071_50711601_90_dialog_content = "베델 님, 들어오는 통신이 많아졌어요. 베델 님께서 진행해 주셔야 할 새 회의도 있고요.",
  ui_story_5071_50711601_91_dialog_content = "지금 바로 가죠. PlayerName, 고마워요. 그럼 다음에 봐요.",
  ui_story_5071_50711601_92_dialog_content = "응, 다음에 봐.",
  ui_story_5071_50711601_93_dialog_content = "빨리빨리, 서둘러! 그 정도 기운 가지고 되겠어? 보스가 아직 우릴 기다리고 계신다고!",
  ui_story_5071_50711601_94_dialog_content = "파이팅! 힘내라~",
  ui_story_5071_50711601_95_dialog_content = "(다들 기운이 넘치네...)",
  ui_story_5071_50711601_96_dialog_content = "또 누구랑 싸워야 되는 건진 모르겠지만, 일단 달려!",
  ui_story_5071_50711601_97_dialog_content = "(햇살이 참 밝네. 움브라톤에 원래 해가 이렇게 밝게 떴었나?)",
  ui_story_5071_50711601_98_dialog_content = "조심 좀 해! 아무리 학교 지을 자재를 옮긴다지만, 교통안전은 지켜야지!",
  ui_story_5071_50711601_99_dialog_content = "(햇살 아래의 움브라톤은 정말 아름답네...)",
  ui_story_5071_50711601_100_dialog_content = "서둘러! 얼른 손님 물건을 수송 차량에 실어!",
  ui_story_5071_50711601_101_dialog_content = "우리 움브라톤 상회 일처리가 느리다고 생각하게 만들지 말라고!",
  ui_story_5071_50711601_102_dialog_content = "(이렇게 맑은 날씨라면 역시 제대로 즐겨 줘야겠지?)",
  ui_story_5071_50711601_103_dialog_content = "(바이스한테 영화나 보러 가자고 할까? 근데 표를 구할 수 있을지 모르겠네...)",
  ui_story_5071_50711601_104_dialog_content = "(이 책은...)",
  ui_story_5071_50711601_105_dialog_content = "(그렇군... 햇살 아래에서 음미하며 읽을 가치가 있는 옛날이야기인가.)",
  ui_story_5071_50711601_106_dialog_content = "(훗, 마침 날씨도 좋고, 고향도 반짝이고 있군...)",
  ui_story_5071_50711601_107_dialog_content = "(마치 우리의 꿈처럼 빛나고 있다.)",
  ui_story_5071_50711601_108_dialog_content = "안 그런가? 친구.",
  ui_story_5071_50711601_109_dialog_content = "일을 꽤 잘 처리했네. 이제야 좀 그럴싸해졌잖아.",
  ui_story_5071_50711601_110_dialog_content = "여기까지 오느라 내가 그동안 얼마나 배웠는지 아나?",
  ui_story_5071_50711601_111_dialog_content = "그럼 내가 썩 괜찮은 선생이었던 모양이야.",
  ui_story_5071_50711601_112_dialog_content = "정말 아름다워... 우리의 고향이 이렇게나 빛나는 곳이었다니...",
  ui_story_5071_50711601_113_dialog_content = "앞으로 움브라톤의 꿈은 더 견고해질 거다. 그러니...",
  ui_story_5071_50711601_114_dialog_content = "언젠가는 분명히 날개를 펴고 하늘로 날아오를 수 있겠지.",
  ui_story_5071_50711601_115_dialog_content = "그럼, 그날을 기대하고 있을 테니까."
}
return config
